  // Image pixel data is stored once per image id here, so history snapshots can
  // reference images by id instead of carrying (and re-serializing) base64 copies.
  const imageDataById = new Map();

  // ---- src/project/grade-rules.js ----
// Grade-rules v2 data model + custom-POM registry lookup.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Grade rules v2 container (US-011) ----------------------------------
  // One persisted object holds every TD grading override:
  //   steps        — v1 constant-step overrides { [pom]: {step, hold} }
  //                  (step in the project unit, as the Size Run dialog wrote)
  //   alpha, depth — per-POM per-size delta overrides { [pom]: {[size]: Δ} },
  //                  stored in INCHES (unit-independent, converted at use like
  //                  the built-ins). Written by the Grading dialog (S3).
  //   depthOffsets — the former state.depthRules { [pom]: {offset} } (project
  //                  unit), absorbed here so one field persists all grading.
  function makeEmptyGradeRulesV2() {
    return { version: 2, steps: {}, alpha: {}, depth: {}, depthOffsets: {} };
  }

  // Lossless upgrade of persisted grading state to the v2 container.
  // Accepts: a v2 container (returned normalized), a v1 map of
  // { [pom]: {step, hold} } entries, or null/garbage (fresh container).
  // legacyDepthRules is the old separate state.depthRules field from
  // pre-US-011 files; it folds into depthOffsets.
  function migrateGradeRulesV2(raw, legacyDepthRules) {
    const out = makeEmptyGradeRulesV2();
    if (raw && typeof raw === 'object') {
      if (raw.version === 2) {
        for (const k of ['steps', 'alpha', 'depth', 'depthOffsets']) {
          if (raw[k] && typeof raw[k] === 'object') out[k] = JSON.parse(JSON.stringify(raw[k]));
        }
      } else {
        // v1: version-less map of per-POM {step, hold} overrides.
        for (const key of Object.keys(raw)) {
          const e = raw[key];
          if (e && typeof e === 'object' && ('step' in e || 'hold' in e)) {
            out.steps[key] = { ...e };
          }
        }
      }
    }
    if (legacyDepthRules && typeof legacyDepthRules === 'object') {
      for (const key of Object.keys(legacyDepthRules)) {
        const e = legacyDepthRules[key];
        if (e && typeof e === 'object' && e.offset != null && out.depthOffsets[key] == null) {
          out.depthOffsets[key] = { ...e };
        }
      }
    }
    return out;
  }

  // Custom POM registry lookup (US-011 S4). Custom POMs (17+) live in
  // state.customPoms — never in the 18-POM rule JSON (ADR 0018).
  function customPomEntry(pomKey) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    if (!key) return null;
    return (state.customPoms || []).find(p => String(p.pom) === key) || null;
  }

  // Next free custom POM number: one past the highest of 16 and any
  // existing custom or annotation label number.
  function nextCustomPomNumber() {
    // Core template now reserves 1..18 (US-037: neckline 17, armhole 18);
    // custom POMs start at 19. See ADR 0032.
    let max = 18;
    for (const p of state.customPoms || []) {
      const n = Number(p.pom);
      if (Number.isFinite(n) && n > max) max = n;
    }
    for (const ann of state.annotations || []) {
      const n = Number(ann.text != null ? ann.text : NaN);
      if (Number.isFinite(n) && n > max) max = n;
    }
    return max + 1;
  }

  // ---- src/auto/telemetry/session-stats.js ----
// Pure telemetry summarizer for Detect-to-POM speed sessions.
// Source part for app.js. Run `npm run build` after editing.

  function summarizeAutoTelemetryEvents(events) {
    const rows = Array.isArray(events)
      ? events.slice().filter(e => e && typeof e.event === 'string')
      : [];
    rows.sort((a, b) => eventTime(a) - eventTime(b));

    const first = (name) => rows.find(e => e.event === name) || null;
    const last = (name) => {
      for (let i = rows.length - 1; i >= 0; i -= 1) {
        if (rows[i].event === name) return rows[i];
      }
      return null;
    };

    const imageLoaded = first('image_loaded');
    const detectClicked = first('detect_clicked');
    const detectFinished = last('detect_finished');
    const applyStarted = first('apply_started');
    const sessionDone = last('auto_session_done') || last('apply_finished') || last('draft_applied');

    const draggedAnchors = new Set();
    const editedDrafts = new Set();
    let discardedDrafts = 0;
    let appliedDrafts = 0;
    let approvedDrafts = 0;

    for (const row of rows) {
      if (row.event === 'anchor_dragged') {
        draggedAnchors.add(row.anchor_id || row.anchor_kind || String(eventTime(row)));
      } else if (row.event === 'draft_edited') {
        editedDrafts.add(row.draft_id || row.pom_id || String(eventTime(row)));
      } else if (row.event === 'draft_review_only') {
        editedDrafts.add(row.draft_id || row.pom_id || String(eventTime(row)));
        discardedDrafts += 1;
      } else if (row.event === 'draft_discarded') {
        discardedDrafts += Math.max(1, Number(row.count) || 0);
      } else if (row.event === 'draft_applied') {
        appliedDrafts += Math.max(1, Number(row.count) || 1);
      } else if (row.event === 'draft_approved') {
        approvedDrafts += 1;
      }
    }

    const detectMs = durationBetween(detectClicked, detectFinished);
    const loadToDetectMs = durationBetween(imageLoaded, detectFinished);
    const editMs = durationBetween(detectFinished, sessionDone);
    const applyMs = durationBetween(applyStarted, sessionDone);
    const anchorsDragged = draggedAnchors.size;
    const draftsEdited = editedDrafts.size;
    const touchless = !!sessionDone
      && anchorsDragged === 0
      && draftsEdited === 0
      && discardedDrafts === 0;

    return {
      detect_ms: detectMs,
      load_to_detect_ms: loadToDetectMs,
      edit_ms: editMs,
      apply_ms: applyMs,
      anchors_dragged: anchorsDragged,
      drafts_edited: draftsEdited,
      drafts_discarded: discardedDrafts,
      drafts_approved: approvedDrafts,
      drafts_applied: appliedDrafts,
      touchless,
      completed: !!sessionDone,
    };
  }

  function summarizeAutoTelemetrySessions(sessions) {
    const rows = Array.isArray(sessions)
      ? sessions.slice().filter(Boolean)
      : [];
    const normalized = rows.map(session => {
      const summary = session.summary || summarizeAutoTelemetryEvents(session.events || []);
      return Object.assign({}, session, { summary });
    });
    const summaries = normalized.map(s => s.summary || {});
    return {
      sessions: normalized,
      count: normalized.length,
      medians: {
        detect_ms: telemetryMedian(summaries.map(s => s.detect_ms)),
        edit_ms: telemetryMedian(summaries.map(s => s.edit_ms)),
        apply_ms: telemetryMedian(summaries.map(s => s.apply_ms)),
        anchors_dragged: telemetryMedian(summaries.map(s => s.anchors_dragged)),
        drafts_edited: telemetryMedian(summaries.map(s => s.drafts_edited)),
        drafts_discarded: telemetryMedian(summaries.map(s => s.drafts_discarded)),
      },
      touchlessCount: summaries.filter(s => s.touchless).length,
    };
  }

  function eventTime(event) {
    const t = Number(event && event.timestamp);
    return Number.isFinite(t) ? t : 0;
  }

  function durationBetween(startEvent, endEvent) {
    if (!startEvent || !endEvent) return null;
    const start = eventTime(startEvent);
    const end = eventTime(endEvent);
    if (!start || !end || end < start) return null;
    return Math.round(end - start);
  }

  function telemetryMedian(values) {
    const nums = values
      .map(v => Number(v))
      .filter(v => Number.isFinite(v));
    if (!nums.length) return null;
    nums.sort((a, b) => a - b);
    const mid = Math.floor(nums.length / 2);
    return nums.length % 2 ? nums[mid] : (nums[mid - 1] + nums[mid]) / 2;
  }

  // ---- src/auto/telemetry/session-timer.js ----
// Detect-to-POM session telemetry. Stores the active event stream in
// sessionStorage and completed sessions in localStorage["auto_telemetry_log"].
// Source part for app.js. Run `npm run build` after editing.

  const AUTO_TELEMETRY_LOG_KEY = 'auto_telemetry_log';
  const AUTO_TELEMETRY_SESSION_KEY = 'auto_telemetry_current';
  const AUTO_TELEMETRY_CAP = 200;

  function recordAutoTelemetryEvent(event, details = {}) {
    if (!event) return null;
    const timestamp = Date.now();
    const entry = makeAutoTelemetryEvent(event, details, timestamp);
    let session = readCurrentAutoTelemetrySession();

    if (!session && event !== 'image_loaded') return null;

    if (event === 'image_loaded') {
      session = {
        id: makeAutoTelemetrySessionId(timestamp),
        sketch_id: entry.sketch_id || null,
        started_at: new Date(timestamp).toISOString(),
        completed_at: null,
        events: [],
      };
    }

    if (!session.sketch_id && entry.sketch_id) session.sketch_id = entry.sketch_id;
    session.events.push(entry);

    if (event === 'auto_session_done') {
      session.completed_at = new Date(timestamp).toISOString();
      session.summary = summarizeAutoTelemetryEvents(session.events);
      appendAutoTelemetrySession(session);
      clearCurrentAutoTelemetrySession();
    } else {
      writeCurrentAutoTelemetrySession(session);
    }
    return entry;
  }

  function makeAutoTelemetryEvent(event, details, timestamp) {
    const sourceImage = details && details.sourceImageId != null
      ? getImageById(details.sourceImageId)
      : (typeof pickAutoSourceImage === 'function' ? pickAutoSourceImage() : null);
    const styleId = (typeof currentStyleId === 'function') ? currentStyleId() : (state.styleId || '');
    const entry = {
      event: String(event),
      timestamp,
      at: new Date(timestamp).toISOString(),
      sketch_id: details.sketch_id || details.sourceImageId || (sourceImage && sourceImage.id) || null,
      style_id: styleId || '',
    };

    const copyFields = [
      'anchor_id', 'anchor_kind', 'pom_id', 'draft_id', 'run_id',
      'count', 'duration_ms', 'status', 'reason', 'image_width',
      'image_height', 'draft_count', 'approved_count',
    ];
    for (const key of copyFields) {
      if (details && details[key] != null) entry[key] = details[key];
    }
    return entry;
  }

  function readCurrentAutoTelemetrySession() {
    try {
      const raw = sessionStorage.getItem(AUTO_TELEMETRY_SESSION_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch (_) {
      return null;
    }
  }

  function writeCurrentAutoTelemetrySession(session) {
    try {
      sessionStorage.setItem(AUTO_TELEMETRY_SESSION_KEY, JSON.stringify(session));
    } catch (_) {
      // Telemetry is diagnostic only; quota/private-mode failures should not
      // affect drawing or detection.
    }
  }

  function clearCurrentAutoTelemetrySession() {
    try { sessionStorage.removeItem(AUTO_TELEMETRY_SESSION_KEY); } catch (_) { /* ignore */ }
  }

  function appendAutoTelemetrySession(session) {
    const log = getAutoTelemetryLog();
    log.push(session);
    const trimmed = log.slice(-AUTO_TELEMETRY_CAP);
    try {
      localStorage.setItem(AUTO_TELEMETRY_LOG_KEY, JSON.stringify(trimmed));
    } catch (_) {
      // Keep the UI fast even if localStorage is full.
    }
  }

  function getAutoTelemetryLog() {
    try {
      const raw = localStorage.getItem(AUTO_TELEMETRY_LOG_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      return Array.isArray(parsed) ? parsed : [];
    } catch (_) {
      return [];
    }
  }

  function clearAutoTelemetryLog() {
    try { localStorage.removeItem(AUTO_TELEMETRY_LOG_KEY); } catch (_) { /* ignore */ }
    clearCurrentAutoTelemetrySession();
  }

  function getAutoTelemetryReport(limit = 10) {
    const log = getAutoTelemetryLog();
    const latest = log.slice().reverse().slice(0, limit);
    return summarizeAutoTelemetrySessions(latest);
  }

  function makeAutoTelemetrySessionId(timestamp) {
    return 'auto-session-' + timestamp.toString(36) + '-' + Math.random().toString(36).slice(2, 8);
  }

  // ---- src/curves.js ----
  // ===========================================================================
  // Curve geometry. All cubic Bézier math and curved-line construction live
  // here so future curve tweaks are in one place. The build concatenates every
  // src/*.js part into one shared scope, so these are callable from
  // manual-tools.js / rendering.js without any import wiring.
  //
  //   Data model: a curved annotation is one or two cubic Bézier segments.
  //   With a middle anchor (midPoint) + its two handles (midHandleIn/Out) it's
  //   two segments joined there; otherwise a single cubic via control1/control2.
  // ===========================================================================

  // A curved line is one or more cubic Bézier segments. The floor is the
  // pen-tool single cubic (start/control1/control2/end); a TD may grow it with
  // any number of interior anchor points (US-093 / ADR 0053), each an
  // independent {point, handleIn, handleOut}, added on demand via the "Add
  // point" tool — never a structural default. Everything that samples, draws,
  // or measures a curve goes through here, so an empty/absent `points` array
  // renders byte-identical to the original two-handle model.
  //
  // The legacy midPoint/midHandleIn/midHandleOut two-segment shape (rejected
  // 2026-07-18, "rối tay cầm, khó bẻ") is unrelated to `points` and is still
  // collapsed away by ensureCurveControls before this ever sees it.
  function getCurveBeziers(ann) {
    if (!ann || ann.type !== 'curved') return [];
    if (ann.midPoint && ann.midHandleIn && ann.midHandleOut) {
      return [
        { p0: ann.start, p1: ann.control1, p2: ann.midHandleIn, p3: ann.midPoint },
        { p0: ann.midPoint, p1: ann.midHandleOut, p2: ann.control2, p3: ann.end },
      ];
    }
    const points = Array.isArray(ann.points) ? ann.points : null;
    if (!points || !points.length) {
      return [{ p0: ann.start, p1: ann.control1, p2: ann.control2, p3: ann.end }];
    }
    const segs = [];
    let p0 = ann.start, p1 = ann.control1;
    for (const pt of points) {
      segs.push({ p0, p1, p2: pt.handleIn, p3: pt.point });
      p0 = pt.point;
      p1 = pt.handleOut;
    }
    segs.push({ p0, p1, p2: ann.control2, p3: ann.end });
    return segs;
  }

  // ---- US-093 / ADR 0053: interior anchor points -----------------------
  // A "part" name is either one of the fixed fields (start/end/control1/
  // control2/midPoint/midHandleIn/midHandleOut) or "point<i>.point" /
  // "point<i>.handleIn" / "point<i>.handleOut" addressing ann.points[i]. This
  // is the one place that parses that name, so drag/nudge/readout/delete code
  // never has to know the string format.
  const CURVE_ANCHOR_PART_RE = /^point(\d+)\.(point|handleIn|handleOut)$/;

  function parseCurveAnchorPart(part) {
    const m = typeof part === 'string' && part.match(CURVE_ANCHOR_PART_RE);
    return m ? { index: Number(m[1]), field: m[2] } : null;
  }

  // Read the world position addressed by any annotation "part" name, fixed
  // field or interior anchor alike — the one generic getter drag/nudge/readout
  // code should use instead of `ann[part]` (which cannot address an anchor).
  function getAnnPartPoint(ann, part) {
    if (!ann || !part) return null;
    const anchor = parseCurveAnchorPart(part);
    if (anchor) {
      const pt = ann.points && ann.points[anchor.index];
      return pt ? pt[anchor.field] || null : null;
    }
    return ann[part] || null;
  }

  // Keep an interior anchor's two handles collinear through its point (a
  // "smooth" anchor, the TD's default per ADR 0053) by re-angling the handle
  // that was NOT just dragged to point the opposite way, preserving that
  // handle's own current distance from the point — only the angle is forced,
  // not the length. Called on every plain drag, never stored, so an anchor
  // whose pairing was broken with Alt re-smooths itself the moment either
  // handle is dragged normally again.
  function mirrorOppositeCurveHandle(pt, draggedField) {
    const otherField = draggedField === 'handleIn' ? 'handleOut' : 'handleIn';
    const other = pt[otherField];
    const dragged = pt[draggedField];
    if (!other || !dragged || !pt.point) return;
    const dx = dragged.x - pt.point.x;
    const dy = dragged.y - pt.point.y;
    const len = Math.hypot(dx, dy);
    if (len < 1e-6) return;
    const otherLen = Math.hypot(other.x - pt.point.x, other.y - pt.point.y);
    pt[otherField] = {
      x: pt.point.x - (dx / len) * otherLen,
      y: pt.point.y - (dy / len) * otherLen,
    };
  }

  // De Casteljau subdivision of a cubic Bézier at parameter t — splits one
  // curve into two that together trace the EXACT same path, which is what
  // lets "Add point" insert an anchor without changing the curve's shape.
  function subdivideCubicBezier(p0, p1, p2, p3, t) {
    const lerp = (a, b) => ({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t });
    const p01 = lerp(p0, p1), p12 = lerp(p1, p2), p23 = lerp(p2, p3);
    const p012 = lerp(p01, p12), p123 = lerp(p12, p23);
    const p0123 = lerp(p012, p123);
    return { left: [p0, p01, p012, p0123], right: [p0123, p123, p23, p3] };
  }

  // How far (world px) a sampled chord is allowed to depart from the curve it
  // stands in for. US-093 / ADR 0053 code review, 2026-08-21: this is the
  // accuracy budget of the "Add point" hit test, and it is expressed in WORLD
  // px on purpose — it has no zoom term, so it stays far below
  // handleAddPointClick's 8/state.zoom tolerance however far the TD zooms in.
  const CURVE_CHORD_TOLERANCE = 0.05;
  const CURVE_CHORD_MIN_SAMPLES = 24;
  const CURVE_CHORD_MAX_SAMPLES = 512;

  // Chord count for approximating one cubic, chosen so the chord never departs
  // from the curve by more than CURVE_CHORD_TOLERANCE. Standard flatness
  // bound: over a parameter width Δ, |curve − chord| ≤ (Δ²/8)·max|B''|, and
  // for a cubic max|B''| = 6·max(|p0−2p1+p2|, |p1−2p2+p3|). Setting Δ = 1/n
  // and solving gives the count below, so accuracy is driven by the curve's
  // actual bend rather than by a fixed number that a long curve outgrows.
  function curveChordSampleCount(seg) {
    const ax = seg.p0.x - 2 * seg.p1.x + seg.p2.x;
    const ay = seg.p0.y - 2 * seg.p1.y + seg.p2.y;
    const bx = seg.p1.x - 2 * seg.p2.x + seg.p3.x;
    const by = seg.p1.y - 2 * seg.p2.y + seg.p3.y;
    const maxSecond = 6 * Math.max(Math.hypot(ax, ay), Math.hypot(bx, by));
    const n = Math.ceil(Math.sqrt(maxSecond / (8 * CURVE_CHORD_TOLERANCE)));
    // Floor 24 matches the old fixed sample count, so nothing about WHERE an
    // anchor lands got coarser for a short curve. Cap 512 bounds the work for
    // an absurd or corrupt curve — a once-per-click handler can spend 512
    // Bézier evaluations without anyone noticing.
    return clamp(
      Number.isFinite(n) ? n : CURVE_CHORD_MIN_SAMPLES,
      CURVE_CHORD_MIN_SAMPLES,
      CURVE_CHORD_MAX_SAMPLES,
    );
  }

  // Find the closest point ON a selected curve to a click, for the "Add
  // point" tool — insertion always lands on the curve's actual path, at the
  // nearest position, never at the raw click pixel.
  //
  // US-093 / ADR 0053 code review, 2026-08-21: this used to compare the click
  // against 25 sampled VERTICES per segment, which silently rejected a dead-on
  // click on any long or zoomed-in curve. Worst-case distance from an
  // exactly-on-path click to the nearest VERTEX is half the sample spacing —
  // arcLength/48 — so a 400-world-px armhole curve reported 8.3px against
  // handleAddPointClick's 8px tolerance and the click did nothing at all.
  // Zooming in to place a bend precisely made it worse, not better: the
  // tolerance shrinks as 8/state.zoom while vertex spacing does not.
  //
  // The fix is the one isPointNearAnnotation (src/render/hit-testing.js)
  // already relies on — measure against the polyline SEGMENTS, so accuracy is
  // bounded by chord flatness instead of by sample spacing. `t` is then
  // recovered inside the winning chord from the projection parameter, so the
  // anchor still lands ON the path. Insertion is lossless at ANY t (de
  // Casteljau subdivision preserves the path exactly), so sub-sample t
  // precision decides only WHERE the anchor sits, never the curve's shape.
  function nearestPointOnCurve(ann, world) {
    const segs = getCurveBeziers(ann);
    let best = null;
    for (let s = 0; s < segs.length; s += 1) {
      const seg = segs[s];
      const samples = curveChordSampleCount(seg);
      let prev = seg.p0;
      for (let i = 1; i <= samples; i += 1) {
        const next = bezierPoint(seg.p0, seg.p1, seg.p2, seg.p3, i / samples);
        const d = pointToSegmentDistance(world, prev, next);
        if (!best || d < best.distance) {
          best = { seg, segIndex: s, samples, index: i, a: prev, b: next, distance: d };
        }
        prev = next;
      }
    }
    if (!best) return null;
    // Recover t inside the winning chord with the same clamped projection
    // parameter pointToSegmentDistance computes internally, then report the
    // point that parameter names on the CURVE (not on the chord) so the
    // caller's insertion — and the endpoint-proximity gate in front of it —
    // both work against the drawn path.
    const dx = best.b.x - best.a.x;
    const dy = best.b.y - best.a.y;
    const l2 = dx * dx + dy * dy;
    const u = l2 === 0 ? 0
      : clamp(((world.x - best.a.x) * dx + (world.y - best.a.y) * dy) / l2, 0, 1);
    const t = (best.index - 1 + u) / best.samples;
    const seg = best.seg;
    return {
      segIndex: best.segIndex,
      t,
      point: bezierPoint(seg.p0, seg.p1, seg.p2, seg.p3, t),
      distance: best.distance,
    };
  }

  // Dry-run an insertion at (segIndex, t) — subdivideCubicBezier is pure, so
  // the exact geometry insertCurveAnchorAt would write can be inspected before
  // anything is mutated. Returns null when the arguments name no split this
  // curve can take. US-093 / ADR 0053 code review, 2026-08-21.
  //
  // `minHandleSpan` is the shortest distance any of the four handles the split
  // rewrites would end up from the point it bends: the outer handle left behind
  // on the near side (left[1], off p0), the new anchor's own handleIn/handleOut
  // (left[2] / right[1], off the new point), and the outer handle on the far
  // side (right[2], off p3). handleAddPointClick's gate bounds exactly that, so
  // no caller has to relate handle clearance to anchor clearance — the ratio
  // between them is a property of this curve's control points, not a constant.
  function previewCurveAnchorInsertion(ann, segIndex, t) {
    if (!ann || ann.type !== 'curved') return null;
    const points = Array.isArray(ann.points) ? ann.points : [];
    // `segIndex` addresses getCurveBeziers' segment list, which is
    // points.length + 1 long, so anything outside [0, points.length] reads
    // points[-1] or points[points.length] and throws on `.point` / `.handleOut`.
    // That is reachable in principle, not just in theory: getCurveBeziers
    // returns TWO segments for a legacy midPoint curve while `points` is still
    // empty, so nearestPointOnCurve can hand back segIndex 1 against
    // points.length 0. No live path does today — ensureCurveControls collapses
    // midPoint on load, history restore, paste and apply, and
    // createCurvedAnnotation is born with midPoint: null — but the guard costs
    // one comparison and removes the dependency. The integer test is part of
    // the bound rather than decoration: NaN passes both range comparisons and
    // would reach points[NaN - 1].
    if (!Number.isInteger(segIndex) || segIndex < 0 || segIndex > points.length) return null;
    // t must not be exactly 0 or 1: subdivideCubicBezier then returns
    // left = [p0, p0, p0, p0] (mirrored at 1), so the split would drop
    // ann.control1 onto ann.start and put the new anchor there too, with a
    // zero-length handleIn that mirrorOppositeCurveHandle can never re-smooth
    // (it rebuilds the opposite handle at its OWN current length, and that
    // length is 0), while drawArrowheadsForCurve takes atan2(0, 0) and snaps
    // the start arrowhead to +x. Coincident points also lose every hit test to
    // the endpoint (hit-testing.js's `<=` tie rule), so that bend would be
    // gone for good. All of it is strictly a t === 0 / t === 1 hazard — for any
    // t > 0 the split control lies ON the p0->p1 segment, keeping the arrowhead
    // angle exact and both new handles proportional to t — so 1e-3 suffices
    // here. How SHORT a handle may get is `minHandleSpan` and the caller's
    // gate, not this clamp.
    const tSafe = clamp(Number.isFinite(t) ? t : 0.5, 1e-3, 1 - 1e-3);
    const p0 = segIndex === 0 ? ann.start : points[segIndex - 1].point;
    const before = segIndex === 0 ? ann.control1 : points[segIndex - 1].handleOut;
    const after = segIndex === points.length ? ann.control2 : points[segIndex].handleIn;
    const p3 = segIndex === points.length ? ann.end : points[segIndex].point;
    const { left, right } = subdivideCubicBezier(p0, before, after, p3, tSafe);
    const point = left[3];
    return {
      tSafe,
      left,
      right,
      point,
      minHandleSpan: Math.min(
        distance(left[1], p0),
        distance(left[2], point),
        distance(right[1], point),
        distance(right[2], p3),
      ),
    };
  }

  // Insert a new interior anchor by splitting segment `segIndex` (0-based,
  // matching getCurveBeziers' order) at parameter `t`. Exact — the curve's
  // drawn path is unchanged at the instant of insertion (US-093 / ADR 0053).
  // Returns the new anchor's index in ann.points, or -1 if the preview above
  // refused the arguments — in which case nothing at all was changed, ann.points
  // included. -1 can never collide with a real result, which is always the
  // accepted segIndex and therefore >= 0.
  function insertCurveAnchorAt(ann, segIndex, t) {
    const split = previewCurveAnchorInsertion(ann, segIndex, t);
    if (!split) return -1;
    const points = Array.isArray(ann.points) ? ann.points : (ann.points = []);
    const { left, right } = split;
    // Both assignments read the PRE-splice points.length, hence the splice last.
    if (segIndex === 0) ann.control1 = left[1]; else points[segIndex - 1].handleOut = left[1];
    if (segIndex === points.length) ann.control2 = right[2]; else points[segIndex].handleIn = right[2];
    points.splice(segIndex, 0, { point: split.point, handleIn: left[2], handleOut: right[1] });
    return segIndex;
  }

  // Remove one interior anchor (US-093 / ADR 0053). Unlike insertion this has
  // no exact inverse — merging two segments back into one cannot preserve
  // both exactly — so the two now-adjacent segments simply keep whatever
  // outer handles already flank the removed anchor. The TD re-drags by hand
  // if the join doesn't look right; this asymmetry (insertion is lossless,
  // deletion is not) is deliberate, not an oversight.
  function deleteCurveAnchorAt(ann, index) {
    if (!ann || !Array.isArray(ann.points)) return;
    ann.points.splice(index, 1);
  }

  // Build a smooth two-segment curve that PASSES THROUGH start, mid, end (the
  // three clicked points). Catmull-Rom with reflected endpoints: the tangent at
  // the middle is parallel to the start→end chord, so the joint stays smooth.
  function curveControlsThroughThreePoints(start, mid, end) {
    return {
      control1: { x: start.x + (mid.x - start.x) / 3, y: start.y + (mid.y - start.y) / 3 },
      midHandleIn: { x: mid.x - (end.x - start.x) / 6, y: mid.y - (end.y - start.y) / 6 },
      midPoint: { x: mid.x, y: mid.y },
      midHandleOut: { x: mid.x + (end.x - start.x) / 6, y: mid.y + (end.y - start.y) / 6 },
      control2: { x: end.x - (end.x - mid.x) / 3, y: end.y - (end.y - mid.y) / 3 },
    };
  }

  function bezierPoint(p0, p1, p2, p3, t) {
    const mt = 1 - t;
    const mt2 = mt * mt;
    const t2 = t * t;
    const a = mt2 * mt;
    const b = 3 * mt2 * t;
    const c = 3 * mt * t2;
    const d = t * t2;
    return {
      x: a * p0.x + b * p1.x + c * p2.x + d * p3.x,
      y: a * p0.y + b * p1.y + c * p2.y + d * p3.y
    };
  }

  function bezierTangent(p0, p1, p2, p3, t) {
    const mt = 1 - t;
    return {
      x: 3 * mt * mt * (p1.x - p0.x) + 6 * mt * t * (p2.x - p1.x) + 3 * t * t * (p3.x - p2.x),
      y: 3 * mt * mt * (p1.y - p0.y) + 6 * mt * t * (p2.y - p1.y) + 3 * t * t * (p3.y - p2.y)
    };
  }

  function createCurvedAnnotation(start, end, style, color = 'red', arrowType = 'double', lineWidth = DEFAULT_LINE_WIDTH, mid = null) {
    const id = state.idCounter++;
    // A curve is ONE cubic Bézier: two endpoints + two control handles
    // (control1 off start, control2 off end) — TD 2026-07-18, edited like a
    // standard pen tool. No middle anchor. A 3-click draw fits the single cubic
    // so it passes through the middle click at t=0.5; otherwise seed a default
    // bow. `midPoint`/`midHandleIn`/`midHandleOut` stay null.
    const midRaw = mid || defaultCurveMidPoint(start, end);
    const c = controlsFromMidPoint(start, end, midRaw);
    const label = computeDefaultLabelPosition({
      type: 'curved',
      start,
      end,
      control1: c.control1,
      control2: c.control2,
    });
    return {
      id,
      seq: state.nextSequence,
      type: 'curved',
      style,
      color,
      arrowType,
      lineWidth: normalizeLineWidth(lineWidth),
      start: clonePoint(start),
      end: clonePoint(end),
      midPoint: null,
      midHandleIn: null,
      midHandleOut: null,
      control1: c.control1,
      control2: c.control2,
      points: [], // US-093: interior anchors the TD adds later, on demand.
      label,
      labelManual: false,
      text: null,
      value: null,
    };
  }

  // Default bow when drawing a new curve — perpendicular offset matching the
  // pre-midPoint visual default, so new curves look identical.
  function defaultCurveMidPoint(start, end) {
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const len = Math.max(1, Math.hypot(dx, dy));
    const nx = -dy / len;
    const ny = dx / len;
    const offset = clamp(len * 0.16, 26 / state.zoom, 82 / state.zoom);
    return {
      x: (start.x + end.x) / 2 + nx * offset,
      y: (start.y + end.y) / 2 + ny * offset,
    };
  }

  // Derive cubic Bézier controls so the curve passes through `midPoint` at
  // t=0.5 with tangent parallel to the chord. Place controls symmetrically
  // at the t=1/3 and t=2/3 chord positions and lift by (4/3)·(midPoint −
  // chordMid). See B(0.5) = 0.125·S + 0.375·P1 + 0.375·P2 + 0.125·E.
  function controlsFromMidPoint(start, end, midPoint) {
    const cmx = (start.x + end.x) / 2;
    const cmy = (start.y + end.y) / 2;
    const px = (4 / 3) * (midPoint.x - cmx);
    const py = (4 / 3) * (midPoint.y - cmy);
    return {
      control1: {
        x: start.x + (end.x - start.x) / 3 + px,
        y: start.y + (end.y - start.y) / 3 + py,
      },
      control2: {
        x: start.x + 2 * (end.x - start.x) / 3 + px,
        y: start.y + 2 * (end.y - start.y) / 3 + py,
      },
    };
  }

  // Normalize a curved line to the SINGLE-CUBIC model (two endpoints + two
  // control handles) — TD 2026-07-18. New curves are born single-cubic; this
  // also collapses any legacy two-segment curve (midPoint + mid handles) from
  // older saves back to one cubic. The collapse is EXACT for curves that were
  // split by deriveMidAnchor (all auto POM curves): that split set
  // control1 = mid(start, origC1), so origC1 = 2·control1 − start (and
  // symmetrically for control2), which this inverts. Then it drops the middle
  // anchor + its handles.
  function ensureCurveControls(ann) {
    if (!ann || ann.type !== 'curved' || !ann.start || !ann.end) return;
    if (ann.midPoint) {
      if (ann.control1) {
        ann.control1 = { x: 2 * ann.control1.x - ann.start.x, y: 2 * ann.control1.y - ann.start.y };
      }
      if (ann.control2) {
        ann.control2 = { x: 2 * ann.control2.x - ann.end.x, y: 2 * ann.control2.y - ann.end.y };
      }
      ann.midPoint = null;
      ann.midHandleIn = null;
      ann.midHandleOut = null;
    }
    if (!ann.control1 || !ann.control2 ||
        !Number.isFinite(ann.control1.x) || !Number.isFinite(ann.control2.x)) {
      const m0 = defaultCurveMidPoint(ann.start, ann.end);
      const c = controlsFromMidPoint(ann.start, ann.end, m0);
      ann.control1 = c.control1;
      ann.control2 = c.control2;
    }
    // US-093: a project saved before interior anchors existed has no `points`
    // at all — default it to empty rather than treating it as missing data,
    // so getCurveBeziers/getAnnPartPoint never have to null-check twice.
    //
    // US-093 / ADR 0053 code review, 2026-08-21: validate the ENTRIES too, not
    // just the array. loadProject runs arbitrary user-supplied JSON through
    // here, and ONE truncated anchor — { point: {x, y} } with no handles, from
    // a hand edit, a half-written file, or a different build — makes
    // getCurveBeziers emit a segment whose p2 is undefined, so
    // drawAnnotationPath throws on s.p2.x inside the render pass and NOTHING
    // paints; computeDefaultLabelPosition and nearestPointOnCurve dereference
    // the same fields just as unguarded. Dropping the unusable entries beats
    // throwing for the reason normalizeNote already drops an unplaceable note
    // (US-092, project-load.js): the curve still opens, measures, and exports,
    // losing only a bend the TD can re-add with "Add point", whereas a throw
    // costs the TD the entire board. Only reassign when something was actually
    // dropped, so a clean load leaves the array identity untouched.
    if (!Array.isArray(ann.points)) {
      ann.points = [];
    } else if (ann.points.length) {
      const usable = ann.points.filter(pt => pt && isFinitePoint(pt.point)
        && isFinitePoint(pt.handleIn) && isFinitePoint(pt.handleOut));
      if (usable.length !== ann.points.length) ann.points = usable;
    }
  }

  // ---- src/geometry/math.js ----
// Pure math / geometry helpers shared across rendering, interactions,
// hit testing, and annotation builders. Source part for app.js.
// Run `npm run build` after editing.

  function midpoint(a, b) {
    return { x: (a.x + b.x) / 2, y: (a.y + b.y) / 2 };
  }

  function distance(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y);
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function clonePoint(point) {
    return { x: point.x, y: point.y };
  }

  function pointToSegmentDistance(p, a, b) {
    const l2 = (b.x - a.x) ** 2 + (b.y - a.y) ** 2;
    if (l2 === 0) return distance(p, a);
    let t = ((p.x - a.x) * (b.x - a.x) + (p.y - a.y) * (b.y - a.y)) / l2;
    t = clamp(t, 0, 1);
    const proj = { x: a.x + t * (b.x - a.x), y: a.y + t * (b.y - a.y) };
    return distance(p, proj);
  }

  // ---- src/manual/board-graphics.js ----
// US-095 / ADR 0054: non-measurement Board Graphics and path topology.
// Board Graphics deliberately live outside state.annotations: nothing in the
// POM/spec/grading/learning/Excel path reads this collection.

  const BG_MIN_CREATE_SCREEN_PX = 8;
  const BG_KAPPA = 0.5522847498307936;

  function bgPoint(x, y) { return { x: Number(x) || 0, y: Number(y) || 0 }; }
  function bgClonePoint(p) { return bgPoint(p && p.x, p && p.y); }
  function bgNextId(prefix) { return prefix + '-' + (state.idCounter++); }

  function getBoardGraphicById(id) {
    return (state.graphics || []).find(g => g.id === id) || null;
  }

  function getSelectedBoardGraphic() {
    return state.selection.kind === 'graphic' ? getBoardGraphicById(state.selection.id) : null;
  }

  function bgNormalizeNode(raw) {
    const point = bgClonePoint(raw && raw.point);
    return {
      id: String(raw && raw.id || bgNextId('bgn')),
      point,
      handleIn: bgClonePoint(raw && raw.handleIn || point),
      handleOut: bgClonePoint(raw && raw.handleOut || point),
      segmentType: raw && raw.segmentType === 'curve' ? 'curve' : 'line',
    };
  }

  function normalizeBoardGraphic(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const kind = ['rectangle', 'circle', 'hexagon'].includes(raw.shapeKind) ? raw.shapeKind : 'rectangle';
    const mode = raw.mode === 'path' ? 'path' : 'live';
    const live = raw.live || {};
    const graphic = {
      id: raw.id != null ? raw.id : bgNextId('bg'),
      shapeKind: kind,
      mode,
      color: normalizeColorKey(raw.color || 'red'),
      lineWidth: normalizeLineWidth(raw.lineWidth),
      sourceImageId: raw.sourceImageId == null ? null : raw.sourceImageId,
      live: mode === 'live' ? {
        center: bgClonePoint(live.center),
        width: Math.max(1, Number(live.width) || 1),
        height: Math.max(1, Number(live.height) || 1),
      } : null,
      subpaths: [],
    };
    if (mode === 'path') {
      graphic.subpaths = (Array.isArray(raw.subpaths) ? raw.subpaths : []).map(sp => ({
        id: String(sp && sp.id || bgNextId('bgsp')),
        closed: !!(sp && sp.closed),
        nodes: (Array.isArray(sp && sp.nodes) ? sp.nodes : []).map(bgNormalizeNode),
      })).filter(sp => sp.nodes.length >= 2);
    }
    return graphic;
  }

  function normalizeBoardGraphics(list) {
    return (Array.isArray(list) ? list : []).map(normalizeBoardGraphic).filter(Boolean);
  }

  function bgBoxFromDrag(kind, start, current, shiftKey, altKey) {
    let dx = current.x - start.x;
    let dy = current.y - start.y;
    if (shiftKey || kind === 'circle' || kind === 'hexagon') {
      const side = Math.min(Math.abs(dx), Math.abs(dy));
      dx = (dx < 0 ? -1 : 1) * side;
      dy = (dy < 0 ? -1 : 1) * side;
    }
    let x1 = start.x, y1 = start.y, x2 = start.x + dx, y2 = start.y + dy;
    if (altKey) { x1 = start.x - dx; y1 = start.y - dy; }
    return {
      x: Math.min(x1, x2), y: Math.min(y1, y2),
      width: Math.abs(x2 - x1), height: Math.abs(y2 - y1),
    };
  }

  function bgTopImageAt(point) {
    for (let i = state.images.length - 1; i >= 0; i -= 1) {
      const im = state.images[i];
      if (point.x >= im.x && point.x <= im.x + im.width && point.y >= im.y && point.y <= im.y + im.height) return im;
    }
    return null;
  }

  function createBoardGraphicFromDrag(kind, start, current, shiftKey, altKey) {
    const box = bgBoxFromDrag(kind, start, current, shiftKey, altKey);
    if (Math.max(box.width, box.height) * state.zoom < BG_MIN_CREATE_SCREEN_PX) return null;
    const center = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
    const owner = bgTopImageAt(center);
    return normalizeBoardGraphic({
      id: bgNextId('bg'), shapeKind: kind, mode: 'live', color: state.drawColor,
      lineWidth: state.lineWidth, sourceImageId: owner ? owner.id : null,
      live: { center, width: box.width, height: box.height },
    });
  }

  function bgNode(point, segmentType, handleIn, handleOut) {
    return bgNormalizeNode({ id: bgNextId('bgn'), point, segmentType, handleIn: handleIn || point, handleOut: handleOut || point });
  }

  function convertBoardGraphicToPath(graphic) {
    if (!graphic || graphic.mode === 'path' || !graphic.live) return false;
    const c = graphic.live.center, w = graphic.live.width, h = graphic.live.height;
    const rx = w / 2, ry = h / 2;
    let nodes;
    if (graphic.shapeKind === 'circle') {
      nodes = [
        bgNode({ x: c.x, y: c.y - ry }, 'curve', { x: c.x - BG_KAPPA * rx, y: c.y - ry }, { x: c.x + BG_KAPPA * rx, y: c.y - ry }),
        bgNode({ x: c.x + rx, y: c.y }, 'curve', { x: c.x + rx, y: c.y - BG_KAPPA * ry }, { x: c.x + rx, y: c.y + BG_KAPPA * ry }),
        bgNode({ x: c.x, y: c.y + ry }, 'curve', { x: c.x + BG_KAPPA * rx, y: c.y + ry }, { x: c.x - BG_KAPPA * rx, y: c.y + ry }),
        bgNode({ x: c.x - rx, y: c.y }, 'curve', { x: c.x - rx, y: c.y + BG_KAPPA * ry }, { x: c.x - rx, y: c.y - BG_KAPPA * ry }),
      ];
    } else if (graphic.shapeKind === 'hexagon') {
      nodes = [];
      const radius = Math.min(rx, ry);
      for (let i = 0; i < 6; i += 1) {
        const a = -Math.PI / 2 + i * Math.PI / 3;
        const p = { x: c.x + Math.cos(a) * radius, y: c.y + Math.sin(a) * radius };
        nodes.push(bgNode(p, 'line'));
      }
    } else {
      nodes = [
        bgNode({ x: c.x - rx, y: c.y - ry }, 'line'),
        bgNode({ x: c.x + rx, y: c.y - ry }, 'line'),
        bgNode({ x: c.x + rx, y: c.y + ry }, 'line'),
        bgNode({ x: c.x - rx, y: c.y + ry }, 'line'),
      ];
    }
    graphic.mode = 'path';
    graphic.live = null;
    graphic.subpaths = [{ id: bgNextId('bgsp'), closed: true, nodes }];
    return true;
  }

  function bgSegments(graphic) {
    const out = [];
    if (!graphic) return out;
    if (graphic.mode === 'live') {
      const pathCopy = normalizeBoardGraphic(clone(graphic));
      convertBoardGraphicToPath(pathCopy);
      graphic = pathCopy;
    }
    for (const subpath of graphic.subpaths || []) {
      const nodes = subpath.nodes || [];
      const count = subpath.closed ? nodes.length : nodes.length - 1;
      for (let i = 0; i < count; i += 1) {
        const a = nodes[i], b = nodes[(i + 1) % nodes.length];
        if (!a || !b) continue;
        out.push({ subpath, index: i, a, b, type: a.segmentType === 'curve' ? 'curve' : 'line' });
      }
    }
    return out;
  }

  function bgBezierPoint(seg, t) {
    if (seg.type !== 'curve') return { x: seg.a.point.x + (seg.b.point.x - seg.a.point.x) * t, y: seg.a.point.y + (seg.b.point.y - seg.a.point.y) * t };
    return bezierPoint(seg.a.point, seg.a.handleOut, seg.b.handleIn, seg.b.point, t);
  }

  function bgNearestOnSegment(seg, world) {
    const samples = seg.type === 'curve' ? 48 : 1;
    let best = null, prev = seg.a.point;
    for (let i = 1; i <= samples; i += 1) {
      const next = bgBezierPoint(seg, i / samples);
      const dx = next.x - prev.x, dy = next.y - prev.y, l2 = dx * dx + dy * dy;
      const u = l2 ? Math.max(0, Math.min(1, ((world.x - prev.x) * dx + (world.y - prev.y) * dy) / l2)) : 0;
      const q = { x: prev.x + dx * u, y: prev.y + dy * u };
      const d = Math.hypot(world.x - q.x, world.y - q.y);
      if (!best || d < best.distance) best = { distance: d, t: (i - 1 + u) / samples, point: bgBezierPoint(seg, (i - 1 + u) / samples) };
      prev = next;
    }
    return best;
  }

  function hitTestBoardGraphics(world) {
    const tolerance = 9 / state.zoom;
    const graphics = state.graphics || [];
    for (let i = graphics.length - 1; i >= 0; i -= 1) {
      const graphic = graphics[i];
      for (const seg of bgSegments(graphic)) {
        if (bgNearestOnSegment(seg, world).distance <= tolerance) return { id: graphic.id };
      }
    }
    return null;
  }

  function hitTestGraphicEdit(world, graphic) {
    if (!graphic || graphic.mode !== 'path') return null;
    const nodeRadius = 9 / state.zoom, handleRadius = 8 / state.zoom;
    const active = state.graphicEdit && state.graphicEdit.active;
    if (active && active.kind === 'segment') {
      const sp = (graphic.subpaths || []).find(x => x.id === active.subpathId);
      const node = sp && sp.nodes.find(n => n.id === active.startNodeId);
      const next = sp && sp.nodes[(sp.nodes.indexOf(node) + 1) % sp.nodes.length];
      if (node && next && node.segmentType === 'curve') {
        if (Math.hypot(world.x - node.handleOut.x, world.y - node.handleOut.y) <= handleRadius) return { kind: 'handleOut', subpathId: sp.id, nodeId: node.id };
        if (Math.hypot(world.x - next.handleIn.x, world.y - next.handleIn.y) <= handleRadius) return { kind: 'handleIn', subpathId: sp.id, nodeId: next.id };
      }
    }
    for (const sp of graphic.subpaths || []) for (const node of sp.nodes || []) {
      if (Math.hypot(world.x - node.point.x, world.y - node.point.y) <= nodeRadius) return { kind: 'node', subpathId: sp.id, nodeId: node.id };
    }
    let best = null;
    for (const seg of bgSegments(graphic)) {
      const near = bgNearestOnSegment(seg, world);
      if ((!best || near.distance < best.distance) && near.distance <= 9 / state.zoom) {
        best = { kind: 'segment', subpathId: seg.subpath.id, startNodeId: seg.a.id, t: near.t, distance: near.distance };
      }
    }
    return best;
  }

  function bgBounds(graphic) {
    if (!graphic) return null;
    if (graphic.mode === 'live' && graphic.live) return { x: graphic.live.center.x - graphic.live.width / 2, y: graphic.live.center.y - graphic.live.height / 2, width: graphic.live.width, height: graphic.live.height };
    const pts = [];
    for (const sp of graphic.subpaths || []) for (const n of sp.nodes || []) pts.push(n.point, n.handleIn, n.handleOut);
    if (!pts.length) return null;
    const xs = pts.map(p => p.x), ys = pts.map(p => p.y);
    const x = Math.min(...xs), y = Math.min(...ys);
    return { x, y, width: Math.max(1, Math.max(...xs) - x), height: Math.max(1, Math.max(...ys) - y) };
  }

  function bgHitResizeHandle(world, graphic) {
    const b = bgBounds(graphic); if (!b) return null;
    const corners = [
      { name:'nw', x:b.x, y:b.y }, { name:'ne', x:b.x+b.width, y:b.y },
      { name:'se', x:b.x+b.width, y:b.y+b.height }, { name:'sw', x:b.x, y:b.y+b.height },
    ];
    return corners.find(p => Math.hypot(world.x-p.x, world.y-p.y) <= 9/state.zoom) || null;
  }

  function bgOppositeCorner(bounds, name) {
    return {
      x: name.includes('w') ? bounds.x + bounds.width : bounds.x,
      y: name.includes('n') ? bounds.y + bounds.height : bounds.y,
    };
  }

  function bgResizeFromCorner(graphic, interaction, world, shiftKey, altKey) {
    const start = interaction.startBounds, origin = interaction.origin;
    if (!graphic || !start || !origin) return;
    let sx = Math.abs(world.x-origin.x) / Math.max(1,start.width);
    let sy = Math.abs(world.y-origin.y) / Math.max(1,start.height);
    if (graphic.mode === 'live' && (shiftKey || graphic.shapeKind !== 'rectangle')) sx = sy = Math.min(sx, sy);
    if (shiftKey && graphic.mode === 'path') sx = sy = Math.min(sx, sy);
    sx = Math.max(0.05, sx); sy = Math.max(0.05, sy);
    const source = normalizeBoardGraphic(interaction.startGraphic);
    Object.assign(graphic, source);
    const scaleOrigin = altKey ? {x:start.x+start.width/2,y:start.y+start.height/2} : origin;
    bgScaleAbout(graphic, scaleOrigin, sx, sy);
  }

  function bgMoveEditPart(graphic, hit, target) {
    if (!graphic || !hit) return false;
    const sp = (graphic.subpaths || []).find(x => x.id === hit.subpathId);
    const node = sp && sp.nodes.find(n => n.id === hit.nodeId);
    if (!node) return false;
    if (hit.kind === 'node') {
      const dx=target.x-node.point.x, dy=target.y-node.point.y;
      node.point=bgClonePoint(target); node.handleIn.x+=dx;node.handleIn.y+=dy;node.handleOut.x+=dx;node.handleOut.y+=dy;
    } else if (hit.kind === 'handleIn') node.handleIn=bgClonePoint(target);
    else if (hit.kind === 'handleOut') node.handleOut=bgClonePoint(target);
    else return false;
    return true;
  }

  function bgMove(graphic, dx, dy) {
    if (!graphic || (!dx && !dy)) return;
    if (graphic.mode === 'live') { graphic.live.center.x += dx; graphic.live.center.y += dy; return; }
    for (const sp of graphic.subpaths || []) for (const n of sp.nodes || []) for (const key of ['point', 'handleIn', 'handleOut']) { n[key].x += dx; n[key].y += dy; }
  }

  function bgScaleAbout(graphic, origin, sx, sy) {
    if (!graphic || !origin || !Number.isFinite(sx) || !Number.isFinite(sy)) return;
    const scale = p => { p.x = origin.x + (p.x - origin.x) * sx; p.y = origin.y + (p.y - origin.y) * sy; };
    if (graphic.mode === 'live') {
      scale(graphic.live.center);
      graphic.live.width = Math.max(1, graphic.live.width * Math.abs(sx));
      graphic.live.height = Math.max(1, graphic.live.height * Math.abs(sy));
      if (graphic.shapeKind !== 'rectangle') {
        const side = Math.min(graphic.live.width, graphic.live.height);
        graphic.live.width = side; graphic.live.height = side;
      }
      return;
    }
    for (const sp of graphic.subpaths || []) for (const n of sp.nodes || []) for (const key of ['point', 'handleIn', 'handleOut']) scale(n[key]);
  }

  function bgOwnedByImage(imageId) { return (state.graphics || []).filter(g => g.sourceImageId === imageId); }

  function scaleOwnedGraphicsForImageResize(imageId, origin, factor) {
    if (!Number.isFinite(factor) || factor <= 0 || Math.abs(factor-1)<1e-9) return;
    for (const graphic of bgOwnedByImage(imageId)) bgScaleAbout(graphic, origin, factor, factor);
  }

  function bgEnterEdit(graphic) {
    if (!graphic) return false;
    const changed = convertBoardGraphicToPath(graphic);
    state.graphicEdit = { graphicId: graphic.id, active: null };
    if (changed) pushHistoryIfChanged();
    updateUI(); requestRender();
    return true;
  }

  function bgExitEdit() {
    if (!state.graphicEdit) return false;
    state.graphicEdit = null; updateUI(); requestRender(); return true;
  }

  function bgFindActive(graphic) {
    const active = state.graphicEdit && state.graphicEdit.graphicId === graphic.id ? state.graphicEdit.active : null;
    if (!active) return null;
    const subpath = (graphic.subpaths || []).find(sp => sp.id === active.subpathId);
    if (!subpath) return null;
    const nodeIndex = active.nodeId ? subpath.nodes.findIndex(n => n.id === active.nodeId) : -1;
    const segmentIndex = active.startNodeId ? subpath.nodes.findIndex(n => n.id === active.startNodeId) : -1;
    return { active, subpath, nodeIndex, segmentIndex };
  }

  function bgInsertNodeOnSegment(subpath, segmentIndex, t) {
    const nodes = subpath.nodes, a = nodes[segmentIndex], b = nodes[(segmentIndex + 1) % nodes.length];
    if (!a || !b) return -1;
    const safe = Math.max(0.001, Math.min(0.999, Number(t) || 0.5));
    let node;
    if (a.segmentType === 'curve') {
      const split = subdivideCubicBezier(a.point, a.handleOut, b.handleIn, b.point, safe);
      a.handleOut = bgClonePoint(split.left[1]);
      b.handleIn = bgClonePoint(split.right[2]);
      node = bgNode(split.left[3], 'curve', split.left[2], split.right[1]);
    } else {
      const p = { x: a.point.x + (b.point.x - a.point.x) * safe, y: a.point.y + (b.point.y - a.point.y) * safe };
      node = bgNode(p, 'line');
    }
    nodes.splice(segmentIndex + 1, 0, node);
    return segmentIndex + 1;
  }

  function bgCutNode(graphic, subpath, index) {
    const nodes = subpath.nodes;
    if (!nodes[index]) return false;
    if (!subpath.closed && (index === 0 || index === nodes.length - 1)) return false;
    if (subpath.closed) {
      const rotated = nodes.slice(index).concat(nodes.slice(0, index));
      const first = rotated[0];
      const last = bgNormalizeNode({ id: bgNextId('bgn'), point: first.point, handleIn: first.handleIn, handleOut: first.point, segmentType: 'line' });
      first.handleIn = bgClonePoint(first.point);
      rotated.push(last);
      subpath.nodes = rotated;
      subpath.closed = false;
      state.graphicEdit.active = { kind: 'node', subpathId: subpath.id, nodeId: last.id };
      return true;
    }
    const left = nodes.slice(0, index + 1).map(n => bgNormalizeNode(clone(n)));
    const right = nodes.slice(index).map(n => bgNormalizeNode(clone(n)));
    right[0].id = bgNextId('bgn');
    left[left.length - 1].handleOut = bgClonePoint(left[left.length - 1].point);
    left[left.length - 1].segmentType = 'line';
    right[0].handleIn = bgClonePoint(right[0].point);
    subpath.nodes = left;
    const newSubpath = { id: bgNextId('bgsp'), closed: false, nodes: right };
    const at = graphic.subpaths.indexOf(subpath);
    graphic.subpaths.splice(at + 1, 0, newSubpath);
    state.graphicEdit.active = { kind: 'node', subpathId: newSubpath.id, nodeId: right[0].id };
    return true;
  }

  function cutSelectedBoardGraphicPath() {
    const graphic = getSelectedBoardGraphic();
    const found = graphic && bgFindActive(graphic);
    if (!found || !['node', 'segment'].includes(found.active.kind)) { showToast('Select a path node or segment first.'); return false; }
    let index = found.nodeIndex;
    if (found.active.kind === 'segment') index = bgInsertNodeOnSegment(found.subpath, found.segmentIndex, found.active.t);
    if (index < 0 || !bgCutNode(graphic, found.subpath, index)) { showToast('That point is already an open endpoint.'); return false; }
    pushHistoryIfChanged(); updateUI(); requestRender(); showToast('Path cut — subpaths remain one Board Graphic.');
    return true;
  }

  function bgSetActiveSegmentType(type) {
    const graphic = getSelectedBoardGraphic(), found = graphic && bgFindActive(graphic);
    if (!found || found.active.kind !== 'segment' || found.segmentIndex < 0) return false;
    const node = found.subpath.nodes[found.segmentIndex];
    if (node.segmentType === type) return false;
    const next = found.subpath.nodes[(found.segmentIndex + 1) % found.subpath.nodes.length];
    node.segmentType = type;
    if (type === 'line') { node.handleOut = bgClonePoint(node.point); next.handleIn = bgClonePoint(next.point); }
    else {
      node.handleOut = { x: node.point.x + (next.point.x - node.point.x) / 3, y: node.point.y + (next.point.y - node.point.y) / 3 };
      next.handleIn = { x: next.point.x - (next.point.x - node.point.x) / 3, y: next.point.y - (next.point.y - node.point.y) / 3 };
    }
    pushHistoryIfChanged(); updateUI(); requestRender(); return true;
  }

  function drawBoardGraphicPath(graphic) {
    for (const sp of (graphic.mode === 'path' ? graphic.subpaths : [])) {
      const nodes = sp.nodes || []; if (nodes.length < 2) continue;
      ctx.beginPath(); ctx.moveTo(nodes[0].point.x, nodes[0].point.y);
      const count = sp.closed ? nodes.length : nodes.length - 1;
      for (let i = 0; i < count; i += 1) {
        const a = nodes[i], b = nodes[(i + 1) % nodes.length];
        if (a.segmentType === 'curve') ctx.bezierCurveTo(a.handleOut.x, a.handleOut.y, b.handleIn.x, b.handleIn.y, b.point.x, b.point.y);
        else ctx.lineTo(b.point.x, b.point.y);
      }
      ctx.stroke();
    }
  }

  function drawBoardGraphic(graphic, alpha) {
    if (!graphic) return;
    ctx.save(); ctx.globalAlpha = alpha == null ? 1 : alpha;
    ctx.strokeStyle = LINE_COLORS[normalizeColorKey(graphic.color)] || LINE_COLOR;
    ctx.lineWidth = normalizeLineWidth(graphic.lineWidth) / featureZoom();
    ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);
    if (graphic.mode === 'live') {
      const b = bgBounds(graphic); ctx.beginPath();
      if (graphic.shapeKind === 'circle') ctx.arc(b.x + b.width / 2, b.y + b.height / 2, Math.min(b.width, b.height) / 2, 0, Math.PI * 2);
      else if (graphic.shapeKind === 'hexagon') {
        const c = graphic.live.center, r = Math.min(graphic.live.width, graphic.live.height) / 2;
        for (let i = 0; i < 6; i += 1) { const a = -Math.PI / 2 + i * Math.PI / 3, p = { x: c.x + Math.cos(a) * r, y: c.y + Math.sin(a) * r }; if (!i) ctx.moveTo(p.x, p.y); else ctx.lineTo(p.x, p.y); } ctx.closePath();
      } else ctx.rect(b.x, b.y, b.width, b.height);
      ctx.stroke();
    } else drawBoardGraphicPath(graphic);
    ctx.restore();
  }

  function drawBoardGraphics() { for (const graphic of (state.graphics || [])) drawBoardGraphic(graphic); }

  function bgDrawHandle(p, active, square) {
    const r = (active ? 5 : 4) / state.zoom;
    ctx.save(); ctx.fillStyle = active ? '#356dff' : '#fff'; ctx.strokeStyle = '#356dff'; ctx.lineWidth = 1.5 / state.zoom; ctx.beginPath();
    if (square) ctx.rect(p.x - r, p.y - r, r * 2, r * 2); else ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
    ctx.fill(); ctx.stroke(); ctx.restore();
  }

  function drawBoardGraphicSelection(graphic) {
    if (!graphic) return;
    const editing = state.graphicEdit && state.graphicEdit.graphicId === graphic.id;
    if (!editing) {
      const b = bgBounds(graphic); if (!b) return;
      ctx.save(); ctx.strokeStyle = 'rgba(53,109,255,.75)'; ctx.lineWidth = 1.2 / state.zoom; ctx.setLineDash([5 / state.zoom, 4 / state.zoom]); ctx.strokeRect(b.x, b.y, b.width, b.height); ctx.restore();
      for (const p of [{x:b.x,y:b.y},{x:b.x+b.width,y:b.y},{x:b.x+b.width,y:b.y+b.height},{x:b.x,y:b.y+b.height}]) bgDrawHandle(p, false, true);
      return;
    }
    const active = state.graphicEdit.active;
    for (const sp of graphic.subpaths || []) for (const node of sp.nodes || []) bgDrawHandle(node.point, !!(active && active.kind === 'node' && active.nodeId === node.id), true);
    const found = bgFindActive(graphic);
    if (found && found.active.kind === 'segment' && found.segmentIndex >= 0) {
      const a = found.subpath.nodes[found.segmentIndex], b = found.subpath.nodes[(found.segmentIndex + 1) % found.subpath.nodes.length];
      if (a.segmentType === 'curve') {
        ctx.save(); ctx.strokeStyle = 'rgba(53,109,255,.5)'; ctx.lineWidth = 1 / state.zoom; ctx.setLineDash([5/state.zoom,4/state.zoom]); ctx.beginPath(); ctx.moveTo(a.point.x,a.point.y);ctx.lineTo(a.handleOut.x,a.handleOut.y);ctx.moveTo(b.point.x,b.point.y);ctx.lineTo(b.handleIn.x,b.handleIn.y);ctx.stroke();ctx.restore();
        bgDrawHandle(a.handleOut, false, false); bgDrawHandle(b.handleIn, false, false);
      }
    }
  }

  function drawBoardGraphicPreview() {
    const inter = state.interaction;
    if (!inter || inter.type !== 'draw-graphic') return;
    const box = bgBoxFromDrag(inter.kind, inter.startWorld, inter.currentWorld, inter.shiftKey, inter.altKey);
    const temp = normalizeBoardGraphic({ id: 'preview', shapeKind: inter.kind, mode:'live', color:state.drawColor, lineWidth:state.lineWidth, live:{center:{x:box.x+box.width/2,y:box.y+box.height/2},width:box.width,height:box.height} });
    drawBoardGraphic(temp, 0.65);
  }

  // ---- src/ui/toast.js ----
// Lightweight on-screen toast helper.
// Source part for app.js. Run `npm run build` after editing.
//
// US-032: one visible toast plus a short queue. A toast that arrives while
// the current one hasn't had a fair reading window queues instead of
// overwriting, then the queue drains on an early-advance cadence. Callers
// whose messages are a live STATUS (Tab part-cycling, brush size) pass
// { replace: true } — latest wins there, since replaying stale states after
// a keyboard burst would be worse than the old overwrite behaviour.
// The second positional argument still accepts a number (duration in ms)
// for the existing long-error call sites.

  const TOAST_DEFAULT_MS = 2600;
  const TOAST_MIN_VISIBLE_MS = 900; // fair reading window before a swap
  const TOAST_QUEUE_MAX = 3;
  let toastQueue = [];
  let toastShownAt = 0;
  let toastAdvanceTimer = null;

  function showToast(message, opts) {
    const options = typeof opts === 'number' ? { duration: opts } : (opts || {});
    const entry = { message, duration: options.duration || TOAST_DEFAULT_MS };
    const visible = el.toast.classList.contains('show');
    if (options.replace) {
      toastQueue = [];
      displayToast(entry);
      return;
    }
    if (visible && el.toast.textContent === message) {
      displayToast(entry); // same message again — extend, don't queue
      return;
    }
    const shownFor = performance.now() - toastShownAt;
    if (visible && shownFor < TOAST_MIN_VISIBLE_MS) {
      if (!toastQueue.some(q => q.message === message)) {
        toastQueue.push(entry);
        if (toastQueue.length > TOAST_QUEUE_MAX) toastQueue.shift();
        scheduleToastAdvance(TOAST_MIN_VISIBLE_MS - shownFor);
      }
      return;
    }
    displayToast(entry);
  }

  function displayToast(entry) {
    if (toastAdvanceTimer) {
      clearTimeout(toastAdvanceTimer);
      toastAdvanceTimer = null;
    }
    el.toast.textContent = entry.message;
    el.toast.classList.add('show');
    toastShownAt = performance.now();
    clearTimeout(state.toastTimer);
    state.toastTimer = setTimeout(() => {
      el.toast.classList.remove('show');
      advanceToastQueue();
    }, entry.duration);
    if (toastQueue.length) scheduleToastAdvance(TOAST_MIN_VISIBLE_MS);
  }

  function scheduleToastAdvance(delay) {
    if (toastAdvanceTimer) return; // an advance is already on its way
    toastAdvanceTimer = setTimeout(() => {
      toastAdvanceTimer = null;
      advanceToastQueue();
    }, Math.max(0, delay));
  }

  function advanceToastQueue() {
    const next = toastQueue.shift();
    if (next) displayToast(next);
  }

  // ---- src/ui/dialogs/core.js ----
// Shared modal shell used by every dialog under src/ui/dialogs/.
// Source part for app.js. Run `npm run build` after editing.
//
// buildDialog gives each dialog a backdrop, header with a close button, and
// Esc / click-outside dismissal. Dialog-specific files (help, scale, etc.)
// assemble their bodies on top of the returned panel. escapeHtml is the
// shared safe-text helper used when dialogs build innerHTML strings.

  let dialogTitleSeq = 0;

  // Shared shell so dialogs look and behave the same: backdrop, header with
  // a close button, Esc / click-outside to dismiss. Returns the panel to fill.
  function buildDialog({ title, sub }) {
    const returnFocus = document.activeElement;
    const overlay = document.createElement('div');
    overlay.className = 'picker-overlay';

    const panel = document.createElement('div');
    panel.className = 'picker-panel dialog-panel';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-modal', 'true');
    overlay.appendChild(panel);

    const header = document.createElement('div');
    header.className = 'picker-header dialog-header';
    const heading = document.createElement('h2');
    heading.id = 'dialog-title-' + (++dialogTitleSeq);
    heading.textContent = title;
    panel.setAttribute('aria-labelledby', heading.id);
    header.appendChild(heading);
    if (sub) {
      const subEl = document.createElement('span');
      subEl.className = 'picker-sub';
      subEl.textContent = sub;
      header.appendChild(subEl);
    }
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'dialog-close';
    closeBtn.setAttribute('aria-label', 'Close');
    closeBtn.innerHTML = '&times;';
    header.appendChild(closeBtn);
    panel.appendChild(header);

    let closed = false;
    function close() {
      if (closed) return;
      closed = true;
      document.removeEventListener('keydown', onKey, true);
      overlay.remove();
      if (returnFocus && returnFocus.isConnected && typeof returnFocus.focus === 'function') {
        returnFocus.focus();
      }
    }
    function onKey(ev) {
      if (ev.key === 'Escape') {
        // Modal Escape belongs exclusively to the open dialog. Several page
        // controllers also listen for Escape on document (for example, BOM
        // uses it to return to Board). stopPropagation() alone still allows
        // later listeners on the same document node to run after close()
        // removes the overlay, so closing a palette could also change pages.
        ev.preventDefault();
        ev.stopImmediatePropagation();
        close();
        return;
      }
      if (ev.key !== 'Tab') return;
      const focusable = Array.from(panel.querySelectorAll(
        'button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), '
        + '[href], [tabindex]:not([tabindex="-1"])'
      )).filter(node => node.offsetParent !== null);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (ev.shiftKey && document.activeElement === first) {
        ev.preventDefault();
        last.focus();
      } else if (!ev.shiftKey && document.activeElement === last) {
        ev.preventDefault();
        first.focus();
      }
    }
    closeBtn.addEventListener('click', close);
    overlay.addEventListener('click', ev => { if (ev.target === overlay) close(); });
    document.addEventListener('keydown', onKey, true);

    return {
      overlay,
      panel,
      close,
      open() { document.body.appendChild(overlay); },
    };
  }

  function escapeHtml(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  // ---- src/ui/dialogs/command-palette-dialog.js ----
// Searchable, keyboard-first Command Palette (US-094). Source part for app.js.
// Run `npm run build` after editing.

  function openCommandPalette() {
    if (document.querySelector('.command-palette-overlay')) return;

    const dialog = buildDialog({
      title: 'Command Palette',
      sub: 'Every stable action, scoped to the page and selection you are using.',
    });
    dialog.overlay.classList.add('command-palette-overlay');
    dialog.panel.classList.add('command-palette-panel');

    const searchWrap = document.createElement('div');
    searchWrap.className = 'command-palette-search-wrap';
    const search = document.createElement('input');
    search.type = 'search';
    search.className = 'command-palette-search';
    search.placeholder = 'Type a command…';
    search.autocomplete = 'off';
    search.spellcheck = false;
    search.setAttribute('aria-label', 'Search commands');
    searchWrap.appendChild(search);
    dialog.panel.appendChild(searchWrap);

    const list = document.createElement('div');
    list.className = 'command-palette-list';
    list.setAttribute('role', 'listbox');
    list.setAttribute('aria-label', 'Commands');
    dialog.panel.appendChild(list);

    const footer = document.createElement('div');
    footer.className = 'command-palette-footer';
    footer.innerHTML = '<span><span class="kbd">↑</span><span class="kbd">↓</span> navigate</span>'
      + '<span><span class="kbd">Enter</span> run</span>'
      + '<span><span class="kbd">Esc</span> close</span>';
    dialog.panel.appendChild(footer);

    let rows = [];
    let activeIndex = 0;

    function paletteSearchText(command) {
      return [command.label, command.category, command.keywords, command.id]
        .join(' ').toLowerCase();
    }

    function paletteCommands() {
      const query = search.value.trim().toLowerCase();
      const tokens = query.split(/\s+/).filter(Boolean);
      return getAppCommands()
        .filter(command => command.palette !== false)
        .filter(command => tokens.every(token => paletteSearchText(command).includes(token)))
        .map(command => ({ command, availability: getAppCommandAvailability(command) }))
        .sort((a, b) => {
          const aPage = a.command.page === state.activePage ? 0 : (a.command.page ? 2 : 1);
          const bPage = b.command.page === state.activePage ? 0 : (b.command.page ? 2 : 1);
          if (aPage !== bPage) return aPage - bPage;
          if (a.availability.enabled !== b.availability.enabled) return a.availability.enabled ? -1 : 1;
          return a.command.category.localeCompare(b.command.category) || a.command.label.localeCompare(b.command.label);
        });
    }

    function activePaletteRow() {
      return rows[activeIndex] || null;
    }

    function syncPaletteActive() {
      const buttons = Array.from(list.querySelectorAll('[data-command-id]'));
      buttons.forEach((button, index) => {
        const active = index === activeIndex;
        button.classList.toggle('active', active);
        button.setAttribute('aria-selected', String(active));
        if (active) {
          search.setAttribute('aria-activedescendant', button.id);
          button.scrollIntoView({ block: 'nearest' });
        }
      });
      if (!buttons.length) search.removeAttribute('aria-activedescendant');
    }

    function renderPalette() {
      rows = paletteCommands();
      activeIndex = Math.max(0, Math.min(activeIndex, rows.length - 1));
      if (!rows.length) {
        list.innerHTML = '<div class="command-palette-empty">No commands match this search.</div>';
        search.removeAttribute('aria-activedescendant');
        return;
      }
      list.innerHTML = rows.map((row, index) => {
        const command = row.command;
        const shortcut = formatAppCommandShortcuts(command);
        return '<button type="button" id="command-palette-row-' + index + '" data-command-id="'
          + escapeHtml(command.id) + '" role="option" tabindex="-1" aria-disabled="'
          + String(!row.availability.enabled) + '" class="command-palette-row'
          + (row.availability.enabled ? '' : ' disabled') + '">'
          + '<span class="command-palette-copy"><span class="command-palette-label">'
          + escapeHtml(command.label) + '</span><span class="command-palette-meta">'
          + escapeHtml(command.category)
          + (row.availability.enabled ? '' : ' · ' + row.availability.reason) + '</span></span>'
          + (shortcut ? '<span class="command-palette-shortcut">' + escapeHtml(shortcut) + '</span>' : '')
          + '</button>';
      }).join('');
      syncPaletteActive();
    }

    function executePaletteRow(row) {
      if (!row) return;
      if (!row.availability.enabled) {
        showToast(row.availability.reason);
        return;
      }
      const id = row.command.id;
      dialog.close();
      runAppCommand(id);
    }

    search.addEventListener('input', () => {
      activeIndex = 0;
      renderPalette();
    });
    search.addEventListener('keydown', event => {
      if (!rows.length) return;
      if (event.key === 'ArrowDown') activeIndex = (activeIndex + 1) % rows.length;
      else if (event.key === 'ArrowUp') activeIndex = (activeIndex - 1 + rows.length) % rows.length;
      else if (event.key === 'Home') activeIndex = 0;
      else if (event.key === 'End') activeIndex = rows.length - 1;
      else if (event.key === 'Enter') {
        event.preventDefault();
        executePaletteRow(activePaletteRow());
        return;
      } else return;
      event.preventDefault();
      syncPaletteActive();
    });
    list.addEventListener('mousemove', event => {
      const button = event.target.closest('[data-command-id]');
      if (!button) return;
      const index = Array.from(list.querySelectorAll('[data-command-id]')).indexOf(button);
      if (index >= 0 && index !== activeIndex) {
        activeIndex = index;
        syncPaletteActive();
      }
    });
    list.addEventListener('click', event => {
      const button = event.target.closest('[data-command-id]');
      if (!button) return;
      executePaletteRow(rows.find(row => row.command.id === button.dataset.commandId));
    });

    dialog.open();
    renderPalette();
    search.focus();
  }

