  // ---- src/ui/dialogs/scale-dialog.js ----
// Set Scale dialog: calibrate board units-per-pixel from one known line.
// Source part for app.js. Run `npm run build` after editing.

  // refLabel is optional. When calibrating from a spec-panel row it names the
  // POM ("POM 1 — 1/2 Bottom Band, Relax"); the Set Scale button passes nothing
  // and the copy falls back to "selected line".
  function openScaleDialog(px, refLabel) {
    const cal = state.calibration;
    const currentUnit = cal && cal.unit ? cal.unit : 'in';
    const currentValue = cal && cal.unitsPerPx != null
      ? +(px * cal.unitsPerPx).toFixed(3)
      : '';
    const refText = refLabel ? refLabel : 'the selected line';

    const dialog = buildDialog({
      title: 'Set scale',
      sub: 'Calibrate the board from one known length.',
    });

    const body = document.createElement('div');
    body.className = 'scale-body';
    body.innerHTML = `
      <p class="scale-lead">Type the real length of <b>${refText}</b>. Every other line on the board is then estimated from it.</p>
      <div class="scale-field">
        <input type="number" min="0" step="any" inputmode="decimal" placeholder="e.g. 14" aria-label="Real length" />
        <select aria-label="Unit">
          <option value="in">in</option>
          <option value="cm">cm</option>
          <option value="mm">mm</option>
          <option value="m">m</option>
        </select>
      </div>
      <p class="scale-note">Tip: choose a line whose true measurement you know — a band, a strap, or a ruler shown in the photo.</p>`;
    dialog.panel.appendChild(body);

    const input = body.querySelector('input');
    const select = body.querySelector('select');
    input.value = currentValue === '' ? '' : String(currentValue);
    select.value = currentUnit;

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    const spacer = document.createElement('span');
    spacer.style.flex = '1';
    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'picker-btn';
    cancelBtn.textContent = 'Cancel';
    const applyBtn = document.createElement('button');
    applyBtn.type = 'button';
    applyBtn.className = 'picker-btn primary';
    applyBtn.textContent = 'Set scale';
    footer.appendChild(spacer);
    footer.appendChild(cancelBtn);
    footer.appendChild(applyBtn);
    dialog.panel.appendChild(footer);

    function apply() {
      const value = parseFloat(input.value);
      if (!isFinite(value) || value <= 0) {
        input.focus();
        input.select();
        showToast('Enter a length greater than zero, e.g. 70.');
        return;
      }
      const unit = select.value;
      state.calibration = { unitsPerPx: value / px, unit };
      pushHistoryIfChanged();
      showToast('Scale set: the table now estimates every line in ' + unit + '.');
      updateUI();
      requestRender();
      dialog.close();
    }

    cancelBtn.addEventListener('click', dialog.close);
    applyBtn.addEventListener('click', apply);
    input.addEventListener('keydown', ev => {
      if (ev.key === 'Enter') { ev.preventDefault(); apply(); }
    });

    dialog.open();
    input.focus();
    input.select();
  }

  // ---- src/ui/dialogs/auto-exit-dialog.js ----
// Auto Mode exit guard: Apply / Discard / Stay prompt for unapplied drafts.
// Source part for app.js. Run `npm run build` after editing.

  // Auto Mode exit guard. The TD has unapplied drafts
  // and is trying to leave Auto Mode (or open a project, which would
  // implicitly clear the draft layer). Offers Apply / Discard / Stay as real
  // buttons instead of a confusing free-text prompt. Resolves to one of
  // 'apply', 'discard', or 'stay'.
  function openAutoModeExitDialog({ approvedCount, totalCount, reason }) {
    const dialog = buildDialog({
      title: 'You have unapplied Auto Mode drafts',
      sub: totalCount + ' draft' + (totalCount === 1 ? '' : 's') +
        ' on the board · ' + approvedCount + ' approved.',
    });

    const body = document.createElement('div');
    body.className = 'dialog-body';
    const lead = reason
      ? '<p>' + reason + '</p>'
      : '<p>Choose what to do before leaving Auto Mode:</p>';
    body.innerHTML = lead +
      '<ul style="margin:8px 0 0; padding-left:18px; color:var(--muted);">' +
        '<li><b>Apply Approved Lines</b> moves approved drafts into the project ' +
          'and switches to Manual Mode. Any remaining drafts stay in the Auto ' +
          'draft layer — toggle back to Auto to resolve them.</li>' +
        '<li><b>Discard Drafts</b> clears the draft layer without changing the project.</li>' +
        '<li><b>Stay</b> keeps everything as-is.</li>' +
      '</ul>';
    dialog.panel.appendChild(body);

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    const spacer = document.createElement('span');
    spacer.style.flex = '1';

    const stayBtn = document.createElement('button');
    stayBtn.type = 'button';
    stayBtn.className = 'picker-btn';
    stayBtn.textContent = 'Stay';

    const discardBtn = document.createElement('button');
    discardBtn.type = 'button';
    discardBtn.className = 'picker-btn';
    discardBtn.textContent = 'Discard Drafts';

    const applyBtn = document.createElement('button');
    applyBtn.type = 'button';
    applyBtn.className = 'picker-btn primary';
    applyBtn.textContent = 'Apply Approved Lines';
    applyBtn.disabled = approvedCount === 0;
    if (approvedCount === 0) applyBtn.title = 'No drafts are approved yet.';

    footer.appendChild(spacer);
    footer.appendChild(stayBtn);
    footer.appendChild(discardBtn);
    footer.appendChild(applyBtn);
    dialog.panel.appendChild(footer);

    return new Promise(resolve => {
      // buildDialog wires Esc / backdrop / X-button to its own close()
      // closure — we can't intercept those paths by overriding dialog.close.
      // Watch the overlay being detached instead so every dismissal route
      // funnels through one settle().
      let choice = 'stay';
      let settled = false;
      const observer = new MutationObserver(() => {
        if (!document.body.contains(dialog.overlay)) {
          observer.disconnect();
          if (settled) return;
          settled = true;
          resolve(choice);
        }
      });
      observer.observe(document.body, { childList: true });
      stayBtn.addEventListener('click', () => { choice = 'stay'; dialog.close(); });
      discardBtn.addEventListener('click', () => { choice = 'discard'; dialog.close(); });
      applyBtn.addEventListener('click', () => { choice = 'apply'; dialog.close(); });
      dialog.open();
      (approvedCount > 0 ? applyBtn : stayBtn).focus();
    });
  }

  // ---- src/ui/dialogs/save-evidence-dialog.js ----
// Save-time style-evidence prompt shown when saveProject() sees TD-edited
// auto-applied lines (or other evidence candidates).
// Source part for app.js. Run `npm run build` after editing.
//
// The dialog has two inline editing surfaces so the TD can teach the
// store without leaving the save flow:
//   - A Style code input that updates state.styleId on accept, so
//     evidence lands in the right bucket instead of __default__.
//   - A per-row meaning picker pre-filled with the top-3 ranked
//     suggestions for that POM's geometry plus a "Show all meanings"
//     escape hatch. Confirming a row stamps the candidate with the
//     chosen meaningId and writes it into the style's meaning catalog
//     so future Auto runs on this style resolve POM N silently.
// A bulk "Confirm all suggested" button applies the top suggestion to
// every unconfirmed row at once when the TD trusts the ranking.

  // Save-time evidence prompt. Triggered by saveProject() when the
  // project contains TD-edited Auto-applied lines that are eligible to
  // become style evidence. Resolves with one of:
  //   { action: 'cancel' }                        — close save flow
  //   { action: 'project-only' }                  — save without evidence
  //   { action: 'save-with-evidence', commit: true } — save + commit candidates
  // The caller (project-io.js) owns the actual file write so the dialog
  // stays pure UI.
  function openSaveEvidenceDialog({ styleId, candidates }) {
    const dialog = buildDialog({
      title: 'Save style evidence?',
      sub: 'TD corrections can teach this style next time.',
    });

    const initialStyleId = (styleId && styleId !== '__default__') ? String(styleId) : '';
    // Local dialog state. Style code + meaning confirmations stay
    // un-committed until the user clicks one of the Save buttons; Cancel
    // throws everything away so the rest of the app sees no side effect.
    let pendingStyleId = initialStyleId;
    const pendingMeanings = new Map(); // pom -> { meaningId, label }

    const body = document.createElement('div');
    body.className = 'dialog-body save-evidence-body';

    // --- Style code input ---------------------------------------------
    const styleSection = document.createElement('div');
    styleSection.className = 'se-style-section';
    const styleLabel = document.createElement('label');
    styleLabel.className = 'se-style-label';
    styleLabel.textContent = 'Style code';
    const styleInput = document.createElement('input');
    styleInput.type = 'text';
    styleInput.className = 'se-style-input';
    styleInput.placeholder = 'e.g. AF-123 — leave empty to use the default bucket';
    styleInput.autocomplete = 'off';
    styleInput.spellcheck = false;
    styleInput.maxLength = 40;
    styleInput.value = pendingStyleId;
    styleSection.appendChild(styleLabel);
    styleSection.appendChild(styleInput);
    body.appendChild(styleSection);

    const styleHint = document.createElement('p');
    styleHint.className = 'se-hint';
    styleSection.appendChild(styleHint);

    // --- Candidate rows ----------------------------------------------
    const heading = document.createElement('p');
    heading.className = 'se-heading';
    body.appendChild(heading);

    const list = document.createElement('div');
    list.className = 'se-candidate-list';
    body.appendChild(list);

    const bulkBar = document.createElement('div');
    bulkBar.className = 'se-bulk-bar';
    const bulkBtn = document.createElement('button');
    bulkBtn.type = 'button';
    bulkBtn.className = 'picker-btn se-bulk-btn';
    bulkBtn.textContent = 'Confirm all suggested';
    bulkBar.appendChild(bulkBtn);
    body.appendChild(bulkBar);

    const note = document.createElement('p');
    note.className = 'se-note';
    body.appendChild(note);

    dialog.panel.appendChild(body);

    // --- Footer -------------------------------------------------------
    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    const spacer = document.createElement('span');
    spacer.style.flex = '1';
    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'picker-btn';
    cancelBtn.textContent = 'Cancel';
    const onlyBtn = document.createElement('button');
    onlyBtn.type = 'button';
    onlyBtn.className = 'picker-btn';
    onlyBtn.textContent = 'Save project only';
    const bothBtn = document.createElement('button');
    bothBtn.type = 'button';
    bothBtn.className = 'picker-btn primary';
    footer.appendChild(spacer);
    footer.appendChild(cancelBtn);
    footer.appendChild(onlyBtn);
    footer.appendChild(bothBtn);
    dialog.panel.appendChild(footer);

    // --- Per-row rendering -------------------------------------------
    const rowControllers = []; // each: { candidate, refresh(), confirmTop() }
    for (const c of candidates) {
      const ctrl = buildCandidateRow(c, pendingMeanings, list, updateAll);
      rowControllers.push(ctrl);
    }

    function buildCandidateRow(candidate, pendingMap, parent, onChange) {
      const row = document.createElement('div');
      row.className = 'se-row';
      const pomEl = document.createElement('span');
      pomEl.className = 'se-pom';
      pomEl.textContent = 'POM ' + (candidate.pom || '?');
      const labelEl = document.createElement('span');
      labelEl.className = 'se-label';
      const metaEl = document.createElement('span');
      metaEl.className = 'se-meta';
      metaEl.textContent = candidate.viewRole ? '· ' + candidate.viewRole : '';
      row.appendChild(pomEl);
      row.appendChild(labelEl);
      row.appendChild(metaEl);
      parent.appendChild(row);

      const isAbsent = candidate.tdStatus === 'absent-confirmed';
      const initialMeaningId = candidate.meaningId || null;

      let suggestionIds = [];
      if (!isAbsent && !initialMeaningId) {
        suggestionIds = computeMeaningSuggestionIds(candidate);
      }

      // Renders the row in the right state — already-confirmed (catalog
      // hit), TD-confirmed-in-dialog, absent, or picker. Called once at
      // build time and again when pendingMeanings flips.
      function render() {
        // Reset row to a known state.
        row.classList.remove('is-confirmed', 'is-absent', 'is-pending');
        const dialogConfirmed = pendingMap.get(String(candidate.pom));
        if (isAbsent) {
          row.classList.add('is-absent');
          labelEl.textContent = (candidate.meaningLabel || candidate.meaningId || 'Measurement')
            + ' is absent in this style';
          // Wipe any prior picker controls.
          stripExtras();
          return;
        }
        if (initialMeaningId) {
          row.classList.add('is-confirmed');
          labelEl.textContent = candidate.meaningLabel || candidate.meaningId;
          stripExtras();
          return;
        }
        if (dialogConfirmed) {
          row.classList.add('is-confirmed');
          labelEl.innerHTML = '<span class="se-check">✓</span> '
            + escapeHtml(dialogConfirmed.label);
          stripExtras();
          // Offer an undo so a mis-click can be reversed before save.
          const undoBtn = document.createElement('button');
          undoBtn.type = 'button';
          undoBtn.className = 'se-undo';
          undoBtn.textContent = 'Change';
          undoBtn.addEventListener('click', () => {
            pendingMap.delete(String(candidate.pom));
            render();
            onChange();
          });
          row.appendChild(undoBtn);
          return;
        }
        // Unconfirmed → show picker.
        row.classList.add('is-pending');
        labelEl.textContent = '(meaning not confirmed)';
        stripExtras();
        const picker = buildPicker();
        row.appendChild(picker);
      }

      function stripExtras() {
        const extras = row.querySelectorAll('.se-picker, .se-undo');
        extras.forEach(el => el.remove());
      }

      function buildPicker() {
        const wrap = document.createElement('div');
        wrap.className = 'se-picker';
        const select = document.createElement('select');
        select.className = 'se-picker-select';
        const seen = new Set();
        for (const id of suggestionIds) {
          const entry = (typeof getCatalogEntry === 'function') ? getCatalogEntry(id) : null;
          if (!entry || seen.has(entry.id)) continue;
          seen.add(entry.id);
          const opt = document.createElement('option');
          opt.value = entry.id;
          opt.textContent = entry.label;
          select.appendChild(opt);
        }
        // Always include an "Other…" option that swaps the dropdown for
        // the full catalog, so a missed suggestion is still reachable
        // without leaving the dialog.
        const otherOpt = document.createElement('option');
        otherOpt.value = '__other__';
        otherOpt.textContent = seen.size ? '— Show all meanings —' : 'Pick a meaning…';
        select.appendChild(otherOpt);
        if (!seen.size) select.value = '__other__';

        select.addEventListener('change', () => {
          if (select.value === '__other__') swapToFullCatalog(select, seen);
        });
        // If no suggestions came back, open the full catalog immediately.
        if (!seen.size) swapToFullCatalog(select, seen);

        const confirmBtn = document.createElement('button');
        confirmBtn.type = 'button';
        confirmBtn.className = 'picker-btn primary se-confirm';
        confirmBtn.textContent = 'Confirm';
        confirmBtn.addEventListener('click', () => {
          const id = select.value;
          if (!id || id === '__other__') return;
          const entry = (typeof getCatalogEntry === 'function') ? getCatalogEntry(id) : null;
          if (!entry) return;
          pendingMap.set(String(candidate.pom), { meaningId: entry.id, label: entry.label });
          render();
          onChange();
        });
        wrap.appendChild(select);
        wrap.appendChild(confirmBtn);
        return wrap;
      }

      // First render.
      render();

      return {
        candidate,
        hasSuggestion: () => suggestionIds.length > 0 || initialMeaningId != null,
        isUnconfirmed: () => {
          if (isAbsent || initialMeaningId) return false;
          return !pendingMap.has(String(candidate.pom));
        },
        confirmTop() {
          if (isAbsent || initialMeaningId) return false;
          if (pendingMap.has(String(candidate.pom))) return false;
          const id = suggestionIds[0];
          if (!id) return false;
          const entry = (typeof getCatalogEntry === 'function') ? getCatalogEntry(id) : null;
          if (!entry) return false;
          pendingMap.set(String(candidate.pom), { meaningId: entry.id, label: entry.label });
          render();
          return true;
        },
        refresh: render,
      };
    }

    function swapToFullCatalog(select, seen) {
      const all = (typeof getAllCatalogMeanings === 'function') ? getAllCatalogMeanings() : [];
      // Preserve the already-seen suggestion entries at the top so the
      // ranking signal isn't lost when the TD wants to browse further.
      const top = Array.from(seen);
      select.innerHTML = '';
      const placeholder = document.createElement('option');
      placeholder.value = '';
      placeholder.textContent = 'Pick a meaning…';
      placeholder.disabled = true;
      placeholder.selected = true;
      select.appendChild(placeholder);
      for (const id of top) {
        const entry = (typeof getCatalogEntry === 'function') ? getCatalogEntry(id) : null;
        if (!entry) continue;
        const opt = document.createElement('option');
        opt.value = entry.id;
        opt.textContent = '★ ' + entry.label;
        select.appendChild(opt);
      }
      for (const m of all) {
        if (seen.has(m.id)) continue;
        const opt = document.createElement('option');
        opt.value = m.id;
        opt.textContent = m.label;
        select.appendChild(opt);
      }
    }

    // Rank suggestions for a candidate by handing the live annotation back
    // to rankCatalogForLine — same engine that drives the meaning popover.
    function computeMeaningSuggestionIds(candidate) {
      if (typeof rankCatalogForLine !== 'function') return [];
      if (!state || !Array.isArray(state.annotations)) return [];
      const ann = state.annotations.find(a => a && a.id === candidate.annotationId);
      if (!ann) return [];
      const image = (typeof pickImageForAnnotation === 'function') ? pickImageForAnnotation(ann) : null;
      if (!image) return [];
      const ranked = rankCatalogForLine(image, ann, 3);
      return ranked.map(m => m.id).filter(Boolean);
    }

    // ---- Reactive bits ----------------------------------------------
    function effectiveStyleId() {
      return pendingStyleId || '__default__';
    }

    function isDefaultBucket() {
      return !pendingStyleId;
    }

    function unconfirmedRowsWithSuggestion() {
      return rowControllers.filter(c => c.isUnconfirmed() && c.hasSuggestion());
    }

    function updateAll() {
      const styleIsDefault = isDefaultBucket();
      const unconfirmed = unconfirmedRowsWithSuggestion();

      styleHint.textContent = styleIsDefault
        ? 'Evidence will land in the default bucket. Type a code (e.g. style number on the spec) to keep this style separate from others.'
        : 'Evidence will be saved under style code "' + pendingStyleId + '".';

      heading.textContent = candidates.length === 1
        ? 'The project has 1 TD correction ready to remember:'
        : 'The project has ' + candidates.length + ' TD corrections ready to remember:';

      const noteParts = [
        styleIsDefault
          ? 'You can still save the project. Evidence will only attach to a real style code once one is set.'
          : 'Saving evidence stores confirmed lines and confirmed missing POMs in the browser so Detect can compare next time.',
      ];
      const confirmedInDialog = pendingMeanings.size;
      if (confirmedInDialog > 0) {
        noteParts.push(confirmedInDialog === 1
          ? '1 meaning will be remembered for this style.'
          : confirmedInDialog + ' meanings will be remembered for this style.');
      }
      note.textContent = noteParts.join(' ');

      bulkBar.style.display = unconfirmed.length >= 2 ? '' : 'none';
      bulkBtn.textContent = 'Confirm top suggestion for '
        + unconfirmed.length + ' POM' + (unconfirmed.length === 1 ? '' : 's');

      bothBtn.textContent = styleIsDefault
        ? 'Save project + evidence (default bucket)'
        : 'Save project + evidence';
    }

    styleInput.addEventListener('input', () => {
      pendingStyleId = styleInput.value.trim();
      updateAll();
    });
    bulkBtn.addEventListener('click', () => {
      let confirmed = 0;
      for (const ctrl of rowControllers) {
        if (ctrl.confirmTop()) confirmed += 1;
      }
      if (confirmed > 0) updateAll();
    });

    updateAll();

    return new Promise(resolve => {
      let settled = false;
      function settle(value) {
        if (settled) return;
        settled = true;
        resolve(value);
      }

      function applyPendingStyleId() {
        const next = pendingStyleId.trim();
        if (next === (state.styleId || '').trim()) return;
        state.styleId = next;
        if (typeof updateUI === 'function') updateUI();
      }

      function applyPendingMeanings() {
        if (typeof confirmPomMeaning !== 'function') return;
        for (const [pom, value] of pendingMeanings.entries()) {
          confirmPomMeaning(pom, value.meaningId);
          // Stamp the candidate so the evidence record carries the
          // newly-confirmed meaning into addStyleEvidence.
          const candidate = candidates.find(c => String(c.pom) === String(pom));
          if (candidate) {
            candidate.meaningId = value.meaningId;
            candidate.meaningLabel = value.label;
          }
        }
      }

      const observer = new MutationObserver(() => {
        if (!document.body.contains(dialog.overlay)) {
          observer.disconnect();
          settle({ action: 'cancel' });
        }
      });
      observer.observe(document.body, { childList: true });

      cancelBtn.addEventListener('click', () => {
        dialog.close();
        settle({ action: 'cancel' });
      });
      onlyBtn.addEventListener('click', () => {
        // Project-only still applies the typed style code — it's a
        // project-level field the TD just edited explicitly. Pending
        // meaning confirmations stay un-committed, matching the user's
        // intent to skip the learning step this round.
        applyPendingStyleId();
        dialog.close();
        settle({ action: 'project-only' });
      });
      bothBtn.addEventListener('click', () => {
        applyPendingStyleId();
        applyPendingMeanings();
        dialog.close();
        settle({ action: 'save-with-evidence', commit: true });
      });
      dialog.open();
      // Focus the style input first when none is set so the TD can type
      // a code immediately; otherwise jump to the primary Save button.
      if (!pendingStyleId) styleInput.focus();
      else bothBtn.focus();
    });
  }

  // ---- src/ui/dialogs/learning-data-shared.js ----
// Transparent Learning panel: pure formatting helpers reused across the
// telemetry, corrections, meanings and evidence tabs.
// Source part for app.js. Run `npm run build` after editing.

  function td(text, className) {
    const cell = document.createElement('td');
    if (className) cell.className = className;
    cell.textContent = text == null ? '' : String(text);
    return cell;
  }

  // ---- Formatters -----------------------------------------------------
  function formatEvidenceTimestamp(iso, withTime) {
    if (!iso) return '';
    const t = Date.parse(iso);
    if (!Number.isFinite(t)) return '';
    const d = new Date(t);
    const pad = (n) => String(n).padStart(2, '0');
    const date = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
    if (!withTime) return date;
    return date + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  }

  function buildSummaryCard({ label, value, tone }) {
    const card = document.createElement('div');
    card.className = 'ld-card';
    const labelEl = document.createElement('div');
    labelEl.className = 'ld-card-label';
    labelEl.textContent = label;
    const valueEl = document.createElement('div');
    valueEl.className = 'ld-card-value' + (tone ? ' ' + tone : '');
    valueEl.textContent = value;
    card.appendChild(labelEl);
    card.appendChild(valueEl);
    return card;
  }

  function statusLabelForRow(status) {
    switch (status) {
      case 'active': return 'Active';
      case 'needs-more-samples': return 'Needs more samples';
      case 'large-correction': return 'Large correction';
      case 'conflicting': return 'Conflicting';
      case 'empty': return 'Empty';
      default: return status;
    }
  }

  // Spread/MAD as a percentage of image dimension — mirrors how the
  // median dx/dy column is displayed so the TD can compare magnitudes
  // at a glance.
  function formatLearningSpread(value) {
    const num = Math.abs(Number(value) || 0);
    const pct = num * 100;
    return '±' + pct.toFixed(1) + '%';
  }

  function formatLearningDelta(value) {
    const num = Number(value) || 0;
    const pct = num * 100;
    const sign = pct > 0 ? '+' : (pct < 0 ? '' : ' ');
    return sign + pct.toFixed(1) + '%';
  }

  function formatViewRole(viewRole) {
    if (!viewRole) return '—';
    const map = {
      front: 'Front',
      back: 'Back',
      side: 'Side',
      inside: 'Inside',
      detail: 'Detail',
    };
    return map[String(viewRole).toLowerCase()] || String(viewRole);
  }

  function formatEvidenceSourceKind(kind) {
    if (!kind) return null;
    switch (kind) {
      case 'td-edited-auto-line': return 'Auto + TD edit';
      case 'manual-confirmed-line': return 'Manual confirm';
      case 'td-deleted-auto-line': return 'Auto removed';
      default: return kind;
    }
  }

  function formatTelemetryDuration(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return '—';
    if (n < 1000) return Math.round(n) + 'ms';
    return (n / 1000).toFixed(n < 10000 ? 1 : 0) + 's';
  }

  function formatTelemetryNumber(value) {
    const n = Number(value);
    return Number.isFinite(n) ? String(Math.round(n * 10) / 10) : '—';
  }

  // ---- src/ui/dialogs/learning-data-tabs.js ----
// Transparent Learning panel: generic reusable tab-shell widget — not
// learning-specific at all, it just takes {id,label,count,build} defs.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Tab shell ------------------------------------------------------
  // Tabs are built lazily — each panel's content is constructed once on
  // first activation so revisiting a tab doesn't lose the expanded-row
  // state from the previous visit.
  function buildLearningTabs(defs) {
    const wrap = document.createElement('div');
    wrap.className = 'ld-tab-shell';

    const bar = document.createElement('div');
    bar.className = 'ld-tabs';
    bar.setAttribute('role', 'tablist');

    const panels = document.createElement('div');
    panels.className = 'ld-tab-panels';

    const built = new Map();
    const buttons = [];
    const panelEls = [];

    defs.forEach((def, idx) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'ld-tab';
      btn.setAttribute('role', 'tab');
      btn.setAttribute('aria-controls', 'ld-tab-panel-' + def.id);
      btn.id = 'ld-tab-' + def.id;
      btn.dataset.tab = def.id;

      const labelEl = document.createElement('span');
      labelEl.textContent = def.label;
      btn.appendChild(labelEl);
      if (Number.isFinite(def.count)) {
        const badge = document.createElement('span');
        badge.className = 'ld-tab-badge';
        badge.textContent = String(def.count);
        btn.appendChild(badge);
      }
      bar.appendChild(btn);
      buttons.push(btn);

      const panel = document.createElement('div');
      panel.className = 'ld-tab-panel';
      panel.setAttribute('role', 'tabpanel');
      panel.id = 'ld-tab-panel-' + def.id;
      panel.setAttribute('aria-labelledby', 'ld-tab-' + def.id);
      panels.appendChild(panel);
      panelEls.push(panel);

      btn.addEventListener('click', () => activate(idx));
    });

    function activate(activeIdx) {
      for (let i = 0; i < buttons.length; i++) {
        const isActive = i === activeIdx;
        buttons[i].classList.toggle('is-active', isActive);
        buttons[i].setAttribute('aria-selected', isActive ? 'true' : 'false');
        buttons[i].tabIndex = isActive ? 0 : -1;
        panelEls[i].classList.toggle('is-active', isActive);
        if (isActive && !built.has(i)) {
          const content = defs[i].build();
          if (content) panelEls[i].appendChild(content);
          built.set(i, true);
        }
      }
    }

    wrap.appendChild(bar);
    wrap.appendChild(panels);
    activate(0);
    return wrap;
  }

  // ---- src/ui/dialogs/learning-data-telemetry.js ----
// Transparent Learning panel: Telemetry tab — reaches into
// getAutoTelemetryReport/getAutoTelemetryLog from src/auto/telemetry/*
// rather than the learning/meaning/evidence stores the other tabs use.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Telemetry ------------------------------------------------------
  function buildLearningTelemetrySection(telemetry) {
    const section = document.createElement('div');
    section.className = 'ld-section';

    if (!telemetry || telemetry.count === 0) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'No completed Auto Mode telemetry sessions yet. Run Detect, generate drafts, and apply or discard them to record one.';
      section.appendChild(empty);
      return section;
    }

    const intro = document.createElement('p');
    intro.className = 'ld-section-note';
    intro.textContent = 'Last ' + telemetry.count + ' completed Auto Mode session'
      + (telemetry.count === 1 ? '' : 's')
      + '. Medians show the current speed baseline for Detect-to-POM work.';
    section.appendChild(intro);

    const summaryGrid = document.createElement('div');
    summaryGrid.className = 'ld-summary-grid';
    summaryGrid.appendChild(buildSummaryCard({
      label: 'Median detect',
      value: formatTelemetryDuration(telemetry.medians.detect_ms),
      tone: telemetry.medians.detect_ms == null ? 'muted' : null,
    }));
    summaryGrid.appendChild(buildSummaryCard({
      label: 'Median edit',
      value: formatTelemetryDuration(telemetry.medians.edit_ms),
      tone: telemetry.medians.edit_ms == null ? 'muted' : null,
    }));
    summaryGrid.appendChild(buildSummaryCard({
      label: 'Median apply',
      value: formatTelemetryDuration(telemetry.medians.apply_ms),
      tone: telemetry.medians.apply_ms == null ? 'muted' : null,
    }));
    summaryGrid.appendChild(buildSummaryCard({
      label: 'Median anchors dragged',
      value: formatTelemetryNumber(telemetry.medians.anchors_dragged),
      tone: telemetry.medians.anchors_dragged === 0 ? 'ok' : null,
    }));
    summaryGrid.appendChild(buildSummaryCard({
      label: 'Touchless sessions',
      value: telemetry.touchlessCount + '/' + telemetry.count,
      tone: telemetry.touchlessCount > 0 ? 'ok' : 'muted',
    }));
    section.appendChild(summaryGrid);

    const exportRow = document.createElement('div');
    exportRow.className = 'picker-footer';
    const spacer = document.createElement('span');
    spacer.style.flex = '1';
    const exportBtn = document.createElement('button');
    exportBtn.type = 'button';
    exportBtn.className = 'picker-btn';
    exportBtn.textContent = 'Export telemetry JSON';
    exportBtn.addEventListener('click', () => exportAutoTelemetryJson());
    exportRow.appendChild(spacer);
    exportRow.appendChild(exportBtn);
    section.appendChild(exportRow);

    const table = document.createElement('table');
    table.className = 'ld-table';
    table.innerHTML =
      '<thead><tr>' +
        '<th>Completed</th>' +
        '<th>Sketch</th>' +
        '<th class="ld-num">Detect</th>' +
        '<th class="ld-num">Edit</th>' +
        '<th class="ld-num">Apply</th>' +
        '<th class="ld-num">Anchors dragged</th>' +
        '<th class="ld-num">Drafts edited</th>' +
        '<th>Status</th>' +
      '</tr></thead>';
    const tbody = document.createElement('tbody');
    for (const session of telemetry.sessions) {
      const summary = session.summary || {};
      const tr = document.createElement('tr');
      tr.appendChild(td(session.completed_at ? formatEvidenceTimestamp(session.completed_at, true) : '—'));
      tr.appendChild(td(session.sketch_id || '—'));
      tr.appendChild(td(formatTelemetryDuration(summary.detect_ms), 'ld-num'));
      tr.appendChild(td(formatTelemetryDuration(summary.edit_ms), 'ld-num'));
      tr.appendChild(td(formatTelemetryDuration(summary.apply_ms), 'ld-num'));
      tr.appendChild(td(formatTelemetryNumber(summary.anchors_dragged), 'ld-num'));
      tr.appendChild(td(formatTelemetryNumber(summary.drafts_edited), 'ld-num'));
      const statusCell = td('');
      const chip = document.createElement('span');
      chip.className = 'ld-status ' + (summary.touchless ? 'ld-status-active' : 'ld-status-empty');
      chip.textContent = summary.touchless ? 'Touchless' : 'Touched';
      statusCell.appendChild(chip);
      tr.appendChild(statusCell);
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    section.appendChild(table);
    return section;
  }

  function exportAutoTelemetryJson() {
    const payload = {
      exportedAt: new Date().toISOString(),
      sessions: (typeof getAutoTelemetryLog === 'function') ? getAutoTelemetryLog() : [],
    };
    const blob = new Blob([JSON.stringify(payload, null, 2) + '\n'], { type: 'application/json' });
    downloadBlob(blob, 'auto-telemetry-log.json');
  }

  // ---- src/ui/dialogs/learning-data-summary.js ----
// Transparent Learning panel: always-visible top summary strip above the
// tabs.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Top summary ----------------------------------------------------
  // Five focused fields TDs use to gauge style readiness at a glance.
  // confirmedLinePomCount counts POMs with at least one confirmed line
  // (not raw record count) so the same POM saved over many sessions
  // doesn't inflate the headline.
  function buildLearningTopSummary(learning, meanings, evidence) {
    const section = document.createElement('div');
    section.className = 'ld-section ld-top-summary';

    const styleLabel = meanings
      ? (meanings.currentStyleIsDefault
          ? 'Default (no style code)'
          : meanings.currentStyleId)
      : '—';

    let confirmedLinePomCount = 0;
    let absentPomCount = 0;
    let needsReviewPomCount = 0;
    if (evidence && Array.isArray(evidence.rows)) {
      for (const row of evidence.rows) {
        if (row.status === 'confirmed') confirmedLinePomCount += 1;
        else if (row.status === 'absent-confirmed') absentPomCount += 1;
        else needsReviewPomCount += 1;
      }
    }

    const lastLearned = pickLatestLearningTimestamp(learning, evidence);

    const items = [
      {
        label: 'Current style',
        value: styleLabel,
        tone: meanings && meanings.currentStyleIsDefault ? 'muted' : null,
      },
      {
        label: 'Confirmed lines',
        value: String(confirmedLinePomCount) + ' POM' + (confirmedLinePomCount === 1 ? '' : 's'),
        tone: confirmedLinePomCount > 0 ? 'ok' : 'muted',
      },
      {
        label: 'Absent POMs',
        value: absentPomCount > 0 ? String(absentPomCount) : '0',
        tone: absentPomCount > 0 ? 'warn' : 'muted',
      },
      {
        label: 'Needs review',
        value: needsReviewPomCount > 0 ? String(needsReviewPomCount) : '0',
        tone: needsReviewPomCount > 0 ? 'attention' : 'muted',
      },
      {
        label: 'Last learned',
        value: lastLearned ? formatEvidenceTimestamp(lastLearned, true) : '—',
        tone: lastLearned ? null : 'muted',
      },
    ];

    const grid = document.createElement('div');
    grid.className = 'ld-summary-grid ld-summary-grid-top';
    for (const it of items) grid.appendChild(buildSummaryCard(it));
    section.appendChild(grid);
    return section;
  }

  function pickLatestLearningTimestamp(learning, evidence) {
    let best = 0;
    if (evidence && evidence.lastUpdated) {
      const t = Date.parse(evidence.lastUpdated);
      if (Number.isFinite(t) && t > best) best = t;
    }
    if (learning && Array.isArray(learning.rows)) {
      for (const row of learning.rows) {
        const t = Number(row.lastTs) || 0;
        if (t > best) best = t;
      }
    }
    return best > 0 ? new Date(best).toISOString() : null;
  }

  // ---- src/ui/dialogs/learning-data-corrections.js ----
// Transparent Learning panel: Learning Corrections (anchor calibration) tab.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Learning Corrections (anchor calibration) ----------------------
  function buildLearningAnchorSection(learning) {
    const section = document.createElement('div');
    section.className = 'ld-section';

    if (!learning || learning.rows.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'No anchor corrections recorded yet. Drag an Auto Mode anchor or label a manual POM line to start.';
      section.appendChild(empty);
      return section;
    }

    const conflictingCount = Number(learning.conflictingCount) || 0;
    const intro = document.createElement('p');
    intro.className = 'ld-section-note';
    const introParts = [
      'A bucket goes Active after ' + learning.minSamples + ' samples.',
      'Median offsets are clamped to ±' + Math.round(learning.clampLimit * 100) + '% of the image size.',
      'Anchor samples total: ' + learning.totalSamples + '.',
      'Parameter samples: ' + learning.totalParamSamples + '.',
    ];
    if (conflictingCount > 0) {
      introParts.push(conflictingCount === 1
        ? '1 bucket is Conflicting — its spread dwarfs its median, so bias is halved when applied.'
        : conflictingCount + ' buckets are Conflicting — spread dwarfs median, so bias is halved when applied.');
    }
    // Phase 8: corrections by suspected pipeline stage — tells the TD (and
    // engineers) WHERE the engine loses accuracy, not just how often.
    const stageCounts = learning.stageCounts || {};
    const stageLabels = {
      'anchor-nudge': 'small nudges',
      'landmark-wrong': 'landmark wrong',
      'contour-missing': 'contour/seam evidence missing',
      'geometry-wrong': 'geometry frame weak',
      'segmentation-weak': 'segmentation weak',
      unknown: 'no detection context',
      unattributed: 'recorded before stage tracking',
    };
    const stageBits = Object.keys(stageCounts)
      .filter(k => stageCounts[k] > 0)
      .sort((x, y) => stageCounts[y] - stageCounts[x])
      .map(k => (stageLabels[k] || k) + ': ' + stageCounts[k]);
    if (stageBits.length) {
      introParts.push('Suspected cause of corrections — ' + stageBits.join(' · ') + '.');
    }
    intro.textContent = introParts.join(' ');
    section.appendChild(intro);

    const table = document.createElement('table');
    table.className = 'ld-table';
    table.innerHTML =
      '<thead><tr>' +
        '<th>Anchor</th>' +
        '<th>View role</th>' +
        '<th class="ld-num">Samples</th>' +
        '<th class="ld-num">Median dx</th>' +
        '<th class="ld-num">Median dy</th>' +
        '<th class="ld-num">Spread dx</th>' +
        '<th class="ld-num">Spread dy</th>' +
        '<th>Status</th>' +
      '</tr></thead>';
    const tbody = document.createElement('tbody');
    for (const row of learning.rows) {
      const tr = document.createElement('tr');
      tr.appendChild(td(row.kind));
      tr.appendChild(td(row.viewRole || '—'));
      tr.appendChild(td(String(row.samples), 'ld-num'));
      tr.appendChild(td(formatLearningDelta(row.medianDx), 'ld-num'));
      tr.appendChild(td(formatLearningDelta(row.medianDy), 'ld-num'));
      tr.appendChild(td(formatLearningSpread(row.madDx), 'ld-num'));
      tr.appendChild(td(formatLearningSpread(row.madDy), 'ld-num'));
      const statusCell = td('');
      const chip = document.createElement('span');
      chip.className = 'ld-status ld-status-' + row.status;
      chip.textContent = statusLabelForRow(row.status);
      statusCell.appendChild(chip);
      tr.appendChild(statusCell);
      tbody.appendChild(tr);
    }
    table.appendChild(tbody);
    section.appendChild(table);
    return section;
  }

  // ---- src/ui/dialogs/learning-data-meanings.js ----
// Transparent Learning panel: POM Meanings tab.
// Source part for app.js. Run `npm run build` after editing.

  // ---- POM Meanings ---------------------------------------------------
  function buildLearningMeaningsSection(meanings) {
    const section = document.createElement('div');
    section.className = 'ld-section';

    if (!meanings) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'Meaning store not available.';
      section.appendChild(empty);
      return section;
    }

    const intro = document.createElement('p');
    intro.className = 'ld-section-note';
    intro.textContent = meanings.currentStyleIsDefault
      ? 'Showing the default bucket (no Style code set). Set a Style code to keep per-style meanings separate.'
      : 'Showing meanings confirmed for style "' + meanings.currentStyleId + '". ' +
        meanings.fixedPomCount + ' fixed · ' + meanings.confirmedForCurrent + ' confirmed · ' +
        meanings.customCount + ' custom across all styles.';
    section.appendChild(intro);

    if (meanings.currentRows.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'No POM meanings resolved for this style yet. Label a manual POM 6+ line to confirm one.';
      section.appendChild(empty);
    } else {
      const table = document.createElement('table');
      table.className = 'ld-table';
      table.innerHTML =
        '<thead><tr>' +
          '<th class="ld-num">POM</th>' +
          '<th>Meaning</th>' +
          '<th>Start anchor</th>' +
          '<th>End anchor</th>' +
          '<th>Source</th>' +
        '</tr></thead>';
      const tbody = document.createElement('tbody');
      for (const row of meanings.currentRows) {
        const m = row.meaning;
        const tr = document.createElement('tr');
        tr.appendChild(td(row.pom, 'ld-num'));
        tr.appendChild(td(m && m.label || '—'));
        tr.appendChild(td(m && m.start || '—'));
        tr.appendChild(td(m && m.end || '—'));
        const sourceCell = td('');
        const chip = document.createElement('span');
        chip.className = 'ld-status ld-status-' + (row.source === 'fixed' ? 'fixed' : 'confirmed');
        chip.textContent = row.source === 'fixed' ? 'Fixed' : 'Confirmed';
        sourceCell.appendChild(chip);
        tr.appendChild(sourceCell);
        tbody.appendChild(tr);
      }
      table.appendChild(tbody);
      section.appendChild(table);
    }

    if (meanings.knownStyles.length > 1
        || (meanings.knownStyles.length === 1
            && meanings.knownStyles[0].styleId !== meanings.currentStyleId)) {
      const styleHead = document.createElement('p');
      styleHead.className = 'ld-section-note';
      styleHead.textContent = 'Confirmed POMs per known style:';
      section.appendChild(styleHead);
      const ul = document.createElement('ul');
      ul.className = 'ld-style-list';
      for (const s of meanings.knownStyles) {
        const li = document.createElement('li');
        const name = (s.styleId === meanings.defaultStyleId)
          ? 'default bucket'
          : 'style "' + s.styleId + '"';
        const tag = (s.styleId === meanings.currentStyleId) ? ' (current)' : '';
        li.textContent = name + tag + ' — ' + s.confirmedCount + ' confirmed';
        ul.appendChild(li);
      }
      section.appendChild(ul);
    }
    return section;
  }

  // ---- src/ui/dialogs/learning-data-evidence.js ----
// Transparent Learning panel: Style Evidence tab, incl. expandable
// per-record detail rows.
// Improved columns: POM, Status, Meaning, View, Evidence Source, Records,
// Last Saved. Each POM row is expandable to show the individual records
// (id, timestamp, source, view) — TDs can audit exactly what was saved
// without diving into localStorage.
// Source part for app.js. Run `npm run build` after editing.

  function buildLearningEvidenceSection(evidence, records, meanings) {
    const section = document.createElement('div');
    section.className = 'ld-section';

    if (!evidence) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'Style evidence store not available.';
      section.appendChild(empty);
      return section;
    }

    const styleLabel = meanings && meanings.currentStyleIsDefault
      ? 'the default bucket (no Style code)'
      : 'style "' + evidence.styleId + '"';
    const intro = document.createElement('p');
    intro.className = 'ld-section-note';
    intro.textContent = 'TD-confirmed POM lines remembered for ' + styleLabel
      + (evidence.lastUpdated ? ' · last updated ' + formatEvidenceTimestamp(evidence.lastUpdated) : '')
      + '. Evidence stays separate from calibration residuals and POM meanings.';
    section.appendChild(intro);

    if (evidence.rows.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'ld-empty';
      empty.textContent = 'No style evidence yet. Future Save flows will offer to store corrected POM lines here.';
      section.appendChild(empty);
      return section;
    }

    const pom7Absent = evidence.rows.find(r =>
      String(r.pom) === '7' && r.status === 'absent-confirmed');
    if (pom7Absent) {
      const banner = document.createElement('div');
      banner.className = 'ld-callout ld-callout-absent';
      banner.textContent = 'POM 7 is confirmed absent for this style. Auto Mode will skip drawing POM 7.';
      section.appendChild(banner);
    }

    const recordsByPom = groupRecordsByPom(records);

    const table = document.createElement('table');
    table.className = 'ld-table ld-table-evidence';
    table.innerHTML =
      '<thead><tr>' +
        '<th class="ld-expand-col"></th>' +
        '<th class="ld-num">POM</th>' +
        '<th>Status</th>' +
        '<th>Meaning</th>' +
        '<th>View</th>' +
        '<th>Evidence Source</th>' +
        '<th class="ld-num">Records</th>' +
        '<th>Last Saved</th>' +
      '</tr></thead>';
    const tbody = document.createElement('tbody');
    for (const row of evidence.rows) {
      const pomRecords = recordsByPom.get(String(row.pom)) || [];
      const isAbsent = row.status === 'absent-confirmed';
      const isPom7 = String(row.pom) === '7';

      const tr = document.createElement('tr');
      tr.className = 'ld-evidence-row';
      if (isAbsent) tr.classList.add('ld-evidence-row-absent');
      if (isAbsent && isPom7) tr.classList.add('ld-evidence-row-pom7-absent');

      const expandCell = td('', 'ld-expand-col');
      const expandBtn = document.createElement('button');
      expandBtn.type = 'button';
      expandBtn.className = 'ld-expand-btn';
      expandBtn.setAttribute('aria-label', 'Show records for POM ' + row.pom);
      expandBtn.textContent = '▸';
      expandBtn.disabled = pomRecords.length === 0;
      expandCell.appendChild(expandBtn);
      tr.appendChild(expandCell);

      tr.appendChild(td(row.pom, 'ld-num'));

      const statusCell = td('');
      statusCell.appendChild(buildEvidenceStatusChip(row.status));
      tr.appendChild(statusCell);

      tr.appendChild(td(row.meaningLabel || row.meaningId || '—'));
      tr.appendChild(td(formatViewRole(row.viewRole)));
      tr.appendChild(td(formatEvidenceSource(row.source, pomRecords)));
      tr.appendChild(td(String(row.count), 'ld-num'));
      tr.appendChild(td(row.lastSavedAt ? formatEvidenceTimestamp(row.lastSavedAt, true) : '—'));

      tbody.appendChild(tr);

      const detailRow = document.createElement('tr');
      detailRow.className = 'ld-detail-row';
      detailRow.hidden = true;
      const detailCell = document.createElement('td');
      detailCell.colSpan = 8;
      detailCell.className = 'ld-detail-cell';
      detailCell.appendChild(buildEvidenceDetail(row, pomRecords));
      detailRow.appendChild(detailCell);
      tbody.appendChild(detailRow);

      expandBtn.addEventListener('click', () => {
        if (expandBtn.disabled) return;
        const open = !detailRow.hidden;
        detailRow.hidden = open;
        expandBtn.classList.toggle('is-open', !open);
        expandBtn.textContent = open ? '▸' : '▾';
        expandBtn.setAttribute(
          'aria-label',
          (open ? 'Show' : 'Hide') + ' records for POM ' + row.pom,
        );
      });
    }
    table.appendChild(tbody);
    section.appendChild(table);
    return section;
  }

  function groupRecordsByPom(records) {
    const out = new Map();
    if (!Array.isArray(records)) return out;
    for (const rec of records) {
      const key = rec.pom != null ? String(rec.pom) : '?';
      let arr = out.get(key);
      if (!arr) { arr = []; out.set(key, arr); }
      arr.push(rec);
    }
    return out;
  }

  function buildEvidenceStatusChip(status) {
    const s = status || 'unknown';
    const chip = document.createElement('span');
    if (s === 'confirmed') {
      chip.className = 'ld-status ld-status-confirmed';
      chip.textContent = 'Confirmed';
    } else if (s === 'absent-confirmed') {
      chip.className = 'ld-status ld-status-absent';
      chip.textContent = 'Absent';
    } else if (s === 'pending') {
      chip.className = 'ld-status ld-status-needs-more-samples';
      chip.textContent = 'Needs review';
    } else {
      chip.className = 'ld-status ld-status-empty';
      chip.textContent = s === 'unknown' ? 'Unknown' : s;
    }
    return chip;
  }

  function formatEvidenceSource(primarySource, records) {
    const kinds = new Set();
    if (primarySource) kinds.add(primarySource);
    if (Array.isArray(records)) {
      for (const r of records) if (r && r.source) kinds.add(r.source);
    }
    if (kinds.size === 0) return '—';
    return Array.from(kinds).map(formatEvidenceSourceKind).join(', ');
  }

  // ---- Expanded row detail --------------------------------------------
  // Shows every persisted record under this POM. We stick to metadata
  // the TD can verify (when, where, what shape) — coordinate dumps would
  // overwhelm without helping audit decisions.
  function buildEvidenceDetail(row, records) {
    const wrap = document.createElement('div');
    wrap.className = 'ld-detail';

    const header = document.createElement('div');
    header.className = 'ld-detail-header';
    header.textContent = 'POM ' + row.pom + ' · ' + (row.meaningLabel || row.meaningId || 'no meaning')
      + ' · ' + records.length + ' record' + (records.length === 1 ? '' : 's');
    wrap.appendChild(header);

    if (!records || records.length === 0) {
      const empty = document.createElement('div');
      empty.className = 'ld-detail-empty';
      empty.textContent = 'No individual records recorded for this POM.';
      wrap.appendChild(empty);
      return wrap;
    }

    const list = document.createElement('ul');
    list.className = 'ld-detail-list';
    const sorted = records.slice().sort((a, b) => {
      const ta = a.savedAt ? Date.parse(a.savedAt) : 0;
      const tb = b.savedAt ? Date.parse(b.savedAt) : 0;
      return tb - ta;
    });
    for (const rec of sorted) {
      list.appendChild(buildEvidenceDetailItem(rec));
    }
    wrap.appendChild(list);
    return wrap;
  }

  function buildEvidenceDetailItem(rec) {
    const li = document.createElement('li');
    li.className = 'ld-detail-item';

    const title = document.createElement('div');
    title.className = 'ld-detail-item-title';
    const sourceLabel = formatEvidenceSourceKind(rec.source) || '—';
    title.textContent = sourceLabel + (rec.tdStatus === 'absent-confirmed' ? ' · Absent' : '');
    if (rec.tdStatus === 'absent-confirmed') title.classList.add('is-absent');
    li.appendChild(title);

    const meta = document.createElement('dl');
    meta.className = 'ld-detail-meta';
    appendMetaPair(meta, 'Saved', rec.savedAt ? formatEvidenceTimestamp(rec.savedAt, true) : '—');
    appendMetaPair(meta, 'View', formatViewRole(rec.viewRole));
    appendMetaPair(meta, 'Line type', rec.line ? rec.line.type : (rec.tdStatus === 'absent-confirmed' ? 'none (absent)' : '—'));
    if (rec.sourceImageId) appendMetaPair(meta, 'Image', String(rec.sourceImageId));
    if (rec.appRuleVersion) appendMetaPair(meta, 'Rule version', String(rec.appRuleVersion));
    if (rec.templateVersion) appendMetaPair(meta, 'Template', String(rec.templateVersion));
    if (rec.absentReason) appendMetaPair(meta, 'Absent reason', String(rec.absentReason));
    li.appendChild(meta);

    return li;
  }

  function appendMetaPair(dl, label, value) {
    const dt = document.createElement('dt');
    dt.textContent = label;
    const dd = document.createElement('dd');
    dd.textContent = value;
    dl.appendChild(dt);
    dl.appendChild(dd);
  }

  // ---- src/ui/dialogs/learning-data-dialog.js ----
// Transparent Learning panel (read-only TD review).
// Reads from summarizeLearningStore + summarizeMeaningStore +
// summarizeStyleEvidence + listStyleEvidence. Renders a top summary plus
// a tabbed body: Style Evidence, Learning Corrections, POM Meanings.
// No mutations — Reset and Manage Meanings live in the Auto Mode Manage
// menu and stay there. Opens regardless of mode so the TD can audit prior
// calibration before switching into Auto Mode.
// Source part for app.js. Run `npm run build` after editing.
//
// This is the orchestrator only — it wires the 4 tab defs to their build()
// functions. The shared formatters live in learning-data-shared.js; the
// generic tab-shell widget lives in learning-data-tabs.js; each tab's body
// lives in its own file: learning-data-telemetry.js, learning-data-summary.js,
// learning-data-corrections.js, learning-data-meanings.js,
// learning-data-evidence.js.

  function openLearningDataDialog() {
    const learning = (typeof summarizeLearningStore === 'function') ? summarizeLearningStore() : null;
    const meanings = (typeof summarizeMeaningStore === 'function') ? summarizeMeaningStore() : null;
    const styleId = (typeof currentStyleId === 'function') ? currentStyleId() : null;
    const evidence = (typeof summarizeStyleEvidence === 'function' && styleId != null)
      ? summarizeStyleEvidence(styleId)
      : null;
    const evidenceRecords = (typeof listStyleEvidence === 'function' && styleId != null)
      ? listStyleEvidence(styleId)
      : [];
    const telemetry = (typeof getAutoTelemetryReport === 'function')
      ? getAutoTelemetryReport(10)
      : null;

    const dialog = buildDialog({
      title: 'Learning data',
      sub: 'What the tool has learned from your corrections.',
    });
    dialog.panel.classList.add('ld-wide');

    const body = document.createElement('div');
    body.className = 'dialog-body learning-data-body';

    body.appendChild(buildLearningTopSummary(learning, meanings, evidence));

    const tabs = buildLearningTabs([
      {
        id: 'evidence',
        label: 'Style Evidence',
        count: evidence ? evidence.pomRowCount : 0,
        build: () => buildLearningEvidenceSection(evidence, evidenceRecords, meanings),
      },
      {
        id: 'corrections',
        label: 'Learning Corrections',
        count: learning ? learning.rows.length : 0,
        build: () => buildLearningAnchorSection(learning),
      },
      {
        id: 'meanings',
        label: 'POM Meanings',
        count: meanings ? meanings.currentRows.length : 0,
        build: () => buildLearningMeaningsSection(meanings),
      },
      {
        id: 'telemetry',
        label: 'Telemetry',
        count: telemetry ? telemetry.count : 0,
        build: () => buildLearningTelemetrySection(telemetry),
      },
    ]);
    body.appendChild(tabs);

    dialog.panel.appendChild(body);

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    const note = document.createElement('span');
    note.className = 'learning-data-foot-note';
    note.textContent = 'Use the Manage menu to reset calibration or edit POM meanings.';
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'picker-btn primary';
    closeBtn.textContent = 'Close';
    closeBtn.addEventListener('click', dialog.close);
    footer.appendChild(note);
    footer.appendChild(closeBtn);
    dialog.panel.appendChild(footer);

    dialog.open();
    closeBtn.focus();
  }

  // ---- src/ui/dialogs/library-shared.js ----
// Library dialog: cross-view grouping/formatting helpers used by BOTH the
// "By Style" card grid and the "By Save" flat list.
// Source part for app.js. Run `npm run build` after editing.

  function groupLibraryEntriesByStyle(entries) {
    const byStyle = new Map();
    entries.forEach(entry => {
      const key = entry.styleId || '';
      if (!byStyle.has(key)) byStyle.set(key, []);
      byStyle.get(key).push(entry);
    });
    const groups = [];
    byStyle.forEach((items, styleId) => {
      items.sort((a, b) => (b.savedAt || '').localeCompare(a.savedAt || ''));
      groups.push({ styleId, entries: items, latestSavedAt: items[0] ? items[0].savedAt : '' });
    });
    groups.sort((a, b) => {
      if (!a.styleId && b.styleId) return 1;
      if (a.styleId && !b.styleId) return -1;
      return (b.latestSavedAt || '').localeCompare(a.latestSavedAt || '');
    });
    return groups;
  }

  function countDistinctStyles(entries) {
    const seen = new Set();
    entries.forEach(e => seen.add(e.styleId || ''));
    return seen.size;
  }

  function formatLibraryDate(iso) {
    if (!iso) return '—';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    const pad = (n) => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate())
      + '  ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
  }

  function buildBadge(text, bg, fg) {
    const el = document.createElement('span');
    el.textContent = text;
    el.style.fontSize = '11px';
    el.style.fontWeight = '600';
    el.style.padding = '2px 8px';
    el.style.borderRadius = '999px';
    el.style.background = bg;
    el.style.color = fg;
    return el;
  }

  // ---- src/ui/dialogs/library-list-view.js ----
// Library dialog: "By Save" flat-list rendering — every snapshot is its own
// row, grouped under a per-style header.
// Source part for app.js. Run `npm run build` after editing.

  function renderLibraryList(container, entries, handlers) {
    container.innerHTML = '';
    if (!entries.length) {
      const empty = document.createElement('div');
      empty.style.padding = '32px 16px';
      empty.style.textAlign = 'center';
      empty.style.color = 'var(--muted)';
      empty.style.fontSize = '13px';
      empty.textContent = 'No projects saved yet. Use Save to archive the current board.';
      container.appendChild(empty);
      return;
    }
    const groups = groupLibraryEntriesByStyle(entries);
    groups.forEach(group => {
      const header = document.createElement('div');
      header.style.padding = '8px 12px';
      header.style.background = '#f1f1f4';
      header.style.borderTop = '1px solid #e6e6ea';
      header.style.borderBottom = '1px solid #e6e6ea';
      header.style.fontSize = '12px';
      header.style.fontWeight = '600';
      header.style.color = 'var(--text)';
      header.textContent = (group.styleId || '(no style code)')
        + '   ·   ' + group.entries.length + ' save' + (group.entries.length === 1 ? '' : 's');
      container.appendChild(header);
      group.entries.forEach(entry => {
        container.appendChild(buildLibraryRow(entry, handlers));
      });
    });
  }

  function buildLibraryRow(entry, handlers) {
    const row = document.createElement('div');
    row.className = 'library-row';
    row.style.display = 'flex';
    row.style.gap = '12px';
    row.style.alignItems = 'center';
    row.style.padding = '10px 12px';
    row.style.borderBottom = '1px solid #ececf0';
    row.style.background = '#fff';

    const thumb = document.createElement('div');
    thumb.style.width = '64px';
    thumb.style.height = '64px';
    thumb.style.flex = '0 0 64px';
    thumb.style.borderRadius = '6px';
    thumb.style.border = '1px solid #e0e0e6';
    thumb.style.background = '#f5f5f7 center/contain no-repeat';
    thumb.style.overflow = 'hidden';
    if (entry.thumbnailDataURL) {
      thumb.style.backgroundImage = 'url("' + entry.thumbnailDataURL.replace(/"/g, '%22') + '")';
    } else {
      thumb.style.display = 'flex';
      thumb.style.alignItems = 'center';
      thumb.style.justifyContent = 'center';
      thumb.style.color = '#9ca3af';
      thumb.style.fontSize = '11px';
      thumb.textContent = 'no image';
    }
    row.appendChild(thumb);

    const info = document.createElement('div');
    info.style.flex = '1';
    info.style.minWidth = '0';

    const title = document.createElement('div');
    title.style.fontSize = '13px';
    title.style.fontWeight = '600';
    title.style.color = 'var(--text)';
    title.textContent = entry.styleId || '(no style code)';
    info.appendChild(title);

    const date = document.createElement('div');
    date.style.fontSize = '12px';
    date.style.color = 'var(--muted)';
    date.textContent = formatLibraryDate(entry.savedAt);
    info.appendChild(date);

    const counts = document.createElement('div');
    counts.style.fontSize = '11.5px';
    counts.style.color = 'var(--muted)';
    counts.style.marginTop = '2px';
    const parts = [];
    parts.push((entry.annotationCount || 0) + ' line' + (entry.annotationCount === 1 ? '' : 's'));
    parts.push((entry.imageCount || 0) + ' image' + (entry.imageCount === 1 ? '' : 's'));
    if (entry.confirmedPomCount) parts.push(entry.confirmedPomCount + ' confirmed POM' + (entry.confirmedPomCount === 1 ? '' : 's'));
    counts.textContent = parts.join('  ·  ');
    info.appendChild(counts);

    row.appendChild(info);

    const actions = document.createElement('div');
    actions.style.display = 'flex';
    actions.style.gap = '6px';
    actions.style.flex = '0 0 auto';

    const openBtn = document.createElement('button');
    openBtn.type = 'button';
    openBtn.className = 'picker-btn primary';
    openBtn.textContent = 'Open';
    openBtn.style.fontSize = '12px';
    openBtn.style.padding = '5px 12px';
    openBtn.addEventListener('click', () => handlers.onOpen(entry));

    const downloadBtn = document.createElement('button');
    downloadBtn.type = 'button';
    downloadBtn.className = 'picker-btn';
    downloadBtn.textContent = 'JSON';
    downloadBtn.title = 'Download this snapshot as a .json file';
    downloadBtn.style.fontSize = '12px';
    downloadBtn.style.padding = '5px 10px';
    downloadBtn.addEventListener('click', () => handlers.onDownload(entry));

    const deleteBtn = document.createElement('button');
    deleteBtn.type = 'button';
    deleteBtn.className = 'picker-btn';
    deleteBtn.textContent = 'Delete';
    deleteBtn.style.fontSize = '12px';
    deleteBtn.style.padding = '5px 10px';
    deleteBtn.style.color = '#b91c1c';
    deleteBtn.addEventListener('click', () => handlers.onDelete(entry));

    actions.appendChild(openBtn);
    actions.appendChild(downloadBtn);
    actions.appendChild(deleteBtn);
    row.appendChild(actions);

    return row;
  }

  // ---- src/ui/dialogs/library-grid-view.js ----
// Library dialog: "By Style" card-grid rendering — one card per styleId,
// aggregated counts + evidence/meaning badges.
// Source part for app.js. Run `npm run build` after editing.

  function renderStyleGridView(container, entries, handlers) {
    container.innerHTML = '';
    if (!entries.length) {
      const empty = document.createElement('div');
      empty.style.padding = '32px 16px';
      empty.style.textAlign = 'center';
      empty.style.color = 'var(--muted)';
      empty.style.fontSize = '13px';
      empty.textContent = 'No styles yet. Save the current board to start building the library.';
      container.appendChild(empty);
      return;
    }
    const groups = groupLibraryEntriesByStyle(entries);
    groups.forEach(group => {
      container.appendChild(buildStyleCard(group, handlers));
    });
  }

  function styleMemoryBadges(styleId) {
    let evidenceCount = 0;
    let meaningCount = 0;
    if (styleId && typeof summarizeStyleEvidence === 'function') {
      try {
        const s = summarizeStyleEvidence(styleId);
        evidenceCount = (s && s.totalRecords) || 0;
      } catch (err) { /* memory store may be uninitialized in test contexts */ }
    }
    if (styleId && typeof listConfirmedMeanings === 'function') {
      try {
        meaningCount = (listConfirmedMeanings(styleId) || []).length;
      } catch (err) { /* same as above */ }
    }
    return { evidenceCount, meaningCount };
  }

  function buildStyleCard(group, handlers) {
    const styleId = group.styleId;
    const latest = group.entries[0] || null;
    const saveCount = group.entries.length;
    const totalLines = group.entries.reduce((sum, e) => sum + (e.annotationCount || 0), 0);
    const totalImages = group.entries.reduce((sum, e) => sum + (e.imageCount || 0), 0);
    const totalConfirmedPoms = group.entries.reduce((sum, e) => sum + (e.confirmedPomCount || 0), 0);
    const { evidenceCount, meaningCount } = styleMemoryBadges(styleId);

    const row = document.createElement('div');
    row.className = 'library-style-card';
    row.style.display = 'flex';
    row.style.gap = '14px';
    row.style.alignItems = 'stretch';
    row.style.padding = '12px 14px';
    row.style.borderBottom = '1px solid #ececf0';
    row.style.background = '#fff';

    const thumb = document.createElement('div');
    thumb.style.width = '88px';
    thumb.style.height = '88px';
    thumb.style.flex = '0 0 88px';
    thumb.style.borderRadius = '8px';
    thumb.style.border = '1px solid #e0e0e6';
    thumb.style.background = '#f5f5f7 center/contain no-repeat';
    thumb.style.overflow = 'hidden';
    const cover = latest && latest.thumbnailDataURL;
    if (cover) {
      thumb.style.backgroundImage = 'url("' + cover.replace(/"/g, '%22') + '")';
    } else {
      thumb.style.display = 'flex';
      thumb.style.alignItems = 'center';
      thumb.style.justifyContent = 'center';
      thumb.style.color = '#9ca3af';
      thumb.style.fontSize = '11px';
      thumb.textContent = 'no image';
    }
    row.appendChild(thumb);

    const info = document.createElement('div');
    info.style.flex = '1';
    info.style.minWidth = '0';
    info.style.display = 'flex';
    info.style.flexDirection = 'column';
    info.style.justifyContent = 'space-between';

    const title = document.createElement('div');
    title.style.fontSize = '14px';
    title.style.fontWeight = '600';
    title.style.color = 'var(--text)';
    title.textContent = styleId || '(no style code)';
    info.appendChild(title);

    const lastSeen = document.createElement('div');
    lastSeen.style.fontSize = '12px';
    lastSeen.style.color = 'var(--muted)';
    lastSeen.textContent = 'Last saved: ' + formatLibraryDate(latest && latest.savedAt);
    info.appendChild(lastSeen);

    const counts = document.createElement('div');
    counts.style.fontSize = '11.5px';
    counts.style.color = 'var(--muted)';
    const countParts = [
      saveCount + ' save' + (saveCount === 1 ? '' : 's'),
      totalLines + ' line' + (totalLines === 1 ? '' : 's'),
      totalImages + ' image' + (totalImages === 1 ? '' : 's'),
    ];
    if (totalConfirmedPoms) countParts.push(totalConfirmedPoms + ' confirmed POM' + (totalConfirmedPoms === 1 ? '' : 's'));
    counts.textContent = countParts.join('  ·  ');
    info.appendChild(counts);

    if (styleId && (evidenceCount > 0 || meaningCount > 0)) {
      const badges = document.createElement('div');
      badges.style.display = 'flex';
      badges.style.gap = '6px';
      badges.style.marginTop = '4px';
      badges.style.flexWrap = 'wrap';
      if (meaningCount > 0) badges.appendChild(buildBadge(meaningCount + ' meaning' + (meaningCount === 1 ? '' : 's'), '#dbeafe', '#1e40af'));
      if (evidenceCount > 0) badges.appendChild(buildBadge(evidenceCount + ' evidence', '#dcfce7', '#166534'));
      info.appendChild(badges);
    }
    row.appendChild(info);

    const actions = document.createElement('div');
    actions.style.display = 'flex';
    actions.style.flexDirection = 'column';
    actions.style.gap = '6px';
    actions.style.justifyContent = 'center';
    actions.style.flex = '0 0 auto';

    const openBtn = document.createElement('button');
    openBtn.type = 'button';
    openBtn.className = 'picker-btn primary';
    openBtn.textContent = 'Open latest';
    openBtn.style.fontSize = '12px';
    openBtn.style.padding = '5px 12px';
    openBtn.disabled = !latest;
    openBtn.addEventListener('click', () => {
      if (latest) handlers.onOpen(latest);
    });

    const viewSavesBtn = document.createElement('button');
    viewSavesBtn.type = 'button';
    viewSavesBtn.className = 'picker-btn';
    viewSavesBtn.textContent = saveCount > 1 ? 'View ' + saveCount + ' saves' : 'View saves';
    viewSavesBtn.style.fontSize = '12px';
    viewSavesBtn.style.padding = '5px 10px';
    viewSavesBtn.addEventListener('click', () => handlers.onViewSaves(styleId));

    actions.appendChild(openBtn);
    actions.appendChild(viewSavesBtn);
    row.appendChild(actions);

    return row;
  }

  // ---- src/ui/dialogs/library-dialog.js ----
// Project Library: browse, reopen, and delete saved project snapshots.
// Source part for app.js. Run `npm run build` after editing.
//
// Every writeProjectFile() appends an entry to the IndexedDB-backed library
// in src/project/project-library.js. This dialog has two tabs:
//   - "By Style" (default): one card per styleId, aggregated counts +
//     evidence/meaning badges, "Open latest" or drill into saves.
//   - "By Save": flat list, every snapshot is its own row.
// Opening a snapshot reuses the existing loadProject() flow, so a re-save
// creates a new entry (append history), matching the user's chosen
// "keep history" behavior.
//
// This is the stateful dialog controller only (tabs, filter, refresh, the
// async open/delete/download handlers). The cross-view grouping/formatting
// helpers live in library-shared.js; the "By Save" flat-list rendering lives
// in library-list-view.js; the "By Style" card-grid rendering lives in
// library-grid-view.js.

  function openLibraryDialog() {
    const dialog = buildDialog({
      title: 'Library',
      sub: 'Browse styles you have worked on. Every save is archived per style.',
    });
    // The default .dialog-panel is 560px wide; the library cards need more
    // room or their action buttons clip past the panel edge. ld-wide bumps
    // the shell to min(820px, 100%), and the body then just fills it.
    dialog.panel.classList.add('ld-wide');

    const body = document.createElement('div');
    body.className = 'dialog-body library-body';
    body.style.minWidth = '0';

    let viewMode = 'style';

    const tabs = document.createElement('div');
    tabs.className = 'library-tabs';
    tabs.style.display = 'flex';
    tabs.style.gap = '4px';
    tabs.style.marginBottom = '10px';
    tabs.style.borderBottom = '1px solid #e6e6ea';

    function makeTabBtn(label, onSelect) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.textContent = label;
      btn.style.padding = '6px 14px';
      btn.style.background = 'transparent';
      btn.style.border = '0';
      btn.style.borderBottom = '2px solid transparent';
      btn.style.fontSize = '13px';
      btn.style.fontWeight = '600';
      btn.style.color = 'var(--muted)';
      btn.style.cursor = 'pointer';
      btn.style.marginBottom = '-1px';
      btn.addEventListener('click', onSelect);
      return btn;
    }
    const styleTabBtn = makeTabBtn('By Style', () => setViewMode('style'));
    const saveTabBtn = makeTabBtn('By Save', () => setViewMode('save'));
    tabs.appendChild(styleTabBtn);
    tabs.appendChild(saveTabBtn);
    body.appendChild(tabs);

    function setViewMode(mode) {
      if (mode !== 'style' && mode !== 'save') return;
      viewMode = mode;
      const active = mode === 'style' ? styleTabBtn : saveTabBtn;
      const inactive = mode === 'style' ? saveTabBtn : styleTabBtn;
      active.style.color = 'var(--text)';
      active.style.borderBottomColor = '#2563eb';
      inactive.style.color = 'var(--muted)';
      inactive.style.borderBottomColor = 'transparent';
      applyFilter();
    }

    const controls = document.createElement('div');
    controls.className = 'library-controls';
    controls.style.display = 'flex';
    controls.style.gap = '10px';
    controls.style.alignItems = 'center';
    controls.style.marginBottom = '8px';

    const filterInput = document.createElement('input');
    filterInput.type = 'search';
    filterInput.placeholder = 'Filter by style code…';
    filterInput.autocomplete = 'off';
    filterInput.spellcheck = false;
    filterInput.style.flex = '1';
    filterInput.style.padding = '6px 10px';
    filterInput.style.border = '1px solid #d4d4d8';
    filterInput.style.borderRadius = '6px';
    filterInput.style.fontSize = '13px';

    const summary = document.createElement('span');
    summary.className = 'library-summary';
    summary.style.fontSize = '12px';
    summary.style.color = 'var(--muted)';
    summary.textContent = 'Loading…';

    controls.appendChild(filterInput);
    controls.appendChild(summary);
    body.appendChild(controls);

    const list = document.createElement('div');
    list.className = 'library-list';
    list.style.maxHeight = '60vh';
    list.style.overflowY = 'auto';
    list.style.border = '1px solid #ececf0';
    list.style.borderRadius = '8px';
    list.style.background = '#fafafa';
    body.appendChild(list);

    dialog.panel.appendChild(body);

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    const spacer = document.createElement('span');
    spacer.style.flex = '1';
    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'picker-btn primary';
    closeBtn.textContent = 'Close';
    closeBtn.addEventListener('click', dialog.close);
    footer.appendChild(spacer);
    footer.appendChild(closeBtn);
    dialog.panel.appendChild(footer);

    let entriesCache = [];

    function applyFilter() {
      const q = filterInput.value.trim().toLowerCase();
      const filtered = q
        ? entriesCache.filter(e => (e.styleId || '').toLowerCase().includes(q))
        : entriesCache;
      if (viewMode === 'style') {
        renderStyleGridView(list, filtered, {
          onOpen: handleOpen,
          onViewSaves: handleViewSaves,
        });
        const styleCount = countDistinctStyles(filtered);
        summary.textContent = entriesCache.length === 0
          ? 'No projects saved yet.'
          : styleCount + ' style' + (styleCount === 1 ? '' : 's')
            + '  ·  ' + filtered.length + ' save' + (filtered.length === 1 ? '' : 's');
      } else {
        renderLibraryList(list, filtered, {
          onOpen: handleOpen,
          onDelete: handleDelete,
          onDownload: handleDownload,
        });
        summary.textContent = entriesCache.length === 0
          ? 'No projects saved yet.'
          : (filtered.length === entriesCache.length
              ? entriesCache.length + ' entr' + (entriesCache.length === 1 ? 'y' : 'ies')
              : filtered.length + ' of ' + entriesCache.length + ' shown');
      }
    }

    function handleViewSaves(styleId) {
      filterInput.value = styleId || '';
      setViewMode('save');
    }

    async function refresh() {
      summary.textContent = 'Loading…';
      try {
        entriesCache = await listLibraryEntries();
      } catch (err) {
        console.warn(err);
        entriesCache = [];
        summary.textContent = 'Could not read the library.';
        list.innerHTML = '';
        const error = document.createElement('div');
        error.style.padding = '16px';
        error.style.color = '#b91c1c';
        error.style.fontSize = '13px';
        error.textContent = String(err && err.message || err) || 'Library unavailable.';
        list.appendChild(error);
        return;
      }
      applyFilter();
    }

    async function handleOpen(entry) {
      const drafts = state.autoMode ? state.autoMode.draftAnnotations : null;
      if (state.appMode === 'auto' && drafts && drafts.length > 0) {
        const approvedCount = drafts.filter(d => d.tdApproved && !isReviewOnlyDraft(d)).length;
        const choice = await openAutoModeExitDialog({
          approvedCount,
          totalCount: drafts.length,
          reason: 'Opening a library entry will replace the board and clear the Auto Mode draft layer. Choose what to do with the drafts first:',
        });
        if (choice === 'apply') {
          const applied = applyApprovedDraftsAtomically();
          if (!applied) return;
          if (state.autoMode.draftAnnotations.length > 0) {
            showToast('Some drafts remain. Resolve them before opening another project.');
            return;
          }
        } else if (choice === 'discard') {
          discardAutoDrafts(true);
        } else {
          return;
        }
      } else if (typeof hasUnsavedWork === 'function'
        ? hasUnsavedWork()
        : (state.annotations.length || state.images.length)) {
        // US-092: ask hasUnsavedWork() rather than re-deriving "is there work
        // here" from two collections. This gate had drifted behind the one in
        // onProjectFileChosen (project-load.js) and silently replaced a board
        // holding only notes — or only BOM/Construction work — with no prompt.
        const ok = window.confirm('Open this project? Your current board will be replaced. Save it first if you want to keep it.');
        if (!ok) return;
      }
      let full;
      try {
        full = await getLibraryEntry(entry.id);
      } catch (err) {
        console.warn(err);
        showToast('Could not read that entry.', 4200);
        return;
      }
      if (!full || !full.snapshot) {
        showToast('That entry has no snapshot to open.', 4200);
        return;
      }
      try {
        await loadProject(full.snapshot);
        showToast('Project opened from library.');
        dialog.close();
      } catch (err) {
        console.error(err);
        showToast('Could not open that entry — saved with an older format.', 4200);
      }
    }

    async function handleDelete(entry) {
      const label = entry.styleId ? 'style "' + entry.styleId + '"' : 'this entry';
      if (!window.confirm('Delete the library entry for ' + label + ' (saved ' + formatLibraryDate(entry.savedAt) + ')?\nThis cannot be undone.')) return;
      try {
        await deleteLibraryEntry(entry.id);
      } catch (err) {
        console.warn(err);
        showToast('Could not delete that entry.', 4200);
        return;
      }
      showToast('Entry removed from library.');
      await refresh();
    }

    async function handleDownload(entry) {
      let full;
      try {
        full = await getLibraryEntry(entry.id);
      } catch (err) {
        console.warn(err);
        showToast('Could not read that entry.', 4200);
        return;
      }
      if (!full || !full.snapshot) {
        showToast('That entry has no snapshot to download.', 4200);
        return;
      }
      const blob = new Blob([JSON.stringify(full.snapshot)], { type: 'application/json' });
      const baseName = (full.styleId || 'project').replace(/[^A-Za-z0-9._-]+/g, '-') || 'project';
      const stamp = (full.savedAt || '').replace(/[^0-9]/g, '').slice(0, 14) || 'snapshot';
      downloadBlob(blob, 'bra-sketch-' + baseName + '-' + stamp + '.json');
    }

    dialog.open();
    setViewMode('style');
    filterInput.addEventListener('input', applyFilter);
    refresh();
  }

  // ---- src/ui/dialogs/grading-rules-model.js ----
// Shared grade-rule domain model: base sizes, the house default step table,
// and the pure functions that turn a base value + rule into a graded run.
// Used by both size-run-dialog.js (read-only preview) and grading-dialog.js
// (per-size edit). Grade rules live in state.gradeRules (persisted +
// undoable); NOTHING here touches the rule JSON.
// Source part for app.js. Run `npm run build` after editing.

  const GRADE_SIZES = ['S', 'M', 'L', 'XL', '2XL', '3XL', '4XL', '5XL'];
  const GRADE_BASE_SIZE = 'L';

  // Crossian house grade rule expressed as ONE constant step per POM, in
  // INCHES, plus which POMs are held constant (straps are adjustable, so they
  // don't grade). A constant step is a deliberate approximation of the
  // standard's taper (e.g. the band actually steps ~0.5 -> 1.0); the TD can
  // edit any step in the dialog. See the bra-grading house standard.
  const HOUSE_GRADE_INCHES = {
    '1':  { step: 0.75,  hold: false }, // 1/2 bottom band - relax (bonded ~0.5->1.0)
    '2':  { step: 1.5,   hold: false }, // 1/2 bottom band - extend (~1.0->2.0)
    '3':  { step: 1.25,  hold: false }, // 1/2 chest - measure straight
    '4':  { step: 1.25,  hold: false }, // 1/2 chest - extend
    '5':  { step: 0.25,  hold: false }, // center front height
    '6':  { step: 0.125, hold: false }, // cradle height at center front
    '7':  { step: 0.25,  hold: false }, // cradle height at bottom cup
    '8':  { step: 0.375, hold: false }, // cup height at center front
    '9':  { step: 0.375, hold: false }, // inner cup height
    '10': { step: 0.5,   hold: false }, // inner cup width
    '11': { step: 0.25,  hold: false }, // side seam length
    '12': { step: 0.25,  hold: false }, // back center length
    '13': { step: 0.25,  hold: false }, // back panel height
    '14': { step: 0,     hold: true  }, // shoulder strap - held (adjustable)
    '15': { step: 0,     hold: true  }, // back strap distances - held
    '16': { step: 0.5,   hold: false }, // front apex distance
  };

  function inchesToUnit(unit) {
    if (unit === 'cm') return 2.54;
    if (unit === 'mm') return 25.4;
    if (unit === 'm') return 0.0254;
    return 1; // inches — the project default unit (and the 'in' case)
  }

  // Effective grade rule for a POM in the project's unit: a TD override in
  // state.gradeRules wins; otherwise the house default converted from inches.
  function getGradeRule(pomKey) {
    const key = String(pomKey);
    const house = HOUSE_GRADE_INCHES[key] || { step: 0, hold: false };
    const houseStepUnit = house.step * inchesToUnit(state.calibration.unit);
    const override = (state.gradeRules && state.gradeRules.steps && state.gradeRules.steps[key]) || null;
    if (!override) return { step: houseStepUnit, hold: !!house.hold, overridden: false };
    return {
      step: override.step != null ? Number(override.step) : houseStepUnit,
      hold: override.hold != null ? !!override.hold : !!house.hold,
      overridden: true,
    };
  }

  // Base value for a POM: explicit Size L wins; else the calibrated measured
  // length of its drawn line; else null (nothing to grade from).
  function gradeBaseValue(pomKey, annByPom) {
    const fromSize = parseSpecNumber(getPomSpec(pomKey).sizeL);
    if (fromSize != null) return { value: fromSize, source: 'Size L' };
    const cal = state.calibration;
    if (cal.unitsPerPx != null) {
      const ann = annByPom.get(String(pomKey));
      if (ann) {
        const px = lineLength(ann);
        if (px > 0) return { value: px * cal.unitsPerPx, source: 'measured' };
      }
    }
    return { value: null, source: null };
  }

  function gradedRunForPom(base, rule) {
    const baseIdx = GRADE_SIZES.indexOf(GRADE_BASE_SIZE);
    return GRADE_SIZES.map((_, i) => (rule.hold ? base : base + (i - baseIdx) * rule.step));
  }

  // ---- src/ui/dialogs/size-run-dialog.js ----
// Size-run grading dialog: grade the base spec into a full size run.
// Additive and offline — reads each POM's base value (its Size L, else the
// calibrated measured value), applies a per-POM per-size-step increment, and
// renders a POM x size grid the TD can copy. Grade rules live in
// state.gradeRules (persisted + undoable); NOTHING here touches the rule JSON.
// The grade-rule domain model (GRADE_SIZES, GRADE_BASE_SIZE,
// HOUSE_GRADE_INCHES, inchesToUnit, getGradeRule, gradeBaseValue,
// gradedRunForPom) lives in grading-rules-model.js, shared with
// grading-dialog.js.
// Source part for app.js. Run `npm run build` after editing.

  function pomDisplayName(pomKey) {
    const entry = POM_TEMPLATE && POM_TEMPLATE[String(pomKey)];
    return entry && entry.desc ? entry.desc : ('POM ' + pomKey);
  }

  function openSizeRunDialog() {
    const unit = state.calibration.unit;
    const annByPom = new Map();
    // US-096: the measurement set only. An unlabelled zigzag/cover/bartack
    // line is a construction mark and owns no POM row.
    for (const ann of measurementAnnotations()) annByPom.set(getLabelText(ann), ann);
    const pomKeys = Object.keys(POM_TEMPLATE).sort((a, b) => Number(a) - Number(b));

    const dialog = buildDialog({
      title: 'Generate size run',
      sub: 'Grade the base spec across ' + GRADE_SIZES[0] + '–' + GRADE_SIZES[GRADE_SIZES.length - 1]
        + ' (base ' + GRADE_BASE_SIZE + '). Unit: ' + unit + '.',
    });

    const body = document.createElement('div');
    body.className = 'size-run-body';
    body.style.cssText = 'max-width:100%;overflow:auto;';
    const lead = document.createElement('p');
    lead.style.cssText = 'margin:0 0 8px;font-size:12px;color:#555;';
    // US-011: this dialog is a read-only PREVIEW of the graded run. All
    // grade-rule editing lives in the Grading dialog (one source of truth) —
    // the review flagged that two editing surfaces over one persisted object
    // silently disagree (per-size overrides beat steps with no UI signal).
    lead.innerHTML = 'Base = each POM’s <b>Size L</b>, or its calibrated measured value if Size L is blank. '
      + 'Preview only — edit the rule via the <b>Grading</b> button. Held POMs (straps) stay flat and are shaded.';
    body.appendChild(lead);

    const scroller = document.createElement('div');
    scroller.style.cssText = 'overflow:auto;max-height:56vh;border:1px solid #e5e5e5;border-radius:8px;';
    const table = document.createElement('table');
    table.className = 'size-run-table';
    table.style.cssText = 'border-collapse:collapse;font-size:12px;white-space:nowrap;';
    scroller.appendChild(table);
    body.appendChild(scroller);
    dialog.panel.appendChild(body);

    function renderTable() {
      table.innerHTML = '';
      const thead = document.createElement('thead');
      const hr = document.createElement('tr');
      const headCells = ['POM', 'Step/size', 'Hold'].concat(GRADE_SIZES);
      headCells.forEach((h, idx) => {
        const th = document.createElement('th');
        th.textContent = h + (idx === 1 ? ' (' + unit + ')' : '');
        th.style.cssText = 'position:sticky;top:0;background:#fafafa;border-bottom:1px solid #e5e5e5;'
          + 'padding:5px 8px;text-align:' + (idx <= 2 ? 'left' : 'right') + ';font-weight:600;';
        if (GRADE_SIZES[idx - 3] === GRADE_BASE_SIZE) th.style.background = '#eef4ff';
        hr.appendChild(th);
      });
      thead.appendChild(hr);
      table.appendChild(thead);

      const tbody = document.createElement('tbody');
      for (const key of pomKeys) {
        const rule = getGradeRule(key);
        const baseInfo = gradeBaseValue(key, annByPom);
        const tr = document.createElement('tr');
        if (rule.hold) tr.style.background = '#fffbe6'; // held POMs shaded

        const nameTd = document.createElement('td');
        nameTd.style.cssText = 'padding:4px 8px;border-bottom:1px solid #f0f0f0;max-width:190px;overflow:hidden;text-overflow:ellipsis;';
        nameTd.textContent = key + '. ' + pomDisplayName(key);
        nameTd.title = pomDisplayName(key) + (baseInfo.source ? ' · base from ' + baseInfo.source : ' · no base set');
        tr.appendChild(nameTd);

        // Read-only step/hold display (US-011: editing moved to the Grading
        // dialog; legacy step overrides remain honored and visible here).
        const stepTd = document.createElement('td');
        stepTd.style.cssText = 'padding:4px 8px;border-bottom:1px solid #f0f0f0;color:#555;';
        stepTd.textContent = rule.hold ? '—' : String(+rule.step.toFixed(3));
        if (rule.overridden) {
          stepTd.style.fontWeight = '600';
          stepTd.title = 'TD step override (edit or clear it in the Grading dialog)';
        }
        tr.appendChild(stepTd);

        const holdTd = document.createElement('td');
        holdTd.style.cssText = 'padding:4px 8px;border-bottom:1px solid #f0f0f0;text-align:center;color:#555;';
        holdTd.textContent = rule.hold ? 'held' : '';
        holdTd.title = rule.hold ? 'Held constant across sizes (e.g. adjustable straps)' : '';
        tr.appendChild(holdTd);

        const run = baseInfo.value != null ? gradedRunForPom(baseInfo.value, rule) : null;
        GRADE_SIZES.forEach((sz, i) => {
          const td = document.createElement('td');
          td.style.cssText = 'padding:4px 8px;border-bottom:1px solid #f0f0f0;text-align:right;'
            + (sz === GRADE_BASE_SIZE ? 'background:#eef4ff;font-weight:600;' : '');
          td.textContent = run ? formatMeasure(run[i]) : '—';
          tr.appendChild(td);
        });
        tbody.appendChild(tr);
      }
      table.appendChild(tbody);
    }
    renderTable();

    function buildTsv() {
      const header = ['POM', 'Description'].concat(GRADE_SIZES.map(s => s + ' (' + unit + ')'));
      const lines = [header.join('\t')];
      for (const key of pomKeys) {
        const rule = getGradeRule(key);
        const baseInfo = gradeBaseValue(key, annByPom);
        const run = baseInfo.value != null ? gradedRunForPom(baseInfo.value, rule) : null;
        const cells = [key, pomDisplayName(key)].concat(
          GRADE_SIZES.map((_, i) => (run ? formatMeasure(run[i]) : ''))
        );
        lines.push(cells.join('\t'));
      }
      return lines.join('\n');
    }

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    // US-011: no reset here — this dialog is a preview; the Grading dialog
    // owns every grade-rule edit (per-POM and global resets included).
    const spacer = document.createElement('span');
    spacer.style.flex = '1';
    const copyBtn = document.createElement('button');
    copyBtn.type = 'button';
    copyBtn.className = 'picker-btn';
    copyBtn.textContent = 'Copy table';
    copyBtn.addEventListener('click', () => {
      const tsv = buildTsv();
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(tsv).then(
          () => showToast('Size run copied — paste into a spec sheet.'),
          () => showToast('Copy failed — select and copy manually.')
        );
      } else {
        showToast('Clipboard unavailable in this browser.');
      }
    });
    const doneBtn = document.createElement('button');
    doneBtn.type = 'button';
    doneBtn.className = 'picker-btn primary';
    doneBtn.textContent = 'Done';
    doneBtn.addEventListener('click', dialog.close);
    footer.appendChild(spacer);
    footer.appendChild(copyBtn);
    footer.appendChild(doneBtn);
    dialog.panel.appendChild(footer);

    dialog.open();
  }

  // ---- src/ui/dialogs/export-size-dialog.js ----
// Export size picker (US-011 S2). Opens from Export Excel: checkboxes for
// every SPEC_SIZE_RUN column (grouped alpha / depth) with one-click presets.
// The choice persists in state.sizeSelection (null = all sizes) so the next
// export starts from the same subset. Source part for app.js — run
// `npm run build` after editing. Loads before export-xlsx.js; SPEC_SIZE_RUN
// is referenced at call time only (shared IIFE scope).

  // The size columns Export Excel emits, honouring state.sizeSelection.
  // null / malformed selection → the full run (back-compat default).
  function selectedSizeRun() {
    const sel = state.sizeSelection;
    if (!sel || typeof sel !== 'object') return SPEC_SIZE_RUN.slice();
    const alpha = Array.isArray(sel.alpha) ? sel.alpha : [];
    const depth = Array.isArray(sel.depth) ? sel.depth : [];
    return SPEC_SIZE_RUN.filter(c => (c.tier === 1 ? alpha : depth).includes(c.label));
  }

  function openExportSizeDialog(onConfirm) {
    const dlg = buildDialog({
      title: 'Export sizes',
      sub: 'Choose which size columns the Excel spec includes.',
    });

    const body = document.createElement('div');
    body.className = 'dialog-body';
    body.style.cssText = 'display:flex;flex-direction:column;gap:12px;min-width:420px;';

    const current = new Set(selectedSizeRun().map(c => c.label));
    const boxByLabel = new Map();

    const groupWrap = document.createElement('div');
    groupWrap.style.cssText = 'display:flex;flex-direction:column;gap:10px;';
    const makeGroup = (title, tier) => {
      const wrap = document.createElement('div');
      const h = document.createElement('div');
      h.textContent = title;
      h.style.cssText = 'font-weight:600;font-size:12px;margin-bottom:6px;';
      wrap.appendChild(h);
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;flex-wrap:wrap;gap:6px 14px;';
      for (const col of SPEC_SIZE_RUN.filter(c => c.tier === tier)) {
        const label = document.createElement('label');
        label.style.cssText = 'display:inline-flex;align-items:center;gap:5px;font-size:12px;cursor:pointer;';
        const box = document.createElement('input');
        box.type = 'checkbox';
        box.checked = current.has(col.label);
        box.addEventListener('change', updateFooter);
        boxByLabel.set(col.label, box);
        label.appendChild(box);
        label.appendChild(document.createTextNode(col.label));
        row.appendChild(label);
      }
      wrap.appendChild(row);
      return wrap;
    };
    groupWrap.appendChild(makeGroup('Alpha sizes (graded from Size L)', 1));
    groupWrap.appendChild(makeGroup('Depth sizes (graded from Size L2)', 2));
    body.appendChild(groupWrap);

    // Presets: one click to the common export shapes.
    const presets = document.createElement('div');
    presets.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap;';
    const applyPreset = (predicate) => {
      for (const col of SPEC_SIZE_RUN) boxByLabel.get(col.label).checked = predicate(col);
      updateFooter();
    };
    const presetDefs = [
      ['All sizes', () => true],
      ['Size L only', (c) => c.label === 'L'],
      ['Alpha only', (c) => c.tier === 1],
      ['Depth only', (c) => c.tier === 2],
    ];
    for (const [name, predicate] of presetDefs) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'picker-btn';
      btn.textContent = name;
      btn.addEventListener('click', () => applyPreset(predicate));
      presets.appendChild(btn);
    }
    body.appendChild(presets);

    const hint = document.createElement('div');
    hint.style.cssText = 'font-size:11px;color:#666;';
    hint.textContent = 'Formulas stay live for sizes whose base column (L or L2) is included; '
      + 'otherwise values are exported as plain numbers.';
    body.appendChild(hint);

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    footer.style.cssText = 'display:flex;gap:8px;align-items:center;';
    const count = document.createElement('span');
    count.style.cssText = 'font-size:12px;color:#444;flex:1;';
    const cancelBtn = document.createElement('button');
    cancelBtn.type = 'button';
    cancelBtn.className = 'picker-btn';
    cancelBtn.textContent = 'Cancel';
    cancelBtn.addEventListener('click', () => dlg.close());
    const okBtn = document.createElement('button');
    okBtn.type = 'button';
    okBtn.className = 'picker-btn picker-btn-primary';
    okBtn.textContent = 'Export';
    okBtn.addEventListener('click', () => {
      const chosen = SPEC_SIZE_RUN.filter(c => boxByLabel.get(c.label).checked);
      if (!chosen.length) return;
      // null when everything is selected — the back-compat "no preference"
      // shape old builds also understand (they ignore the field entirely).
      state.sizeSelection = chosen.length === SPEC_SIZE_RUN.length
        ? null
        : {
          alpha: chosen.filter(c => c.tier === 1).map(c => c.label),
          depth: chosen.filter(c => c.tier === 2).map(c => c.label),
        };
      if (typeof scheduleAutosave === 'function') scheduleAutosave();
      dlg.close();
      onConfirm();
    });
    footer.appendChild(count);
    footer.appendChild(cancelBtn);
    footer.appendChild(okBtn);

    function updateFooter() {
      const n = SPEC_SIZE_RUN.filter(c => boxByLabel.get(c.label).checked).length;
      count.textContent = n + ' of ' + SPEC_SIZE_RUN.length + ' sizes selected';
      okBtn.disabled = n === 0;
    }
    updateFooter();

    dlg.panel.appendChild(body);
    dlg.panel.appendChild(footer);
    dlg.open();
  }

  // ---- src/ui/dialogs/grading-dialog.js ----
// Grading dialog (US-011 S3): view and edit the grade rule inside the tool.
// One row per POM (the 18 + any custom POMs), one column per size. Cells show
// the EFFECTIVE per-size delta — per-size TD override, else constant-step
// override (Size Run dialog), else the built-in SPEC_* tables — and edits
// write per-size overrides into gradeRules v2 (stored in inches). The L
// column is the alpha base (always 0); the L2 column edits the L2−L offset
// (gradeRules.depthOffsets, project unit). Source part for app.js — run
// `npm run build` after editing. SPEC_* tables live in export-xlsx.js and
// are referenced at call time only (shared IIFE scope).

  // Fraction parsing/formatting for grade deltas. fractionToNumber
  // (spec-panel.js) rejects negatives; deltas are frequently negative, so the
  // dialog has its own signed parser and a formatter that renders clean
  // fractions ("-1 1/4") and falls back to decimals for oddballs.
  function gradeDeltaToNumber(text) {
    const raw = String(text == null ? '' : text).trim();
    if (!raw) return null;
    const neg = raw.startsWith('-');
    const body = raw.replace(/^[+-]/, '').trim();
    // STRICT shapes only — fractionToNumber's parseFloat fallback would
    // silently truncate typos ("3 /4" → 3, a 4× grade error). Accept exactly:
    // decimal, fraction a/b, or mixed "w a/b" (single space).
    let n = null;
    let m;
    if ((m = body.match(/^(\d+)\s+(\d+)\/(\d+)$/))) {
      const den = parseInt(m[3], 10);
      if (den > 0) n = parseInt(m[1], 10) + parseInt(m[2], 10) / den;
    } else if ((m = body.match(/^(\d+)\/(\d+)$/))) {
      const den = parseInt(m[2], 10);
      if (den > 0) n = parseInt(m[1], 10) / den;
    } else if (/^\d*\.?\d+$/.test(body)) {
      n = parseFloat(body);
    }
    if (n == null || !isFinite(n)) return null;
    return neg ? -n : n;
  }

  function numberToGradeFraction(value) {
    if (value == null || !isFinite(value)) return '';
    const sign = value < 0 ? '-' : '';
    let v = Math.abs(Math.round(value * 10000) / 10000);
    const whole = Math.floor(v);
    const frac = v - whole;
    if (frac < 1e-9) return sign + String(whole);
    // Try the sewing-friendly denominators; fall back to a plain decimal.
    for (const den of [2, 4, 8, 16]) {
      const num = Math.round(frac * den);
      if (num > 0 && Math.abs(frac - num / den) < 1e-9) {
        const fracText = num + '/' + den;
        return sign + (whole ? whole + ' ' + fracText : fracText);
      }
    }
    return sign + String(v);
  }

  // Effective delta for a cell, in the PROJECT UNIT (what the sheet shows).
  // tier 1: delta vs Size L. tier 2 (except L2): delta vs L2.
  function effectiveGradeDeltaUnit(pomKey, col) {
    const key = String(pomKey);
    const unitScale = inchesToUnit(state.calibration.unit);
    const perSize = getPerSizeGradeDelta(col.tier, key, col.label);
    if (perSize != null) return perSize * unitScale;
    const rule = getGradeRule(key);
    if (rule.hold) return 0;
    const baseIdx = GRADE_SIZES.indexOf(GRADE_BASE_SIZE);
    if (col.tier === 1) {
      const alphaDeltas = SPEC_ALPHA_DELTA_L_IN[key] || null;
      const i = GRADE_SIZES.indexOf(col.label);
      if (rule.overridden || !alphaDeltas) return (i - baseIdx) * rule.step;
      return alphaDeltas[i] * unitScale;
    }
    const depthDeltas = SPEC_DEPTH_DELTA_L2_IN[key] || null;
    const depthLabels = SPEC_SIZE_RUN.filter(c => c.tier === 2).map(c => c.label);
    if (rule.overridden || !depthDeltas) {
      return (GRADE_SIZES.indexOf(col.base) - baseIdx) * rule.step;
    }
    return depthDeltas[depthLabels.indexOf(col.label)] * unitScale;
  }

  // Built-in (house default) delta for a cell, in the project unit — the
  // value "Reset to standard" restores and the reference for deciding
  // whether an edit is an override at all.
  function builtinGradeDeltaUnit(pomKey, col) {
    const key = String(pomKey);
    const unitScale = inchesToUnit(state.calibration.unit);
    const house = HOUSE_GRADE_INCHES[key] || { step: 0, hold: false };
    if (house.hold) return 0;
    if (col.tier === 1) {
      const alphaDeltas = SPEC_ALPHA_DELTA_L_IN[key] || null;
      const i = GRADE_SIZES.indexOf(col.label);
      const baseIdx = GRADE_SIZES.indexOf(GRADE_BASE_SIZE);
      if (!alphaDeltas) return (i - baseIdx) * house.step * unitScale;
      return alphaDeltas[i] * unitScale;
    }
    const depthDeltas = SPEC_DEPTH_DELTA_L2_IN[key] || null;
    const depthLabels = SPEC_SIZE_RUN.filter(c => c.tier === 2).map(c => c.label);
    const baseIdx = GRADE_SIZES.indexOf(GRADE_BASE_SIZE);
    if (!depthDeltas) return (GRADE_SIZES.indexOf(col.base) - baseIdx) * house.step * unitScale;
    return depthDeltas[depthLabels.indexOf(col.label)] * unitScale;
  }

  function ensureGradeRulesV2() {
    if (!state.gradeRules || state.gradeRules.version !== 2) {
      state.gradeRules = migrateGradeRulesV2(state.gradeRules, null);
    }
    return state.gradeRules;
  }

  function gradingPomKeys() {
    const template = Object.keys(POM_TEMPLATE).sort((a, b) => Number(a) - Number(b));
    const custom = (state.customPoms || []).map(p => String(p.pom))
      .sort((a, b) => Number(a) - Number(b));
    return template.concat(custom);
  }

  function openGradingDialog() {
    const dlg = buildDialog({
      title: 'Grading rules',
      sub: 'Per-size deltas: alpha sizes vs Size L, depth sizes vs L2. The L2 column is the L2−L offset. Edits are saved with the project.',
    });

    const body = document.createElement('div');
    body.className = 'dialog-body';
    body.style.cssText = 'max-height:60vh;overflow:auto;min-width:720px;';

    const unit = state.calibration.unit || 'in';
    const table = document.createElement('table');
    table.style.cssText = 'border-collapse:collapse;font-size:11px;width:100%;';

    const renderTable = () => {
      const rules = ensureGradeRulesV2();
      const rows = ['<tr><th style="position:sticky;top:0;background:#f2f2f2;padding:4px 6px;text-align:left;">POM</th>'
        + SPEC_SIZE_RUN.map(c => '<th style="position:sticky;top:0;background:'
          + (c.tier === 1 ? '#fcd5b4' : '#c4d79b') + ';padding:4px 6px;">' + escapeHtml(c.label) + '</th>').join('')
        + '<th style="position:sticky;top:0;background:#f2f2f2;"></th></tr>'];
      for (const key of gradingPomKeys()) {
        const custom = (state.customPoms || []).find(p => String(p.pom) === key);
        const name = custom ? (custom.en || 'Custom POM')
          : ((POM_TEMPLATE[key] && POM_TEMPLATE[key].name) || '');
        const cells = SPEC_SIZE_RUN.map(col => {
          if (col.tier === 1 && col.label === GRADE_BASE_SIZE) {
            return '<td style="border:1px solid #ddd;padding:2px;text-align:center;color:#999;">base</td>';
          }
          if (col.label === 'L2') {
            const off = getDepthRule(key);
            const overridden = off.overridden;
            return '<td style="border:1px solid #ddd;padding:0;">'
              + '<input data-pom="' + escapeHtml(key) + '" data-size="L2" data-kind="offset" value="'
              + escapeHtml(numberToGradeFraction(off.offset)) + '" title="L2 − L offset'
              + (overridden ? ' (TD override)' : ' (standard)') + '"'
              + ' style="width:52px;border:0;padding:3px 4px;text-align:center;'
              + (overridden ? 'background:#fff3d6;font-weight:600;' : '') + '"/></td>';
          }
          const eff = effectiveGradeDeltaUnit(key, col);
          const overridden = getPerSizeGradeDelta(col.tier, key, col.label) != null;
          const provenance = (key === '7' && col.label === '4XL2' && !overridden)
            ? ' — interpolated standard value, TD to confirm' : '';
          return '<td style="border:1px solid #ddd;padding:0;">'
            + '<input data-pom="' + escapeHtml(key) + '" data-size="' + escapeHtml(col.label)
            + '" data-kind="' + (col.tier === 1 ? 'alpha' : 'depth') + '" value="'
            + escapeHtml(numberToGradeFraction(eff)) + '" title="'
            + (overridden ? 'TD override' : 'standard') + provenance + '"'
            + ' style="width:52px;border:0;padding:3px 4px;text-align:center;'
            + (overridden ? 'background:#fff3d6;font-weight:600;' : '') + '"/></td>';
        }).join('');
        rows.push('<tr><td style="border:1px solid #ddd;padding:3px 6px;white-space:nowrap;" title="'
          + escapeHtml(name) + '">' + escapeHtml(key) + '</td>' + cells
          + '<td style="border:1px solid #ddd;padding:0;"><button type="button" class="picker-btn" data-reset="'
          + escapeHtml(key) + '" style="font-size:10px;padding:2px 6px;" title="Restore this POM to the standard rule">Reset</button></td></tr>');
        void rules;
      }
      table.innerHTML = rows.join('');
    };

    const commitCell = (input) => {
      const key = String(input.dataset.pom);
      const size = input.dataset.size;
      const kind = input.dataset.kind;
      const rules = ensureGradeRulesV2();
      const unitScale = inchesToUnit(state.calibration.unit);
      const trimmed = String(input.value).trim();
      // Empty = "back to standard" for this cell (delete the override).
      // Pinning a size flat is an explicit act: type 0.
      if (trimmed === '') {
        if (kind === 'offset') delete rules.depthOffsets[key];
        else {
          const bucket = kind === 'alpha' ? rules.alpha : rules.depth;
          if (bucket[key]) { delete bucket[key][size]; if (!Object.keys(bucket[key]).length) delete bucket[key]; }
        }
        pushHistoryIfChanged();
        renderTable();
        if (typeof renderSpecPanel === 'function') renderSpecPanel();
        return;
      }
      const parsed = gradeDeltaToNumber(trimmed);
      if (parsed == null) {
        showToast('Could not read "' + input.value + '" — use a number or fraction like -1 1/4.', 3600);
        renderTable();
        return;
      }
      const valueUnit = parsed;
      if (kind === 'offset') {
        const house = (SPEC_DEPTH_OFFSET_IN[key] || 0) * unitScale;
        if (Math.abs(valueUnit - house) < 1e-9) delete rules.depthOffsets[key];
        else rules.depthOffsets[key] = { offset: valueUnit };
      } else {
        const bucket = kind === 'alpha' ? rules.alpha : rules.depth;
        const builtin = builtinGradeDeltaUnit(key, SPEC_SIZE_RUN.find(c => c.label === size));
        if (Math.abs(valueUnit - builtin) < 1e-9) {
          if (bucket[key]) { delete bucket[key][size]; if (!Object.keys(bucket[key]).length) delete bucket[key]; }
        } else {
          if (!bucket[key]) bucket[key] = {};
          bucket[key][size] = valueUnit / unitScale;   // stored in inches
        }
      }
      pushHistoryIfChanged();
      renderTable();
      if (typeof renderSpecPanel === 'function') renderSpecPanel();
    };

    table.addEventListener('change', (ev) => {
      const input = ev.target.closest('input[data-pom]');
      if (input) commitCell(input);
    });
    table.addEventListener('click', (ev) => {
      const btn = ev.target.closest('button[data-reset]');
      if (!btn) return;
      const key = String(btn.dataset.reset);
      const rules = ensureGradeRulesV2();
      delete rules.alpha[key];
      delete rules.depth[key];
      delete rules.depthOffsets[key];
      delete rules.steps[key];
      pushHistoryIfChanged();
      renderTable();
      showToast('POM ' + key + ' grading reset to the standard rule.');
    });

    body.appendChild(table);

    const footer = document.createElement('div');
    footer.className = 'picker-footer';
    footer.style.cssText = 'display:flex;gap:8px;align-items:center;';
    const note = document.createElement('span');
    note.style.cssText = 'font-size:11px;color:#666;flex:1;';
    note.textContent = 'Values in ' + unit + '. Highlighted cells are TD overrides; they drive the Excel export formulas.';
    const resetAllBtn = document.createElement('button');
    resetAllBtn.type = 'button';
    resetAllBtn.className = 'picker-btn';
    resetAllBtn.textContent = 'Reset all to standard';
    resetAllBtn.addEventListener('click', () => {
      if (!window.confirm('Discard every grading override and restore the standard rule?')) return;
      state.gradeRules = makeEmptyGradeRulesV2();
      pushHistoryIfChanged();
      renderTable();
      showToast('All grading rules reset to standard.');
    });
    const doneBtn = document.createElement('button');
    doneBtn.type = 'button';
    doneBtn.className = 'picker-btn picker-btn-primary';
    doneBtn.textContent = 'Done';
    doneBtn.addEventListener('click', () => dlg.close());
    footer.appendChild(note);
    footer.appendChild(resetAllBtn);
    footer.appendChild(doneBtn);

    renderTable();
    dlg.panel.appendChild(body);
    dlg.panel.appendChild(footer);
    dlg.open();
  }

  // ---- src/ui/dialogs/view-roles-dialog.js ----
// View-role confirmation dialog: replaces the old window.prompt letter-code
// flow (F/B/I/U) after Detect Sketch when the classifier is unsure.
// Source part for app.js. Run `npm run build` after editing.
//
// openViewRolesDialog({ views, sourceImage }) resolves with an array of role
// strings (one per view, in the same order) when the TD confirms, or null
// when they dismiss (Esc / click-outside / "Keep as detected") — null means
// "leave the detection untouched", matching the old cancelled-prompt path.

  const VIEW_ROLE_CHOICES = [
    { role: 'front_outer', label: 'Front Outer' },
    { role: 'back', label: 'Back' },
    { role: 'front_inner', label: 'Front Inner' },
    { role: 'unknown', label: 'Unknown' },
  ];

  function viewRoleDisplayName(role) {
    const hit = VIEW_ROLE_CHOICES.find(c => c.role === role
      || (role === 'front' && c.role === 'front_outer'));
    return hit ? hit.label : 'Unknown';
  }

  // Crop one detected view box out of the source sketch into a small canvas
  // thumbnail. Returns null when anything is missing (e.g. Node tests) so the
  // dialog degrades to text-only rows.
  function buildViewThumbnail(sourceImage, view, size) {
    try {
      const img = sourceImage && sourceImage.img;
      if (!img || typeof document === 'undefined') return null;
      const iw = img.naturalWidth || img.width;
      const ih = img.naturalHeight || img.height;
      if (!iw || !ih) return null;
      const sx = Math.max(0, Math.floor((view.x || 0) * iw));
      const sy = Math.max(0, Math.floor((view.y || 0) * ih));
      const sw = Math.max(1, Math.floor((view.width || 0) * iw));
      const sh = Math.max(1, Math.floor((view.height || 0) * ih));
      const canvas = document.createElement('canvas');
      canvas.width = size;
      canvas.height = size;
      const ctx = canvas.getContext('2d');
      if (!ctx) return null;
      ctx.fillStyle = '#f5f5f7';
      ctx.fillRect(0, 0, size, size);
      const scale = Math.min(size / sw, size / sh);
      const dw = Math.max(1, Math.round(sw * scale));
      const dh = Math.max(1, Math.round(sh * scale));
      ctx.drawImage(img, sx, sy, sw, sh,
        Math.round((size - dw) / 2), Math.round((size - dh) / 2), dw, dh);
      return canvas;
    } catch (err) {
      return null;
    }
  }

  function openViewRolesDialog({ views, sourceImage }) {
    return new Promise((resolve) => {
      const dialog = buildDialog({
        title: 'Confirm view roles',
        sub: 'Tell Auto Mode which detected view is which before it places anchors.',
      });

      let settled = false;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        dialog.close();
        resolve(value);
      };
      // buildDialog's own close paths (Esc, ×, click-outside) bypass finish(),
      // so watch the overlay leaving the DOM and treat it as "keep detected".
      const observer = new MutationObserver(() => {
        if (!document.body.contains(dialog.overlay)) {
          observer.disconnect();
          if (!settled) { settled = true; resolve(null); }
        }
      });

      const body = document.createElement('div');
      body.className = 'dialog-body';

      const intro = document.createElement('p');
      intro.style.margin = '0 0 12px';
      intro.style.fontSize = '12.5px';
      intro.style.color = 'var(--muted)';
      intro.textContent = 'Detection was not sure about these views. Wrong roles put POM lines on the wrong sketch — fix any that look off.';
      body.appendChild(intro);

      const chosen = views.map(v => {
        const role = v.viewRole || v.role || 'unknown';
        return role === 'front' ? 'front_outer' : role;
      });

      views.forEach((view, index) => {
        const row = document.createElement('div');
        row.style.display = 'flex';
        row.style.gap = '12px';
        row.style.alignItems = 'center';
        row.style.padding = '10px 0';
        if (index > 0) row.style.borderTop = '1px solid #ececf0';

        const thumb = buildViewThumbnail(sourceImage, view, 72);
        if (thumb) {
          thumb.style.flex = '0 0 72px';
          thumb.style.borderRadius = '8px';
          thumb.style.border = '1px solid #e0e0e6';
          row.appendChild(thumb);
        }

        const info = document.createElement('div');
        info.style.flex = '0 0 auto';
        info.style.minWidth = '86px';
        const name = document.createElement('div');
        name.style.fontSize = '13px';
        name.style.fontWeight = '600';
        name.textContent = 'View ' + (index + 1);
        info.appendChild(name);
        const detected = document.createElement('div');
        detected.style.fontSize = '11.5px';
        detected.style.color = 'var(--muted)';
        const confidence = view.roleConfidence != null
          ? ' · ' + Math.round(view.roleConfidence * 100) + '%'
          : '';
        detected.textContent = 'Detected: ' + viewRoleDisplayName(chosen[index]) + confidence;
        info.appendChild(detected);
        row.appendChild(info);

        const group = document.createElement('div');
        group.setAttribute('role', 'radiogroup');
        group.setAttribute('aria-label', 'Role for view ' + (index + 1));
        group.style.display = 'flex';
        group.style.gap = '4px';
        group.style.flexWrap = 'wrap';
        group.style.marginLeft = 'auto';

        const buttons = VIEW_ROLE_CHOICES.map(choice => {
          const btn = document.createElement('button');
          btn.type = 'button';
          btn.textContent = choice.label;
          btn.setAttribute('role', 'radio');
          btn.style.padding = '5px 10px';
          btn.style.fontSize = '12px';
          btn.style.borderRadius = '999px';
          btn.style.border = '1px solid #d4d4d8';
          btn.style.cursor = 'pointer';
          btn.addEventListener('click', () => {
            chosen[index] = choice.role;
            paint();
          });
          group.appendChild(btn);
          return { btn, role: choice.role };
        });

        function paint() {
          buttons.forEach(({ btn, role }) => {
            const on = chosen[index] === role;
            btn.style.background = on ? '#1f2937' : '#fff';
            btn.style.color = on ? '#fff' : 'var(--text)';
            btn.style.borderColor = on ? '#1f2937' : '#d4d4d8';
            btn.setAttribute('aria-checked', on ? 'true' : 'false');
          });
        }
        paint();

        row.appendChild(group);
        body.appendChild(row);
      });

      dialog.panel.appendChild(body);

      const footer = document.createElement('div');
      footer.className = 'picker-footer';
      const spacer = document.createElement('span');
      spacer.style.flex = '1';
      const keepBtn = document.createElement('button');
      keepBtn.type = 'button';
      keepBtn.className = 'picker-btn';
      keepBtn.textContent = 'Keep as detected';
      keepBtn.addEventListener('click', () => finish(null));
      const confirmBtn = document.createElement('button');
      confirmBtn.type = 'button';
      confirmBtn.className = 'picker-btn primary';
      confirmBtn.textContent = 'Confirm roles';
      confirmBtn.addEventListener('click', () => finish(chosen.slice()));
      footer.appendChild(spacer);
      footer.appendChild(keepBtn);
      footer.appendChild(confirmBtn);
      dialog.panel.appendChild(footer);

      dialog.open();
      observer.observe(document.body, { childList: true });
      confirmBtn.focus();
    });
  }

  // ---- src/auto/measure/fusion.js ----
// Mode B measurement: library × sketch fusion (ADR 0033), ported to production
// from the validated lab engine (test/engine.js) via US-039 Stage 1.
//
// Pure + side-effect-free: this part only DEFINES functions and one flag const.
// It is FLAGGED OFF by default — getPomSpec only consults it when Mode B is on
// (compile-time MODE_B_DEFAULT or the ?modeB=1 URL pin) — so with the flag off
// production behaviour is bit-identical to Tier-0 (docs/decisions/0009).
//
// The value for each sketch-reliable POM is a precision-weighted SHRINKAGE of
// the sketch measurement (detected anchor pixel distance × a view-local scale)
// toward the library median — never a blind average, and never assigned: it is a
// suggestion the TD accepts or overrides (ADR 0009), and a conflicted POM falls
// back to the library value rather than showing a wrong number.

// Off by default. Turn on for a build by flipping this, or per-session with
// ?modeB=1 (mirrors the ?freeCv=1 / ?label=1 harness pins).
const MODE_B_DEFAULT = false;

function modeBEnabled() {
  if (MODE_B_DEFAULT) return true;
  try {
    if (typeof window !== 'undefined' && window.location) {
      return new URLSearchParams(window.location.search || '').get('modeB') === '1';
    }
  } catch (_e) { /* non-browser / restricted context */ }
  return false;
}

// Per-POM roll-out set (US-041). Empty by default — with the global flag off and
// this list empty, Mode B is fully inert. A POM id is added here ONLY after
// `npm run measurement-accuracy --promote` shows its fused value beats
// library-only on TD-confirmed ground truth; editing this list is the reviewed
// promotion step (mirrors golden/accuracy --update). Governance, not learning:
// it never mutates the versioned contract JSON.
const MODE_B_ENABLED_POMS = [];

// Mode B is live for a POM when the global flag is on OR the POM is promoted.
function modeBEnabledForPom(pom) {
  if (modeBEnabled()) return true;
  return MODE_B_ENABLED_POMS.indexOf(String(pom == null ? '' : pom).trim()) !== -1;
}
// True when ANY Mode B path is live (global flag or a promoted POM) — used to
// skip the whole measured-suggestion computation when nothing is enabled.
function modeBAnyEnabled() {
  return modeBEnabled() || MODE_B_ENABLED_POMS.length > 0;
}

// POM -> [startAnchor, endAnchor], from auto_mode_rules/pom-template.json
// requiredAnchors. Only the corpus sketchReliable POMs (5-13) are fusable; POM
// 1-4 are schematic, 14 is front-to-back (unmeasurable from 2D views, ADR 0026),
// 15/16/17/18 have no corpus median.
const MODE_B_POM_ANCHORS = {
  '5': ['cf-top', 'cf-bottom'],
  '6': ['cradle-cf-top', 'cf-bottom'],
  '7': ['cradle-cup-top', 'cradle-cup-bottom'],
  '8': ['cf-top', 'cradle-cf-top'],
  '9': ['inner-cup-top', 'inner-cup-bottom'],
  '10': ['inner-cup-left', 'inner-cup-right'],
  '11': ['side-top', 'side-bottom'],
  '12': ['back-top', 'back-bottom'],
  '13': ['back-top', 'back-bottom'],
};
const MODE_B_POM_VIEW = {
  '5': 'front_outer', '6': 'front_outer', '7': 'front_outer', '8': 'front_outer',
  '9': 'front_outer', '10': 'front_outer', '11': 'back', '12': 'back', '13': 'back',
};

function mbClamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function mbRound(v, p) { const m = Math.pow(10, p == null ? 3 : p); return Math.round(v * m) / m; }
function mbMedian(xs) {
  const s = xs.slice().sort((a, b) => a - b);
  if (!s.length) return 0;
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

// Coherent, view-wide style offset (kept, not shrunk): robust median of
// (sketch/median - 1). MAD is the in-distribution / scale-trust signal.
function mbStyleOffset(pairs) {
  const ratios = (pairs || []).filter(p => p && p.median > 0 && p.sketch > 0).map(p => p.sketch / p.median - 1);
  if (ratios.length < 2) return { offset: 0, dispersion: null, n: ratios.length };
  const offset = mbMedian(ratios);
  const dispersion = mbMedian(ratios.map(r => Math.abs(r - offset)));
  return { offset: mbRound(mbClamp(offset, -0.25, 0.25), 4), dispersion: mbRound(dispersion, 4), n: ratios.length };
}

// Precision-weighted shrinkage toward the style-adjusted median.
//   styleExpected = median · (1 + styleOffset)
//   fused         = styleExpected + k · (sketch − styleExpected),  k = σL²/(σL²+σs²)
function mbFuseValue(args) {
  const sketch = Number(args.sketch), median = Number(args.median);
  const styleOffset = Number(args.styleOffset) || 0;
  const sL = Math.max(1e-6, Number(args.priorSpreadFrac) || 0.08);
  const sS = Math.max(1e-6, Number(args.sketchSigmaFrac) || 0.08);
  const k = (sL * sL) / (sL * sL + sS * sS);
  const styleExpected = median * (1 + styleOffset);
  const fused = styleExpected + k * (sketch - styleExpected);
  const residual = median > 0 ? (sketch / median - 1 - styleOffset) : 0;
  return { fused: mbRound(fused, 3), k: mbRound(k, 3), residual: mbRound(residual, 4) };
}

function mbDiagnose(residual, dispersion) {
  const r = Math.abs(Number(residual) || 0);
  const d = Number(dispersion);
  if (Number.isFinite(d) && d > 0.12) return 'scale_suspect';
  if (r > 0.15) return 'anchor_outlier';
  return 'coherent';
}

// Sketch noise fraction: lower (more trust) for ink-confirmed anchors and
// independent (TD/construction) scale; higher for short POMs and inferred scale.
function mbSketchSigmaFrac(scaleIndependent, anchorConfirmed, shortPom) {
  return (scaleIndependent ? 0.03 : 0.08) * (anchorConfirmed ? 1.0 : 1.8) * (shortPom ? 1.5 : 1.0);
}

// Build { pom: { value_in, sketch_in, library_in, k, residual, diagnosis,
// confidence, decision, scaleSource } } from detected anchors + library medians.
// anchors: array of { kind, x, y (normalized 0..1), viewRole, confidence, source, reviewRequired }
// suggestions: POM_SUGGESTIONS ({ median, sketchReliable } per POM id)
// dims: { width, height } source-image px (aspect matters for pixel-length ratios)
function mbComputeMeasuredSuggestions(anchors, suggestions, dims) {
  const out = {};
  if (!Array.isArray(anchors) || !anchors.length || !suggestions) return out;
  const W = Number(dims && dims.width) || 1;
  const H = Number(dims && dims.height) || 1;
  const byKind = {};
  for (const a of anchors) if (a && a.kind) byKind[a.kind] = a;

  const rank = { high: 3, medium: 2, low: 1, very_low: 0 };
  const inkSourced = s => /ink|silhouette|opencv/i.test(String(s || ''));

  // Per-POM sketch geometry (source-px pixel distance) + library median.
  const rows = {};
  for (const pom of Object.keys(MODE_B_POM_ANCHORS)) {
    const sug = suggestions[pom];
    if (!sug || !(Number(sug.median) > 0) || sug.sketchReliable === false) continue;
    const [kA, kB] = MODE_B_POM_ANCHORS[pom];
    const a = byKind[kA], b = byKind[kB];
    if (!a || !b || !Number.isFinite(Number(a.x)) || !Number.isFinite(Number(b.x))) continue;
    const dx = (Number(a.x) - Number(b.x)) * W, dy = (Number(a.y) - Number(b.y)) * H;
    const px = Math.hypot(dx, dy);
    if (!(px > 0)) continue;
    const confirmed = !a.reviewRequired && !b.reviewRequired && inkSourced(a.source) && inkSourced(b.source);
    const conf = rank[a.confidence] <= rank[b.confidence] ? (a.confidence || 'low') : (b.confidence || 'low');
    rows[pom] = { pom, view: MODE_B_POM_VIEW[pom], px, median: Number(sug.median), confirmed, confidence: conf };
  }

  // One robust view-local scale from all that view's sketch-reliable POMs
  // (candidate scale = median/px). Dispersion = trust; front never shares back.
  const views = {};
  for (const pom of Object.keys(rows)) {
    const r = rows[pom];
    (views[r.view] = views[r.view] || []).push(r);
  }
  for (const view of Object.keys(views)) {
    const vr = views[view];
    const candidates = vr.map(r => r.median / r.px);
    if (candidates.length < 2) continue;                 // need >=2 POMs to fit a scale
    const scale = mbMedian(candidates);
    const styleOffset = mbStyleOffset(vr.map(r => ({ sketch: r.px * scale, median: r.median })));
    for (const r of vr) {
      const sketch = r.px * scale;
      const spreadFrac = 0.06;                            // corpus between-style spread (provisional; tuned by the accuracy gate)
      const sigmaFrac = mbSketchSigmaFrac(false, r.confirmed, r.pom === '7' || r.pom === '8');
      const f = mbFuseValue({ sketch, median: r.median, priorSpreadFrac: spreadFrac, sketchSigmaFrac: sigmaFrac, styleOffset: styleOffset.offset });
      const diagnosis = mbDiagnose(f.residual, styleOffset.dispersion);
      out[r.pom] = {
        value_in: f.fused, sketch_in: mbRound(sketch, 3), library_in: r.median,
        k: f.k, residual: f.residual, styleOffset: styleOffset.offset, dispersion: styleOffset.dispersion,
        diagnosis, confidence: diagnosis === 'coherent' ? (r.confidence === 'high' ? 'medium' : 'low') : 'low',
        decision: diagnosis === 'coherent' ? 'ESTIMATED_SUGGESTION' : 'REVIEW_REQUIRED',
        scaleSource: 'library_multi_anchor_inference',
      };
    }
  }
  return out;
}

  // ---- src/ui/spec-visibility.js ----
// Per-POM line visibility on the canvas: the state helpers plus the DOM
// controls (the per-row × / + toggle and the sticky "Hide all / Show all"
// row) that expose it in the Measurements panel.
// Extracted from src/ui/spec-panel.js; the panel orchestrator that calls
// these lives there, and the row builders that embed the toggle live in
// src/ui/spec-row-builders.js.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Per-POM visibility (review overlay) ----
  // Hide toggles let the TD isolate one POM line at a time on the canvas so
  // they can eyeball whether Auto Mode picked the right anchors. Kept as
  // arrays on state (serialization-friendly); the helpers below normalize
  // to a set-like lookup. Session-only, not persisted.
  //
  // US-093 / ADR 0053 code review, 2026-08-21: a hidden line is not merely
  // undrawn — canAddCurveAnchor() (canvas-tools.js) refuses it, so a
  // panel-only refresh leaves "Add point" visible and .active on a line every
  // click now silently refuses. Hence updateUI(), not renderSpecPanel(), and
  // one exit for it: the mutators here plus the setHiddenAnnIds debug hook
  // (src/auto/debug-api.js), which drifted once by taking its own route. The
  // only other writers clear the set inside a bigger reset (board-reset.js,
  // project-load.js) and already end in updateUI(). Drafts are out of scope:
  // nothing updateUI() syncs reads isDraftHidden, so toggleDraftHidden
  // refreshes the panel alone.
  function syncAfterHiddenPomChange() {
    updateUI();
    requestRender();
  }

  // US-096 / ADR 0055 code review, 2026-08-23: hiding is a POM-REVIEW gesture,
  // so it can only apply to a measurement line.
  //
  // state.hiddenAnnIds is not pruned when a line changes role, and nothing else
  // could prune it — a role flip is reachable from the Stitches menu, a preset,
  // and the spec panel's own POM cell. Deriving the answer here instead makes it
  // self-healing from every one of those paths at once.
  //
  // Without this, a hidden POM line restyled to a stitch style was stranded: not
  // painted (render-loop and visibleExportAnnotations both skip hidden lines),
  // no spec row left to carry its × toggle, and filtered out of
  // getSelectedAnnotationIds so it could not even be clicked. It still counted
  // in "Annotations: n" and still blocked Clear. It could also drive
  // hideablePomCount() - hiddenPomCount() negative, which permanently
  // suppressed the Hide-all control.
  function isAnnHidden(id) {
    if (id == null) return false;
    const ids = state.hiddenAnnIds;
    if (!Array.isArray(ids)) return false;
    if (ids.indexOf(id) === -1) return false;
    const ann = (state.annotations || []).find(a => a && a.id === id);
    return ann ? isMeasurementAnnotation(ann) : true;
  }

  function isDraftHidden(id) {
    if (id == null) return false;
    const ids = state.hiddenDraftIds;
    if (!Array.isArray(ids)) return false;
    return ids.indexOf(id) !== -1;
  }

  function toggleAnnHidden(id) {
    if (id == null) return;
    if (!Array.isArray(state.hiddenAnnIds)) state.hiddenAnnIds = [];
    const idx = state.hiddenAnnIds.indexOf(id);
    if (idx === -1) state.hiddenAnnIds.push(id);
    else state.hiddenAnnIds.splice(idx, 1);
    syncAfterHiddenPomChange();
  }

  function toggleDraftHidden(id) {
    if (id == null) return;
    if (!Array.isArray(state.hiddenDraftIds)) state.hiddenDraftIds = [];
    const idx = state.hiddenDraftIds.indexOf(id);
    if (idx === -1) state.hiddenDraftIds.push(id);
    else state.hiddenDraftIds.splice(idx, 1);
    renderSpecPanel();
    requestRender();
  }

  // Counted through isAnnHidden rather than off the raw array, so an id left
  // behind by a line that has since become construction cannot make this
  // exceed hideablePomCount() and drive the visible count negative.
  function hiddenPomCount() {
    const a = Array.isArray(state.hiddenAnnIds)
      ? state.hiddenAnnIds.filter(id => isAnnHidden(id)).length : 0;
    const d = Array.isArray(state.hiddenDraftIds) ? state.hiddenDraftIds.length : 0;
    return a + d;
  }

  // How many POM lines can be toggled at all: drawn annotations plus (in Auto
  // Mode) outstanding drafts. Template rows with no line drawn yet are not
  // hideable, so they don't count. Drives whether the visibility control row
  // renders and whether "Hide all" has anything to act on.
  function hideablePomCount() {
    // US-096: construction lines are not POMs, so they neither count towards
    // "is there anything to hide" nor get hidden by Hide all.
    let n = measurementAnnotations().length;
    if (state.appMode === 'auto' && state.autoMode && Array.isArray(state.autoMode.draftAnnotations)) {
      n += state.autoMode.draftAnnotations.length;
    }
    return n;
  }

  function showAllPoms() {
    let changed = false;
    if (Array.isArray(state.hiddenAnnIds) && state.hiddenAnnIds.length > 0) {
      state.hiddenAnnIds = [];
      changed = true;
    }
    if (Array.isArray(state.hiddenDraftIds) && state.hiddenDraftIds.length > 0) {
      state.hiddenDraftIds = [];
      changed = true;
    }
    if (!changed) return;
    syncAfterHiddenPomChange();
  }

  // Inverse of showAllPoms: hide every visible POM line at once so the TD can
  // clear the sketch and reveal lines one at a time. Mirrors showAllPoms'
  // ann + draft handling so the two stay symmetric.
  function hideAllPoms() {
    let changed = false;
    if (!Array.isArray(state.hiddenAnnIds)) state.hiddenAnnIds = [];
    for (const ann of measurementAnnotations()) {
      if (ann && ann.id != null && state.hiddenAnnIds.indexOf(ann.id) === -1) {
        state.hiddenAnnIds.push(ann.id);
        changed = true;
      }
    }
    if (state.appMode === 'auto' && state.autoMode && Array.isArray(state.autoMode.draftAnnotations)) {
      if (!Array.isArray(state.hiddenDraftIds)) state.hiddenDraftIds = [];
      for (const draft of state.autoMode.draftAnnotations) {
        if (draft && draft.id != null && state.hiddenDraftIds.indexOf(draft.id) === -1) {
          state.hiddenDraftIds.push(draft.id);
          changed = true;
        }
      }
    }
    if (!changed) return;
    syncAfterHiddenPomChange();
  }

  // Small × / + toggle used in each POM row. Text intentionally kept to a
  // single glyph so the button stays out of the row's way.
  function buildVisibilityToggleButton(hidden, onToggle, opts) {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'pom-vis-btn' + (hidden ? ' is-hidden' : '');
    btn.textContent = hidden ? '+' : '×';
    btn.title = hidden
      ? 'Show this POM line on the sketch'
      : 'Hide this POM line so you can review other lines alone';
    btn.setAttribute('aria-pressed', hidden ? 'true' : 'false');
    if (opts && opts.disabled) {
      btn.disabled = true;
      btn.title = opts.disabledTitle || 'Nothing drawn yet for this POM.';
    }
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (btn.disabled) return;
      onToggle();
    });
    return btn;
  }

  // Sticky control row at the top of the panel. Shows "Hide all POMs" while any
  // line is still visible and "Show all POMs (N hidden)" while any line is
  // hidden — both together when the sketch is partially hidden.
  function buildVisibilityControlRow() {
    const tr = document.createElement('tr');
    tr.className = 'spec-show-all-row';
    const td = document.createElement('td');
    td.colSpan = SPEC_COL_COUNT;
    const wrap = document.createElement('div');
    wrap.className = 'spec-vis-actions';

    const hiddenCount = hiddenPomCount();
    const visibleCount = hideablePomCount() - hiddenCount;

    if (visibleCount > 0) {
      const hideBtn = document.createElement('button');
      hideBtn.type = 'button';
      hideBtn.className = 'spec-hide-all-btn';
      hideBtn.textContent = 'Hide all POMs';
      hideBtn.title = 'Hide every POM line on the sketch so you can reveal them one at a time.';
      hideBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        hideAllPoms();
      });
      wrap.appendChild(hideBtn);
    }
    if (hiddenCount > 0) {
      const showBtn = document.createElement('button');
      showBtn.type = 'button';
      showBtn.className = 'spec-show-all-btn';
      showBtn.textContent = 'Show all POMs (' + hiddenCount + ' hidden)';
      showBtn.title = 'Restore visibility for every hidden POM line on the sketch.';
      showBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        showAllPoms();
      });
      wrap.appendChild(showBtn);
    }
    td.appendChild(wrap);
    tr.appendChild(td);
    return tr;
  }

  function appendVisibilityToggle(td, opts) {
    const btn = buildVisibilityToggleButton(!!opts.hidden, opts.onToggle, {
      disabled: !!opts.disabled,
      disabledTitle: opts.disabledTitle,
    });
    td.appendChild(btn);
  }

  // ---- src/ui/spec-values.js ----
// Value model behind the Measurements panel's Size L / Size L2 / TOL / 中文 /
// English columns: built-in POM name fallbacks, the Tier-0 library-suggestion
// lookup, the ADR 0033 Mode-B measured-fusion gate, the imperial
// fraction <-> decimal math, the state.pomSpecs read/write layer, and the
// tolerance evaluation shared with the on-canvas readout. buildSpecInputCell
// lives here too because its ArrowUp/Down stepping is bound to
// scheduleSpecStepCommit's module-private timer.
// Extracted from src/ui/spec-panel.js; the row/cell DOM that consumes these
// values lives in src/ui/spec-row-builders.js.
// Source part for app.js. Run `npm run build` after editing.

  // ---- Size L / TOL cell helpers ----
  // Values are stored per POM label in state.pomSpecs, so a paired row can
  // hold two independent Size L / TOL values (e.g. POM 1 Relax vs POM 2
  // Extend) even though only the primary row is visible.
  // Built-in labels for a POM (from POM_TEMPLATE), used as defaults for the
  // editable Description (English) and 中文 columns when the project has no
  // per-POM override.
  function builtinPomZh(pomKey) {
    return getPomInfo(String(pomKey == null ? '' : pomKey).trim()).zh || '';
  }
  function builtinPomEn(pomKey) {
    return getPomInfo(String(pomKey == null ? '' : pomKey).trim()).desc || '';
  }

  // ---- Library-value suggestions (Tier-0 measurement layer) ----
  // Each POM may carry a corpus-derived Size L suggestion (median + range +
  // default TOL + confidence) loaded from auto_mode_rules/sizeL-suggestions.json
  // and exposed as POM_SUGGESTIONS. These are PRE-FILLED as TD-owned defaults:
  // shown muted with a "library" badge, used for tolerance + export until the
  // TD types an override, and never persisted into state.pomSpecs — so a
  // regenerated corpus updates every POM the TD has not touched. Values are
  // stored in inches (the corpus unit); we only convert for display when the TD
  // has switched the working scale to cm (docs/decisions/0009-*).
  function getPomSuggestion(pomKey) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    if (!key || !POM_SUGGESTIONS) return null;
    const s = POM_SUGGESTIONS[key];
    return s && typeof s === 'object' ? s : null;
  }

  // True when the POM has a usable library median (corpus data exists).
  function hasSuggestedValue(pomKey) {
    const s = getPomSuggestion(pomKey);
    return !!(s && s.median != null && s.n > 0);
  }

  // ---- Mode B measured suggestions (ADR 0033, flagged OFF by default) ----
  // When Mode B is on, a sketch-reliable POM's Size-L suggestion becomes the
  // library×sketch FUSED value derived from the detected anchors (fusion.js) —
  // still a suggestion, never assigned or persisted. Memoized by a cheap anchor
  // signature so getPomSpec stays cheap across a full panel rebuild.
  let _measuredCache = { sig: null, map: null };
  function measuredSuggestionsMap() {
    if (typeof modeBAnyEnabled !== 'function' || !modeBAnyEnabled()) return null;
    const am = (state && state.autoMode) || {};
    const anchors = Array.isArray(am.anchors) ? am.anchors : [];
    const det = am.detection || null;
    if (!anchors.length || !det) return null;
    const first = anchors[0] || {};
    const sig = anchors.length + ':' + (det.naturalWidth || 0) + 'x' + (det.naturalHeight || 0) + ':' + (first.kind || '') + first.x;
    if (_measuredCache.sig === sig) return _measuredCache.map;
    let map = null;
    try { map = mbComputeMeasuredSuggestions(anchors, POM_SUGGESTIONS, { width: det.naturalWidth, height: det.naturalHeight }); }
    catch (_e) { map = null; }
    _measuredCache = { sig, map };
    return map;
  }
  // Gated measured entry for a POM: only a coherent, positive numeric proposal
  // surfaces; a conflicted (review/outlier) POM returns null so the panel falls
  // back to the library value rather than showing a wrong number.
  function measuredFor(pomKey) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    // Per-POM roll-out gate (US-041): only a globally-flagged or promoted POM
    // surfaces a measured value.
    if (typeof modeBEnabledForPom === 'function' && !modeBEnabledForPom(key)) return null;
    const map = measuredSuggestionsMap();
    if (!map) return null;
    const m = map[key];
    return (m && m.decision === 'ESTIMATED_SUGGESTION' && Number.isFinite(Number(m.value_in)) && Number(m.value_in) > 0) ? m : null;
  }

  // Corpus inches -> active display unit (no-op for the default 'in').
  function suggestionToDisplay(inchValue) {
    if (inchValue == null) return null;
    return state.calibration.unit === 'cm' ? inchValue * 2.54 : inchValue;
  }

  // Precision-preserving formatter (formatMeasure rounds to 0.1, too coarse for
  // eighth-inch specs like 3.75 or a 1/8 tolerance). Keeps up to 3 decimals.
  function formatSuggestion(inchValue) {
    const v = suggestionToDisplay(inchValue);
    if (v == null) return '';
    return String(Math.round(v * 1000) / 1000);
  }

  // ---- US-048: imperial fraction display for spec numbers ----
  // Size L / Size L2 / TOL are shown (panel) and exported (TOL) as reduced
  // fractions in INCH mode — the house spec convention (0.375 → 3/8, 5.5 →
  // 5 1/2, 2.25 → 2 1/4). cm mode keeps decimals. A value is fractionised only
  // when it lands EXACTLY on the 1/16 grid, so an odd/typed value (9.9, a raw
  // median) is shown verbatim rather than misrepresented as a near fraction.
  function gcdInt(a, b) { a = Math.abs(a); b = Math.abs(b); while (b) { const t = b; b = a % b; a = t; } return a || 1; }
  function decimalToFraction(value) {
    const DEN = 16;
    const v = Math.max(0, Number(value) || 0);
    const whole = Math.floor(v + 1e-9);
    const num = Math.round((v - whole) * DEN);
    if (num >= DEN) return String(whole + 1);
    if (num === 0) return String(whole);
    const g = gcdInt(num, DEN);
    const frac = (num / g) + '/' + (DEN / g);
    return whole > 0 ? (whole + ' ' + frac) : frac;
  }
  // Display string for a stored spec value: a fraction when on-grid in inches,
  // else the value verbatim. Preserves a leading "± " (TOL may carry one).
  function inchesToFractionOrDecimal(str) {
    const raw = String(str == null ? '' : str).trim();
    if (!raw) return raw;
    if (state.calibration.unit !== 'in') return raw; // cm → decimal as-is
    const pm = /^±\s*/.test(raw) ? '± ' : '';
    const body = raw.replace(/^±\s*/, '');
    const n = parseSpecNumber(body);
    if (n == null || n < 0) return raw;
    const scaled = n * 16;
    if (Math.abs(scaled - Math.round(scaled)) > 1e-6) return raw; // off 1/16 grid → decimal
    return pm + decimalToFraction(n);
  }
  function specNumEq(a, b) { return a != null && b != null && Math.abs(a - b) < 1e-9; }

  // Parse a fraction / mixed-number / decimal string ('1/4', '5 1/2', '0.25').
  // TOL defaults arrive as fractions but the tool's inputs are decimal.
  function fractionToNumber(raw) {
    if (raw == null) return null;
    const str = String(raw).trim();
    if (!str) return null;
    const mixed = str.match(/^(\d+)\s+(\d+)\/(\d+)$/);
    if (mixed) return parseInt(mixed[1], 10) + parseInt(mixed[2], 10) / parseInt(mixed[3], 10);
    const frac = str.match(/^(\d+)\/(\d+)$/);
    if (frac) return parseInt(frac[1], 10) / parseInt(frac[2], 10);
    const n = parseFloat(str);
    return Number.isFinite(n) ? n : null;
  }

  // Formatted Size L suggestion ('' when the POM has no library data). With
  // Mode B on, a gated measured (library×sketch fused) value takes precedence
  // over the raw library median; both remain TD-owned suggestions.
  function suggestedSizeL(pomKey) {
    const m = measuredFor(pomKey);
    if (m) return formatSuggestion(m.value_in);
    const s = getPomSuggestion(pomKey);
    if (!s || s.median == null || !(s.n > 0)) return '';
    return formatSuggestion(s.median);
  }

  // Formatted default-TOL suggestion as a decimal in the active unit.
  function suggestedTol(pomKey) {
    const s = getPomSuggestion(pomKey);
    if (!s || !s.tol) return '';
    const n = fractionToNumber(s.tol);
    return n == null ? '' : formatSuggestion(n);
  }

  function getPomSpec(pomKey) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    if (!key) return { sizeL: '', sizeL2: '', tol: '', zh: '', en: '' };
    const raw = (state.pomSpecs && state.pomSpecs[key]) || {};
    return {
      // sizeL / tol fall back to the library suggestion when the TD has no
      // override (mirrors how en / zh fall back to the built-in name). This is
      // what pre-fills the panel and drives tolerance + Excel export.
      sizeL: raw.sizeL != null ? String(raw.sizeL) : suggestedSizeL(key),
      sizeL2: raw.sizeL2 != null ? String(raw.sizeL2) : '',
      tol: raw.tol != null ? String(raw.tol) : suggestedTol(key),
      // en / zh fall back to the built-in name so every row shows a label
      // without the TD typing one; only edits that differ are persisted.
      zh: raw.zh != null ? String(raw.zh) : builtinPomZh(key),
      en: raw.en != null ? String(raw.en) : builtinPomEn(key),
    };
  }

  function setPomSpec(pomKey, field, rawValue) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    if (!key) return false;
    if (field !== 'sizeL' && field !== 'sizeL2' && field !== 'tol' && field !== 'zh' && field !== 'en') return false;
    if (!state.pomSpecs || typeof state.pomSpecs !== 'object') state.pomSpecs = {};
    const trimmed = String(rawValue == null ? '' : rawValue).trim();
    const current = state.pomSpecs[key] || {};
    const next = { ...current };
    // en / 中文 are name fields: a blank value OR one equal to the built-in
    // default stores no override (so the built-in can still evolve); anything
    // else is a per-project override. sizeL / tol just clear on blank.
    let clears;
    if (field === 'zh') clears = (trimmed === '' || trimmed === builtinPomZh(key));
    else if (field === 'en') clears = (trimmed === '' || trimmed === builtinPomEn(key));
    // sizeL / tol store no override when blank OR equal to the library
    // suggestion, so an accepted suggestion stays live and a regenerated corpus
    // can still evolve it (matches en / zh handling above).
    // US-048: compare NUMERICALLY, so accepting a suggestion still counts as
    // "no override" whether the field shows it as a fraction (5 1/2) or a
    // decimal (5.5) — both parse to the same number.
    else if (field === 'sizeL') clears = (trimmed === '' || trimmed === suggestedSizeL(key) || specNumEq(parseSpecNumber(trimmed), parseSpecNumber(suggestedSizeL(key))));
    else if (field === 'tol') clears = (trimmed === '' || trimmed === suggestedTol(key) || specNumEq(parseSpecNumber(trimmed), parseSpecNumber(suggestedTol(key))));
    else clears = (trimmed === '');
    if (clears) {
      if (next[field] == null) return false;
      delete next[field];
    } else {
      if (next[field] === trimmed) return false;
      next[field] = trimmed;
    }
    if (Object.keys(next).length === 0) {
      if (!state.pomSpecs[key]) return false;
      delete state.pomSpecs[key];
    } else {
      state.pomSpecs[key] = next;
    }
    return true;
  }

  function specFieldTdClass(field) {
    if (field === 'sizeL' || field === 'sizeL2') return 'spec-td-size';
    if (field === 'zh') return 'spec-td-zh';
    return 'spec-td-tol';
  }

  // US-031: rapid arrow-steps in a Size L / L2 / TOL field are one "burst" —
  // each step writes the spec immediately (so the tolerance chip tracks it),
  // but history commits once, after the last press. renderSpecPanel's
  // editing-field guard keeps the commit from rebuilding under the caret.
  const SPEC_STEP_COMMIT_MS = 700;
  let specStepCommitTimer = null;

  function scheduleSpecStepCommit() {
    if (specStepCommitTimer) clearTimeout(specStepCommitTimer);
    specStepCommitTimer = setTimeout(() => {
      specStepCommitTimer = null;
      pushHistoryIfChanged();
    }, SPEC_STEP_COMMIT_MS);
  }

  function buildSpecInputCell(pomKey, field, placeholder) {
    const td = document.createElement('td');
    td.className = specFieldTdClass(field);
    const input = document.createElement('input');
    input.type = 'text';
    input.className = field === 'zh' ? 'spec-zh' : 'spec-val';
    // US-048: Size L / L2 / TOL display as imperial fractions (inch mode); zh
    // is a name field, shown verbatim.
    const rawFieldVal = getPomSpec(pomKey)[field];
    input.value = (field === 'sizeL' || field === 'sizeL2' || field === 'tol')
      ? inchesToFractionOrDecimal(rawFieldVal)
      : rawFieldVal;
    input.placeholder = placeholder || '';
    input.addEventListener('change', () => {
      if (setPomSpec(pomKey, field, input.value)) pushHistoryIfChanged();
    });
    // US-050: focusing selects the whole value, so one click + type REPLACES a
    // pre-filled library value — no manual clearing. Deferred a tick so a click
    // that positions the caret doesn't immediately deselect.
    input.addEventListener('focus', () => { setTimeout(() => { try { input.select(); } catch (_) { /* noop */ } }, 0); });
    // US-031: ArrowUp/Down steps the numeric spec fields by 1/8 — the Excel
    // export's fraction grain — or 0.1 in cm mode; Shift = a whole unit.
    if (field === 'sizeL' || field === 'sizeL2' || field === 'tol') {
      // US-035: name the unit in the tooltip, and mark unparseable values
      // instead of ignoring them silently. Refreshed live while typing.
      const unitTitle = () => {
        const u = state.calibration.unit || 'in';
        if (field === 'tol') return 'Tolerance in ' + u + ' — allowed ± variance from Size L. Decimal (0.25) or fraction (1/4).';
        if (field === 'sizeL2') return 'Optional Size L2 sample base in ' + u + ' for the depth tier — blank derives it from Size L.';
        return 'Size L target in ' + u + '. Decimal (12.5) or fraction (12 1/2).';
      };
      const refreshValidity = () => {
        const raw = input.value.trim();
        const bad = raw !== '' && parseSpecNumber(raw) == null;
        input.classList.toggle('spec-invalid', bad);
        input.title = bad
          ? 'Not a number — this value is ignored. Enter a decimal (12.5) or a fraction (12 1/2).'
          : unitTitle();
      };
      input.addEventListener('input', refreshValidity);
      refreshValidity();
      input.addEventListener('keydown', (ev) => {
        if (ev.key !== 'ArrowUp' && ev.key !== 'ArrowDown') return;
        ev.preventDefault();
        const unitStep = state.calibration.unit === 'cm' ? 0.1 : 0.125;
        const step = (ev.shiftKey ? 1 : unitStep) * (ev.key === 'ArrowUp' ? 1 : -1);
        const base = parseSpecNumber(input.value);
        const next = Math.max(0, Math.round(((base == null ? 0 : base) + step) * 1000) / 1000);
        // Write the decimal to the store, but keep the field showing a fraction
        // (inch mode) so stepping by 1/8 reads as 3/8 → 1/2 → 5/8, not decimals.
        if (setPomSpec(pomKey, field, String(next))) scheduleSpecStepCommit();
        input.value = inchesToFractionOrDecimal(String(next));
        const tr = input.closest('tr');
        if (tr && tr.dataset.annId) refreshMeasuredValueForAnnotation(Number(tr.dataset.annId));
        refreshValidity();
      });
    }
    td.appendChild(input);
    return td;
  }

  // Read-only measured value for a drawn line: its length in the calibrated
  // unit when a scale is set, else raw board pixels. This is the connection
  // from the detected / adjusted geometry back to a usable number — Size L is
  // the target, TOL the allowed variance, and this is what the sketch is.
  function measuredValueText(ann) {
    if (!ann || !ann.start || !ann.end) return '';
    const lengthPx = lineLength(ann);
    if (!(lengthPx > 0)) return '';
    if (state.calibration.unitsPerPx != null) {
      return formatMeasure(lengthPx * state.calibration.unitsPerPx) + ' ' + state.calibration.unit;
    }
    return Math.round(lengthPx) + ' px';
  }

  // Tolerant numeric parse for a Size L / TOL field (leading number wins;
  // blank / non-numeric → null so the caller can treat it as "not set").
  // US-035: also accepts the fraction forms TDs actually type — "1/2",
  // "12 1/2", "12-1/2" — so a typed fraction behaves like its decimal
  // everywhere this parser is used (chip, readout, stepping, size run,
  // Excel export L2).
  function parseSpecNumber(raw) {
    if (raw == null) return null;
    const s = String(raw).trim();
    if (!s) return null;
    const frac = s.match(/^(\d+(?:\.\d+)?)?[\s-]*(\d+)\s*\/\s*(\d+)$/);
    if (frac && parseInt(frac[3], 10) !== 0) {
      const whole = frac[1] ? parseFloat(frac[1]) : 0;
      return whole + parseInt(frac[2], 10) / parseInt(frac[3], 10);
    }
    const n = parseFloat(s);
    return Number.isFinite(n) ? n : null;
  }

  // Compare a drawn line's measured length against its Size L ± TOL target.
  // Only meaningful when a real-unit scale is set (Size L / TOL are entered in
  // the calibrated unit; an uncalibrated px value can't be compared to cm/in).
  // status: 'in' (within TOL) | 'out' (outside TOL) | 'delta' (target set, no
  // TOL — show the difference only) | null (cannot compare).
  function evaluateSpecTolerance(ann, pomKey) {
    const out = { measured: null, target: null, tol: null, delta: null, status: null };
    if (!ann || state.calibration.unitsPerPx == null) return out;
    const lengthPx = lineLength(ann);
    if (!(lengthPx > 0)) return out;
    out.measured = lengthPx * state.calibration.unitsPerPx;
    const target = parseSpecNumber(getPomSpec(pomKey).sizeL);
    if (target == null) return out;
    out.target = target;
    out.delta = out.measured - target;
    const tol = parseSpecNumber(getPomSpec(pomKey).tol);
    if (tol == null) { out.status = 'delta'; return out; }
    out.tol = Math.abs(tol);
    out.status = Math.abs(out.delta) <= out.tol + 1e-9 ? 'in' : 'out';
    return out;
  }

  // Signed Δ against Size L with its ✓ / ✗ verdict — one formatter shared by
  // the panel's Value-cell chip and the on-canvas adjustment readout
  // (US-029), so the two can never disagree.
  function specDeltaText(ev) {
    if (!ev || !ev.status) return '';
    const signed = (ev.delta > 0 ? '+' : ev.delta < 0 ? '−' : '±') + formatMeasure(Math.abs(ev.delta));
    return ev.status === 'in' ? signed + ' ✓' : ev.status === 'out' ? signed + ' ✗' : signed;
  }

  // ---- src/ui/spec-row-builders.js ----
// Row and cell DOM builders for the Measurements table: the suggestion badge
// decoration, the English-description / POM / measured-value cells, the
// pairing hint, the template and annotation row shapes, and the custom-POM
// (US-011) remove control + "+ Add POM" row.
// Extracted from src/ui/spec-panel.js; the values these cells display come
// from src/ui/spec-values.js, the × / + toggle from src/ui/spec-visibility.js,
// and the orchestrator that assembles the rows stays in src/ui/spec-panel.js.
//
// NOTE: renderSpecPanel's focus-preservation guard decides what is "mid-edit
// safe" during a rebuild from three row selectors — tr[data-ann-id],
// tr[data-pom-key] and tr.add-pom-row. A row built here that matches none of
// them will have a TD's half-typed value blown away by the next rebuild, so
// keep those class / data-attribute names in sync with that guard.
// Source part for app.js. Run `npm run build` after editing.

  function appendSuggestBadge(td, text, cls, title) {
    const badge = document.createElement('div');
    badge.className = 'spec-conf spec-suggest-badge ' + cls;
    badge.textContent = text;
    if (title) badge.title = title;
    td.appendChild(badge);
  }

  // Decorate a Size L / TOL cell to show it holds a library suggestion (not a
  // TD entry): mute the input and, for Size L, add a "library · <confidence>"
  // provenance badge — or a "no data" badge for POMs with no corpus value
  // (15 back-straps distance, 16 front apex). Skipped once the TD overrides.
  function decorateSuggestedCell(td, pomKey, field) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    const sug = getPomSuggestion(key);
    if (!sug) return;
    const raw = (state.pomSpecs && state.pomSpecs[key]) || {};
    const hasOverride = raw[field] != null;
    if (hasOverride) return;

    if (field === 'sizeL' && !hasSuggestedValue(key)) {
      appendSuggestBadge(td, 'no data', 'very_low',
        'No library value for this POM — enter Size L manually.');
      return;
    }
    const suggested = field === 'sizeL' ? suggestedSizeL(key) : suggestedTol(key);
    if (!suggested) return;
    const input = td.querySelector('input');
    if (input) input.classList.add('is-suggested');
    if (field === 'sizeL') {
      // Mode B: a fused sketch measurement is a distinct, estimated suggestion.
      const m = measuredFor(key);
      if (m) {
        appendSuggestBadge(td, 'measured · ' + (m.confidence || 'low'), 'library',
          'Sketch measurement (Mode B, estimated) — detected anchors × view-local scale, fused toward the library median'
          + ' (k ' + m.k + ', residual ' + (Math.round((m.residual || 0) * 1000) / 10) + '%, library ' + m.library_in + ' in). Type to override.');
        return;
      }
      const conf = sug.confidence || 'very_low';
      const rangeIn = (sug.min != null && sug.max != null) ? ' · range ' + sug.min + '–' + sug.max + ' in' : '';
      appendSuggestBadge(td, 'library · ' + conf, 'library',
        'Library suggestion — median of ' + sug.n + ' Size-L samples' + rangeIn
        + ' · source: corpus. Type to override.');
    }
  }

  // Editable English Description cell (mirrors the 中文 column): a textarea
  // pre-filled with the built-in POM name, editable, with per-POM overrides
  // persisted in state.pomSpecs[pom].en. Used on both template and applied
  // rows so the TD can rename any POM's English term. `ann` (optional) links
  // focus to the annotation so clicking the field selects its line.
  function buildEnDescCell(pomKey, ann) {
    const td = document.createElement('td');
    const input = document.createElement('textarea');
    input.className = 'spec-desc';
    input.rows = 2;
    input.value = getPomSpec(pomKey).en;
    input.placeholder = builtinPomEn(pomKey) || '—';
    const refreshTitle = () => { input.title = input.value || input.placeholder || ''; };
    refreshTitle();
    if (ann) input.addEventListener('focus', () => setSelection('annotation', ann.id));
    input.addEventListener('input', refreshTitle);
    input.addEventListener('change', () => {
      if (setPomSpec(pomKey, 'en', input.value)) pushHistoryIfChanged();
      refreshTitle();
    });
    td.appendChild(input);
    return td;
  }

  // Rich hover tooltip for a POM badge. Surfaces the JSON contract data
  // (view, required + optional anchors, expected confidence tier) so the
  // TD reviewing evidence can see at a glance what a POM is supposed to
  // depend on. Falls back to the standard description for anything not
  // in the POM_TEMPLATE (e.g. custom-labeled annotations).
  function getPomTooltip(pomKey) {
    const key = String(pomKey == null ? '' : pomKey).trim();
    if (!key) return '';
    const entry = POM_TEMPLATE && POM_TEMPLATE[key];
    if (!entry) return getPomInfo(key).desc || '';
    const bits = [];
    bits.push('POM ' + key + ' — ' + entry.desc);
    if (entry.viewRole) bits.push('View: ' + prettyView(entry.viewRole));
    if (Array.isArray(entry.requiredAnchors) && entry.requiredAnchors.length) {
      bits.push('Anchors: ' + entry.requiredAnchors.join(' ↔ '));
    }
    if (Array.isArray(entry.optionalAnchors) && entry.optionalAnchors.length) {
      bits.push('Optional: ' + entry.optionalAnchors.join(', '));
    }
    if (entry.expected_confidence_tier) {
      bits.push('Expected confidence: ' + entry.expected_confidence_tier);
    }
    return bits.join('\n');
  }

  function prettyView(viewRole) {
    if (viewRole === 'front_outer') return 'front outer';
    if (viewRole === 'front_inner') return 'front inner';
    if (viewRole === 'back') return 'back';
    return String(viewRole);
  }

  function buildMeasuredValueCell(ann, pomKey) {
    const td = document.createElement('td');
    td.className = 'spec-td-value';
    const text = measuredValueText(ann);
    if (!text) {
      td.textContent = '—';
      td.title = 'No line drawn for this POM yet.';
      return td;
    }
    const measuredEl = document.createElement('span');
    measuredEl.className = 'spec-measured';
    measuredEl.textContent = text;
    td.appendChild(measuredEl);

    const unit = state.calibration.unit;
    const ev = evaluateSpecTolerance(ann, pomKey);
    if (ev.status) {
      const signed = (ev.delta > 0 ? '+' : ev.delta < 0 ? '−' : '±') + formatMeasure(Math.abs(ev.delta));
      const chip = document.createElement('span');
      chip.className = 'spec-delta spec-delta-' + (ev.status === 'in' ? 'in' : ev.status === 'out' ? 'out' : 'neutral');
      chip.textContent = specDeltaText(ev);
      td.appendChild(chip);
      if (ev.status === 'in') td.classList.add('spec-in');
      else if (ev.status === 'out') td.classList.add('spec-out');
      td.title = ev.status === 'delta'
        ? `Measured ${formatMeasure(ev.measured)} ${unit} · target ${formatMeasure(ev.target)} ${unit} · Δ ${signed} (no TOL set)`
        : `Measured ${formatMeasure(ev.measured)} ${unit} · target ${formatMeasure(ev.target)} ± ${formatMeasure(ev.tol)} ${unit} · Δ ${signed} · ${ev.status === 'in' ? 'in tolerance' : 'OUT of tolerance'}`;
    } else {
      td.title = state.calibration.unitsPerPx != null
        ? 'Measured from the line on the sketch. Enter Size L (+ TOL) to check tolerance.'
        : 'Measured length in pixels — use Set Scale to show real ' + state.calibration.unit + '.';
    }

    // Per-row calibration shortcut: because a line exists here (measuredValueText
    // was non-empty), the TD can set the board scale straight from this POM —
    // type its real length and every POM re-estimates. Reuses the Set Scale
    // engine (openScaleDialog), so it stays one global, undoable scale.
    const refPx = lineLength(ann);
    if (refPx > 0) {
      const entry = POM_TEMPLATE && POM_TEMPLATE[String(pomKey)];
      const refLabel = entry && entry.desc ? ('POM ' + pomKey + ' — ' + entry.desc) : null;
      const scaleBtn = document.createElement('button');
      scaleBtn.type = 'button';
      scaleBtn.className = 'spec-scale-ref';
      scaleBtn.textContent = '📏';
      scaleBtn.title = state.calibration.unitsPerPx == null
        ? 'Set scale from this line — type its real length and every POM switches to real units.'
        : 'Re-calibrate scale from this line — type its real length and every POM re-estimates.';
      scaleBtn.style.cssText = 'margin-left:6px;border:none;background:none;cursor:pointer;font-size:11px;line-height:1;padding:0;opacity:0.5;';
      scaleBtn.addEventListener('mouseenter', () => { scaleBtn.style.opacity = '1'; });
      scaleBtn.addEventListener('mouseleave', () => { scaleBtn.style.opacity = '0.5'; });
      scaleBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openScaleDialog(refPx, refLabel);
      });
      td.appendChild(scaleBtn);
    }
    return td;
  }

  // Relationship hint so the split band/chest rows still show that POM 2/4
  // (Extend) are derived from POM 1/3 (Relax). Reads the pairing that still
  // drives the extension-stub geometry in the rule data.
  function pomPairHint(pomKey) {
    const entry = POM_TEMPLATE && POM_TEMPLATE[String(pomKey)];
    const pairing = entry && entry.pairing;
    if (!pairing) return '';
    if (pairing.role === 'primary') {
      return (pairing.primaryLabel || 'Primary') + ' · pairs with POM ' + pairing.partner;
    }
    if (pairing.role === 'secondary') {
      const primaryEntry = POM_TEMPLATE[String(pairing.primary)];
      const label = (primaryEntry && primaryEntry.pairing && primaryEntry.pairing.secondaryLabel) || 'Extend';
      return label + ' · derived from POM ' + pairing.primary;
    }
    return '';
  }

  function appendPairHint(descTd, pomKey) {
    const hint = pomPairHint(pomKey);
    if (!hint) return;
    const hintEl = document.createElement('div');
    hintEl.className = 'spec-pair-hint';
    hintEl.textContent = hint;
    descTd.appendChild(hintEl);
  }

  // Template row: no annotation exists yet for this POM. Shows the POM
  // number and description as read-only text plus editable Size L / TOL
  // cells so the TD can enter spec-sheet targets before drawing anything.
  function buildTemplateSpecRow(pomKey) {
    const tr = document.createElement('tr');
    tr.classList.add('template-row');
    tr.dataset.pomKey = pomKey;

    const pomTd = document.createElement('td');
    const pomBadge = document.createElement('span');
    pomBadge.className = 'spec-pom';
    pomBadge.textContent = pomKey;
    pomBadge.title = getPomTooltip(pomKey);
    pomTd.appendChild(pomBadge);
    appendVisibilityToggle(pomTd, {
      hidden: false,
      disabled: true,
      disabledTitle: 'Draw or apply a line labeled ' + pomKey + ' first.',
      onToggle: () => {},
    });

    const descTd = buildEnDescCell(pomKey, null);
    appendPairHint(descTd, pomKey);

    tr.appendChild(pomTd);
    tr.appendChild(descTd);
    tr.appendChild(buildSpecInputCell(pomKey, 'zh', ''));
    tr.appendChild(buildMeasuredValueCell(null, pomKey));
    const sizeTd = buildSpecInputCell(pomKey, 'sizeL', '');
    decorateSuggestedCell(sizeTd, pomKey, 'sizeL');
    tr.appendChild(sizeTd);
    tr.appendChild(buildSpecInputCell(pomKey, 'sizeL2', ''));
    const tolTd = buildSpecInputCell(pomKey, 'tol', '');
    decorateSuggestedCell(tolTd, pomKey, 'tol');
    tr.appendChild(tolTd);
    return tr;
  }

  // Standard one-annotation spec row
  // (POM | Description | 中文 | Value | Size L | TOL).
  function buildSingleSpecRow(ann) {
    const tr = document.createElement('tr');
    tr.dataset.annId = ann.id;
    const specKey = getLabelText(ann);
    tr.dataset.pomKey = specKey;
    if (state.selection.kind === 'annotation' && state.selection.id === ann.id) {
      tr.className = 'selected';
    }
    if (isAnnHidden(ann.id)) tr.classList.add('pom-hidden');
    tr.addEventListener('click', () => setSelection('annotation', ann.id));

    const { td: pomTd } = buildPomCell(ann);
    const descTd = buildEnDescCell(specKey, ann);
    appendPairHint(descTd, specKey);
    const zhTd = buildSpecInputCell(specKey, 'zh', '');
    const valueTd = buildMeasuredValueCell(ann, specKey);
    const sizeTd = buildSpecInputCell(specKey, 'sizeL', '');
    decorateSuggestedCell(sizeTd, specKey, 'sizeL');
    const sizeL2Td = buildSpecInputCell(specKey, 'sizeL2', '');
    const tolTd = buildSpecInputCell(specKey, 'tol', '');
    decorateSuggestedCell(tolTd, specKey, 'tol');

    tr.appendChild(pomTd);
    tr.appendChild(descTd);
    tr.appendChild(zhTd);
    tr.appendChild(valueTd);
    tr.appendChild(sizeTd);
    tr.appendChild(sizeL2Td);
    tr.appendChild(tolTd);
    return tr;
  }

  function buildPomCell(ann) {
    const td = document.createElement('td');
    const input = document.createElement('input');
    input.type = 'text';
    input.className = 'spec-pom';
    input.value = ann.text != null ? ann.text : '';
    input.placeholder = String(ann.seq);
    const refreshPomTooltip = () => {
      const key = input.value.trim() || String(ann.seq);
      const tip = getPomTooltip(key);
      input.title = tip || '';
      td.title = tip || '';
    };
    refreshPomTooltip();
    input.addEventListener('focus', () => setSelection('annotation', ann.id));
    input.addEventListener('input', refreshPomTooltip);
    input.addEventListener('change', () => {
      const v = input.value.trim();
      const next = v === '' ? null : v;
      if (ann.text !== next) { ann.text = next; pushHistoryIfChanged(); requestRender(); }
      refreshPomTooltip();
    });
    td.appendChild(input);
    appendVisibilityToggle(td, {
      hidden: isAnnHidden(ann.id),
      onToggle: () => toggleAnnHidden(ann.id),
    });
    // No metadata badges here (TD request 2026-07-10: the POM-number cell
    // shows only the number). Confidence/drawability/accepted state remain
    // visible in the Auto Mode draft-review rows.
    return { td, getValue: () => input.value.trim() };
  }

  function labelSortKey(ann) {
    const m = String(getLabelText(ann)).match(/\d+(\.\d+)?/);
    return m ? parseFloat(m[0]) : 9999;
  }

  // Small × on a custom POM's template row: removing the registry entry is
  // only offered while no drawn line carries the number (a row with a line
  // renders as a normal annotation row, so this control never shows there).
  function decorateCustomPomRow(tr, pomKey) {
    tr.classList.add('custom-pom-row');
    const pomTd = tr.querySelector('td');
    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.textContent = '×';
    removeBtn.title = 'Remove custom POM ' + pomKey + ' (no line uses it)';
    removeBtn.style.cssText = 'margin-left:4px;border:0;background:none;color:#b91c1c;cursor:pointer;font-size:12px;';
    removeBtn.addEventListener('click', (ev) => {
      ev.stopPropagation();
      state.customPoms = (state.customPoms || []).filter(p => String(p.pom) !== String(pomKey));
      if (state.pomSpecs) delete state.pomSpecs[String(pomKey)];
      pushHistoryIfChanged();
      renderSpecPanel();
      showToast('Custom POM ' + pomKey + ' removed.');
    });
    pomTd.appendChild(removeBtn);
  }

  // Full-width "+ Add POM" row (US-011 S4): creates the next free number
  // (17, 18, …) with a TD-entered English name (中文 optional). The new POM
  // gets a template-style row with full Size L / L2 / TOL / grading / export
  // parity; the 18-POM rule JSON is never touched (ADR 0018).
  function buildAddPomRow() {
    const tr = document.createElement('tr');
    tr.className = 'add-pom-row';
    const td = document.createElement('td');
    td.colSpan = SPEC_COL_COUNT;
    td.style.cssText = 'text-align:center;padding:6px;';

    const addBtn = document.createElement('button');
    addBtn.type = 'button';
    addBtn.className = 'picker-btn';
    addBtn.textContent = '+ Add POM';
    addBtn.title = 'Add a style-specific POM beyond the standard 16';
    addBtn.addEventListener('click', () => {
      const nextNum = String(nextCustomPomNumber());
      td.innerHTML = '';
      const form = document.createElement('span');
      form.style.cssText = 'display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap;';
      const label = document.createElement('span');
      label.textContent = 'POM ' + nextNum + ':';
      label.style.cssText = 'font-weight:600;font-size:12px;';
      const enInput = document.createElement('input');
      enInput.type = 'text';
      enInput.placeholder = 'Description - English (required)';
      enInput.style.cssText = 'width:220px;font-size:12px;padding:3px 6px;';
      const zhInput = document.createElement('input');
      zhInput.type = 'text';
      zhInput.placeholder = '中文 (optional)';
      zhInput.style.cssText = 'width:140px;font-size:12px;padding:3px 6px;';
      const okBtn = document.createElement('button');
      okBtn.type = 'button';
      okBtn.className = 'picker-btn';
      okBtn.textContent = 'Add';
      const cancelBtn = document.createElement('button');
      cancelBtn.type = 'button';
      cancelBtn.className = 'picker-btn';
      cancelBtn.textContent = 'Cancel';
      okBtn.addEventListener('click', () => {
        const en = enInput.value.trim();
        if (!en) { showToast('Enter an English description for the new POM.'); enInput.focus(); return; }
        if (!Array.isArray(state.customPoms)) state.customPoms = [];
        state.customPoms.push({ pom: nextNum, en, zh: zhInput.value.trim() });
        pushHistoryIfChanged();
        renderSpecPanel();
        showToast('POM ' + nextNum + ' added — label a drawn line "' + nextNum + '" to measure it.');
      });
      cancelBtn.addEventListener('click', () => renderSpecPanel());
      enInput.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') okBtn.click(); });
      zhInput.addEventListener('keydown', (ev) => { if (ev.key === 'Enter') okBtn.click(); });
      form.appendChild(label);
      form.appendChild(enInput);
      form.appendChild(zhInput);
      form.appendChild(okBtn);
      form.appendChild(cancelBtn);
      td.appendChild(form);
      enInput.focus();
    });
    td.appendChild(addBtn);
    tr.appendChild(td);
    return tr;
  }

  // ---- src/ui/spec-panel.js ----
// Measurement / spec panel orchestration.
// Source part for app.js. Run `npm run build` after editing.
//
// renderSpecPanel rebuilds the table on the right side of the board. It
// renders the Auto Mode draft review section (if drafts are present),
// then walks the 18 POM template slots in order — using a drawn
// annotation when the label matches, or a read-only template row when
// nothing has been drawn yet — pairing primary/secondary POMs into one
// row where the schema defines a pair. Every row exposes editable Size L
// and TOL inputs so the TD can enter spec-sheet targets even before a
// line is drawn; those values live on state.pomSpecs (per POM label) and
// persist through save/load + undo/redo.
//
// This file owns the assembly and the US-033 rebuild-skip fingerprint plus
// the Auto Mode status prose and draft-review rows. The pieces it assembles
// live next door: src/ui/spec-values.js (Size L / TOL value model, fraction
// math, pomSpecs read/write), src/ui/spec-row-builders.js (row + cell DOM),
// src/ui/spec-visibility.js (per-POM line visibility on the canvas), and
// src/ui/anchor-manager-panel.js (the separate floating anchor panel).
// The calibration commands the panel's note refers to (setScaleFromSelection
// / clearScale) live with their toolbar listeners in src/ui/bindings.js.

  // ---- Measurement table panel ----
  // Total column count in the spec table:
  //   POM | Description | 中文 | Value | Size L | Size L2 | TOL.
  // Value is the measured length of the drawn line (the connection back to
  // the sketch); Size L is the spec target and TOL its allowed variance.
  // Size L2 is the optional second sample base that anchors the depth tier
  // (M2–5XL2) in the Excel export — blank derives L2 = L + offset.
  const SPEC_COL_COUNT = 7;

  // ---- US-033: rebuild-skip fingerprint -----------------------------------
  // renderSpecPanel runs on every updateUI (every click), but most calls
  // change nothing the table renders from — only the selection moved. The
  // fingerprint captures the table's actual data inputs; when it matches the
  // one stored after the last full rebuild, we refresh highlight classes and
  // stop. Selection is deliberately NOT fingerprinted.
  //
  // If you add a panel feature that renders from state not listed here, add
  // its input to this fingerprint or the panel will go stale.
  let lastSpecPanelFingerprint = null;
  const specDepIds = new WeakMap();
  let specDepNext = 1;

  // Identity marker for heavyweight objects that are replaced wholesale
  // (detection) rather than mutated — cheaper than stringifying them.
  function specDepId(obj) {
    if (!obj || typeof obj !== 'object') return 0;
    if (!specDepIds.has(obj)) specDepIds.set(obj, specDepNext++);
    return specDepIds.get(obj);
  }

  function specPanelFingerprint() {
    const r = (p) => (p ? [Math.round(p.x * 1000), Math.round(p.y * 1000)] : 0);
    // US-096: the panel renders the measurement set, so the fingerprint that
    // decides whether to rebuild it must be taken over the same set — reading
    // the whole board here would rebuild on every construction-line drag, and
    // (worse) MISS the rebuild when a line's style is the only thing that
    // changed. `a.style` is in the bits below for exactly that reason: a
    // plain-to-zigzag conversion adds or removes a row without moving a pixel.
    const annBits = measurementAnnotations().map(a => [
      a.style,
      a.id, a.seq, a.text, a.type,
      r(a.start), r(a.end), r(a.midPoint),
      r(a.control1), r(a.control2), r(a.midHandleIn), r(a.midHandleOut),
      Array.isArray(a.points) ? a.points.map(pt => [r(pt.point), r(pt.handleIn), r(pt.handleOut)]) : 0,
    ]);
    const draftBits = state.autoMode.draftAnnotations.map(d => [
      d.id, d.seq, d.text, !!d.tdApproved, !!d.tdEdited, !!d.tdTouched,
      d.drawability, d.confidence, d.reason, d.uncertainty, d.reviewNotes,
    ]);
    const anchors = state.autoMode.anchors;
    return JSON.stringify([
      state.appMode,
      annBits,
      draftBits,
      state.pomSpecs,
      state.customPoms,
      state.calibration.unitsPerPx, state.calibration.unit,
      state.hiddenAnnIds, state.hiddenDraftIds,
      state.images.length,
      specDepId(state.autoMode.detection),
      anchors.length, anchors.filter(a => a && a.reviewRequired).length,
      // US-038 anchor visibility lives in its OWN floating panel, not the
      // exported Measurements panel — so it is deliberately NOT fingerprinted
      // here.
    ]);
  }

  // US-035: the three numeric column headers name the board's active unit.
  // Runs before the US-033 fingerprint skip — it's three textContent sets,
  // and calibration is fingerprinted so full rebuilds stay correct too.
  function updateSpecUnitHeaders() {
    const u = '(' + (state.calibration.unit || 'in') + ')';
    document.querySelectorAll('.specPanel thead .th-unit').forEach((elm) => {
      if (elm.textContent !== u) elm.textContent = u;
    });
  }

  function renderSpecPanel() {
    renderSpecCalNote();
    updateSpecUnitHeaders();
    // Only preserve focus when the user is mid-edit in a text field inside
    // the panel — annotation rows, template rows, and paired rows all
    // qualify. Draft rows have no editable inputs, so Approve / R/O buttons
    // must always allow a full rebuild — otherwise row badges and the
    // review-header counts go stale (e.g. Approved/Edited badges, the
    // "N approved" line in the panel header).
    const active = document.activeElement;
    const editingPanelField = active
      && el.specBody.contains(active)
      && (active.tagName === 'INPUT' || active.tagName === 'TEXTAREA')
      // The Add-POM inline form (US-011) also counts: rebuilding while the
      // TD types the new POM's name would destroy the half-typed entry.
      && !!(active.closest('tr[data-ann-id]') || active.closest('tr[data-pom-key]')
        || active.closest('tr.add-pom-row'));
    if (editingPanelField) {
      updateSpecHighlightOnly();
      return;
    }

    // US-033: nothing the table renders from changed — selection-only call.
    const fingerprint = specPanelFingerprint();
    if (fingerprint === lastSpecPanelFingerprint) {
      updateSpecHighlightOnly();
      return;
    }

    el.specBody.innerHTML = '';

    // Sticky visibility control row: renders whenever there is at least one
    // hideable line, offering "Hide all" (isolate the sketch) and, once
    // anything is hidden, "Show all" — each a one-click toggle so the TD can
    // reveal and re-hide lines while checking evidence.
    if (hideablePomCount() > 0) {
      el.specBody.appendChild(buildVisibilityControlRow());
    }

    // Auto Mode: render the 18-row draft review section first.
    const draftPomKeys = new Set();
    // Construction summary renders whenever a detection exists — the TD
    // lands in Manual mode after Apply (ADR 0008) and still needs to see
    // what the detector recognized. No-op on pure manual projects.
    renderConstructionSummary();

    if (state.appMode === 'auto') {
      renderAutoReviewHeader();
      const drafts = state.autoMode.draftAnnotations
        .slice()
        .sort((a, b) => (a.seq || 0) - (b.seq || 0));
      for (const draft of drafts) {
        el.specBody.appendChild(buildDraftRow(draft));
        const draftKey = String(draft.text != null ? draft.text : draft.seq);
        if (draftKey) draftPomKeys.add(draftKey);
      }
    }

    // Panel is now pre-populated with the 18 POM template rows, so the
    // "No measurements yet" placeholder is redundant.
    el.specEmpty.style.display = 'none';

    // Lookup by effective POM label so each slot can find its annotation.
    // US-096 / ADR 0055: rows come from the measurement set. A zigzag drawn to
    // document topstitching is construction, not a POM, and must not appear
    // here or in anything derived from here.
    const anns = measurementAnnotations();
    const annByPom = new Map();
    for (const ann of anns) annByPom.set(getLabelText(ann), ann);

    // Render one row per POM slot in POM order — every POM gets its own row,
    // including the band (1 & 2) and chest (3 & 4) pairs, which each show
    // their own description, 中文, TOL and Size L. Pairing still lives in the
    // rule data (it drives the POM 2/4 extension-stub geometry) but is no
    // longer merged into a single panel row. Uses the annotation when one
    // exists, else a template row so 中文 / TOL / Size L stay editable. In
    // Auto Mode, POMs covered by an outstanding draft skip their template row
    // so the draft review section is not duplicated.
    const renderedAnnIds = new Set();
    const templateOrder = Object.keys(POM_TEMPLATE).sort((a, b) => Number(a) - Number(b));
    for (const pomKey of templateOrder) {
      const ann = annByPom.get(pomKey) || null;
      if (ann) {
        el.specBody.appendChild(buildSingleSpecRow(ann));
        renderedAnnIds.add(ann.id);
      } else if (!draftPomKeys.has(pomKey)) {
        el.specBody.appendChild(buildTemplateSpecRow(pomKey));
      }
    }

    // Registered custom POMs (19+, US-011) render template-style rows right
    // after the core 18 — with or without a drawn line — so a TD can spec them
    // before drawing. A row with a line behaves exactly like a template POM.
    const customKeys = (state.customPoms || []).map(p => String(p.pom))
      .sort((a, b) => Number(a) - Number(b));
    for (const pomKey of customKeys) {
      const ann = annByPom.get(pomKey) || null;
      if (ann) {
        el.specBody.appendChild(buildSingleSpecRow(ann));
        renderedAnnIds.add(ann.id);
      } else if (!draftPomKeys.has(pomKey)) {
        const tr = buildTemplateSpecRow(pomKey);
        decorateCustomPomRow(tr, pomKey);
        el.specBody.appendChild(tr);
      }
    }

    // Any additional user-labeled annotations that fall outside 1..18
    // (unregistered custom labels, renamed labels) render after the template
    // block in POM-numerical order.
    const extras = anns
      .filter(a => !renderedAnnIds.has(a.id))
      .sort((a, b) => labelSortKey(a) - labelSortKey(b) || a.seq - b.seq);
    for (const ann of extras) {
      if (renderedAnnIds.has(ann.id)) continue;
      el.specBody.appendChild(buildSingleSpecRow(ann));
      renderedAnnIds.add(ann.id);
    }

    el.specBody.appendChild(buildAddPomRow());

    // Stored only after a COMPLETED rebuild — the focus-guard early return
    // above must never mark a skipped rebuild as up to date.
    lastSpecPanelFingerprint = fingerprint;
  }

  function renderSpecCalNote() {
    let note = 'Label a callout with its <b>POM number</b> (e.g. 8) to auto-fill its description and standard size-L value. Values are editable per style.';
    if (state.appMode === 'auto') {
      const det = state.autoMode.detection;
      const anchors = state.autoMode.anchors;
      const drafts = state.autoMode.draftAnnotations;
      if (drafts.length > 0) {
        note = 'Auto Mode — <b>review drafts</b>: approve, mark review-only, or drag endpoints to edit. Then <i>Apply Approved Lines</i>.';
      } else if (anchors.length > 0 && state.autoMode.anchorsHidden) {
        note = '<b>Auto Mode — POM lines applied.</b> Anchors are hidden. Click <b>Reset Anchors</b> to show and re-tune them, or <b>Detect</b> to start over.';
      } else if (anchors.length > 0) {
        const edited = anchors.filter(a => !a.autoFilled).length;
        note = '<b>Auto Mode — anchors placed.</b> ' + anchors.length + ' anchors' +
          (edited > 0 ? ' (' + edited + ' adjusted)' : ' (all auto-seeded)') +
          '. Drag any that look wrong, then click <b>Generate POM Drafts</b>.';
      } else if (det) {
        const pct = (det.coverage * 100).toFixed(1);
        const features = [];
        features.push('band');
        if (det.chestY != null) features.push('chest');
        if (det.cradleY != null) features.push('cradle');
        if (det.sideLeftX != null) features.push('seam L');
        if (det.sideRightX != null) features.push('seam R');
        if (det.apexLeft) features.push('apex L');
        if (det.apexRight) features.push('apex R');
        if (det.strapTop && det.strapBottom) features.push('strap');
        if (det.back && det.back.top && det.back.bottom) features.push('back center');
        const sym = det.symmetry != null ? ' • sym ' + Math.round(det.symmetry * 100) + '%' : '';
        const fit = det.quality != null
          ? ' • fit ' + (det.quality >= 0.65 ? 'A' : (det.quality >= 0.40 ? 'B' : 'C'))
          : '';
        let views = '';
        if (det.viewBoxes && det.viewBoxes.length > 1) {
          const frontOuter = det.viewBoxes.find(v => v && (v.viewRole === 'front_outer' || v.role === 'front'));
          const frontInner = det.viewBoxes.find(v => v && v.viewRole === 'front_inner');
          const back  = det.viewBoxes.find(v => v && (v.viewRole === 'back' || v.role === 'back'));
          if (frontOuter && back && frontInner) {
            views = ' • front outer + back + front inner identified';
          } else if (frontOuter && back) {
            views = ' • front outer + back identified';
          } else if (frontOuter) {
            views = ' • ' + det.viewBoxes.length + ' views, front outer identified';
          } else {
            views = ' • ' + det.viewBoxes.length + ' views, using #' + ((det.primaryViewIndex || 0) + 1);
          }
          if (det.viewRoleReviewRequired) views += ' • roles need review';
        }
        note = '<b>Auto Mode — detected sketch.</b> ' + det.sampleWidth + '×' + det.sampleHeight +
          ' • local offline vision' + views + ' • ' + pct + '% coverage' + sym + fit +
          (det.durationMs != null ? ' • ' + det.durationMs + 'ms' : '') +
          '<br><span class="muted">Features: ' + features.join(', ') +
          '</span>. Next: drag any wrong anchors, then <i>Generate POM Drafts</i>.';
      } else {
        note = 'Auto Mode — click <b>Detect Sketch</b> to estimate the bra shape, then anchors, then POM drafts.';
      }
    }
    // Scale status applies in every mode, so append it last — the Auto Mode
    // branch above rebuilds `note` from scratch and would otherwise drop it.
    if (state.calibration.unitsPerPx != null) {
      note += ' <b>Scale set</b> — Value shown in <b>' + state.calibration.unit + '</b>.';
    } else {
      note += ' <span class="muted">Value in px — use <b>Set Scale</b> for real units.</span>';
    }
    el.specCal.innerHTML = note;
  }

  // Read-only "Detected from sketch" summary (v1). Surfaces the construction
  // facts the detector already knows — detected views, the front-closure
  // placket signature (ADR 0023 junction tier), the cup model, and how many
  // anchors are flagged for review — so the TD sees what the tool recognized
  // before reading the 18 draft rows. Display-only in this slice; confirming
  // these as library style-feature evidence (LIBRARY_CONSTRUCTION_TAXONOMY.md
  // Tier A) is a later slice. Absence of the placket signature is reported as
  // "not found", never as a claim about the back closure.
  function renderConstructionSummary() {
    const det = state.autoMode.detection;
    if (!det) return;

    const parts = [];

    const roleLabels = { front_outer: 'front outer', front_inner: 'front inner', back: 'back' };
    const seen = [];
    for (const v of (Array.isArray(det.views) ? det.views : [])) {
      const label = roleLabels[v && (v.viewRole || v.role)];
      if (label && !seen.includes(label)) seen.push(label);
    }
    if (seen.length) {
      parts.push('<b>Views:</b> ' + escapeHtml(seen.join(' + '))
        + (det.viewRoleReviewRequired
          ? ' <span style="color:#b45309;font-weight:600">— roles need review</span>' : ''));
    }

    parts.push('<b>Closure:</b> ' + (det.cradleCfTopJunction
      ? 'front-closure signature (placket interrupts the CF seam) — '
        + '<span style="color:#b45309;font-weight:600">confirm</span>'
      : 'no front-closure signature found'));

    const cm = det.cupModel;
    if (cm) {
      const bits = [cm.side === 1 ? 'right cup' : (cm.side === -1 ? 'left cup' : 'cup')];
      if (cm.visibility) bits.push(cm.visibility + ' visibility');
      if (typeof cm.contourConfidence === 'number') bits.push('contour ' + cm.contourConfidence.toFixed(2));
      if (typeof cm.seamConfidence === 'number') bits.push('seam ' + cm.seamConfidence.toFixed(2));
      parts.push('<b>Cup:</b> ' + escapeHtml(bits.join(' · ')));
    }

    const anchors = state.autoMode.anchors;
    if (anchors.length) {
      const revCount = anchors.filter(a => a && a.reviewRequired).length;
      parts.push('<b>Anchors:</b> ' + (revCount ? revCount + ' flagged for review' : 'none flagged'));
    }

    const tr = document.createElement('tr');
    tr.className = 'draft-row';
    tr.style.background = 'transparent';
    const td = document.createElement('td');
    td.colSpan = SPEC_COL_COUNT;
    td.innerHTML = '<div class="construction-summary" style="background:#f0f9ff;'
      + 'border:1px solid #bae6fd;color:#0c4a6e;border-radius:6px;padding:6px 8px;'
      + 'margin:4px 0;font-size:12px;line-height:1.5">'
      + '<b>Detected from sketch</b><br>' + parts.join('<br>')
      + '</div>';
    tr.appendChild(td);
    el.specBody.appendChild(tr);
  }

  function renderAutoReviewHeader() {
    const auto = state.autoMode;
    const drafts = auto.draftAnnotations;
    const hasDrafts = drafts.length > 0;
    const hasErrors = !!(auto.validation && auto.validation.errors && auto.validation.errors.length);
    const hasWarnings = !!(auto.validation && auto.validation.warnings && auto.validation.warnings.length);
    const hasLastError = !!auto.lastError;
    // Nothing to review and nothing to report — skip the section entirely so
    // the applied board isn't cluttered with an empty "0 rows" header.
    if (!hasDrafts && !hasErrors && !hasWarnings && !hasLastError) return;

    const approvable = drafts.filter(d => !isReviewOnlyDraft(d) && !d.tdApproved);
    const highApprovable = approvable.filter(d => d.confidence === 'high');
    const approved = drafts.filter(d => d.tdApproved && !isReviewOnlyDraft(d)).length;
    const reviewOnly = drafts.filter(d => isReviewOnlyDraft(d)).length;

    const headerTr = document.createElement('tr');
    headerTr.className = 'draft-row';
    headerTr.style.background = 'transparent';
    const headerTd = document.createElement('td');
    headerTd.colSpan = SPEC_COL_COUNT;
    // Draft-review summary + bulk actions only when drafts are outstanding;
    // the error / warning blocks below render on their own.
    let html = '';
    if (hasDrafts) {
      html += '<div class="auto-review-head">' +
        '<b>Auto Mode draft review</b> — ' + drafts.length + ' row' + (drafts.length === 1 ? '' : 's') + ' • ' +
        approved + ' approved • ' + reviewOnly + ' review-only' +
        (auto.runId ? '<br><span style="font-weight:400">Run: ' + auto.runId + '</span>' : '') +
        '<div class="auto-review-bulk">' +
          '<button type="button" class="auto-bulk-btn" data-bulk="approve-all"' +
            (approvable.length === 0 ? ' disabled' : '') + '>' +
            'Approve all (' + approvable.length + ')' +
          '</button>' +
          '<button type="button" class="auto-bulk-btn" data-bulk="approve-high"' +
            (highApprovable.length === 0 ? ' disabled' : '') + '>' +
            'Approve high-confidence (' + highApprovable.length + ')' +
          '</button>' +
        '</div>' +
        '</div>';
    }

    if (auto.validation && auto.validation.errors && auto.validation.errors.length) {
      html += '<div class="auto-review-errors"><b>Validation errors</b><ul>' +
        auto.validation.errors.map(e => '<li>' + escapeHtml(e) + '</li>').join('') +
        '</ul></div>';
    }
    if (auto.validation && auto.validation.warnings && auto.validation.warnings.length) {
      html += '<div class="auto-review-errors" style="background:#fffbeb;border-color:#fde68a;color:#854d0e"><b>Warnings</b><ul>' +
        auto.validation.warnings.map(w => '<li>' + escapeHtml(w) + '</li>').join('') +
        '</ul></div>';
    }
    if (auto.lastError) {
      html += '<div class="auto-review-errors"><b>Last error</b><br>' +
        escapeHtml(auto.lastError) + '</div>';
    }
    headerTd.innerHTML = html;
    headerTd.querySelectorAll('[data-bulk]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const mode = btn.getAttribute('data-bulk');
        const targets = mode === 'approve-high' ? highApprovable : approvable;
        if (targets.length === 0) return;
        for (const d of targets) approveDraftAnnotation(d);
        pushHistoryIfChanged();
        updateUI();
        requestRender();
        showToast('Approved ' + targets.length + ' draft' + (targets.length === 1 ? '' : 's') + '.');
      });
    });
    headerTr.appendChild(headerTd);
    el.specBody.appendChild(headerTr);
  }

  // escapeHtml lives in src/ui/dialogs/core.js — one declaration for the whole
  // bundle. This file used to carry a byte-equivalent second copy; because every
  // part shares one scope, the later declaration silently won for BOTH call
  // sites, so editing either copy would have had a surprising blast radius.

  function buildDraftRow(draft) {
    const tr = document.createElement('tr');
    tr.dataset.draftId = draft.id;
    tr.classList.add('draft-row');
    if (isReviewOnlyDraft(draft)) tr.classList.add('review-only');
    if (draft.tdApproved) tr.classList.add('approved');
    if (state.selection.kind === 'draft' && state.selection.id === draft.id) {
      tr.classList.add('selected');
    }
    if (isDraftHidden(draft.id)) tr.classList.add('pom-hidden');
    tr.addEventListener('click', () => setSelection('draft', draft.id));

    const pomTd = document.createElement('td');
    const pomLabel = document.createElement('span');
    const draftKey = draft.text != null ? String(draft.text) : String(draft.seq);
    pomLabel.textContent = draftKey;
    pomLabel.style.fontWeight = '700';
    pomLabel.title = getPomTooltip(draftKey);
    pomTd.appendChild(pomLabel);
    appendVisibilityToggle(pomTd, {
      hidden: isDraftHidden(draft.id),
      onToggle: () => toggleDraftHidden(draft.id),
    });
    const status = document.createElement('span');
    status.className = 'draft-status';
    if (isReviewOnlyDraft(draft)) status.textContent = 'Review-only';
    else if (draft.tdApproved) status.textContent = 'Approved';
    else if (draft.tdEdited) status.textContent = 'Edited';
    else status.textContent = draft.drawability === 'APPROXIMATE' ? 'Approx' : 'Draft';
    pomTd.appendChild(status);

    const descTd = document.createElement('td');
    const descBody = document.createElement('div');
    descBody.className = 'spec-desc-text';
    const standardDesc = getPomInfo(draft.text || draft.seq).desc || '—';
    descBody.textContent = standardDesc;
    descBody.title = standardDesc;
    descTd.appendChild(descBody);
    const meta = document.createElement('div');
    meta.style.cssText = 'font-size:10.5px;color:#6b7280;margin-top:2px;line-height:1.35';
    const metaBits = [];
    if (draft.confidence) metaBits.push('conf: ' + draft.confidence);
    if (draft.reason) metaBits.push(draft.reason);
    if (draft.uncertainty && isReviewOnlyDraft(draft)) metaBits.push(draft.uncertainty);
    // Phase 7: the landmark-QA explanations behind a review-only demotion
    // (missing seam, no back view, inferred cup, …) so the TD sees the "why"
    // without opening the debug payload.
    if (isReviewOnlyDraft(draft) && Array.isArray(draft.reviewNotes)) {
      for (const note of draft.reviewNotes) metaBits.push(note);
    }
    if (metaBits.length) meta.textContent = metaBits.join(' • ');
    descTd.appendChild(meta);

    const actionsTd = document.createElement('td');
    actionsTd.colSpan = SPEC_COL_COUNT - 2;
    actionsTd.style.cssText = 'white-space:nowrap';

    const approveBtn = document.createElement('button');
    approveBtn.type = 'button';
    approveBtn.textContent = draft.tdApproved ? 'Approved' : 'Approve';
    approveBtn.disabled = isReviewOnlyDraft(draft) || draft.tdApproved;
    approveBtn.style.cssText = 'padding:3px 8px;font-size:11px;margin-right:4px';
    approveBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      blurActivePanelField();
      setSelection('draft', draft.id);
      approveDraftAnnotation(draft);
      pushHistoryIfChanged();
      updateUI();
      requestRender();
    });
    actionsTd.appendChild(approveBtn);

    const reviewBtn = document.createElement('button');
    reviewBtn.type = 'button';
    reviewBtn.textContent = 'R/O';
    reviewBtn.title = 'Mark this row REVIEW_ONLY';
    reviewBtn.disabled = isReviewOnlyDraft(draft);
    reviewBtn.style.cssText = 'padding:3px 8px;font-size:11px';
    reviewBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      blurActivePanelField();
      setSelection('draft', draft.id);
      markDraftReviewOnly(draft);
      pushHistoryIfChanged();
      updateUI();
      requestRender();
    });
    actionsTd.appendChild(reviewBtn);

    tr.appendChild(pomTd);
    tr.appendChild(descTd);
    tr.appendChild(actionsTd);
    return tr;
  }

  function blurActivePanelField() {
    // Drop focus off any input/button inside the spec panel so the next
    // renderSpecPanel pass is free to rebuild rows (Approve / R/O state).
    const active = document.activeElement;
    if (active && el.specBody.contains(active) && typeof active.blur === 'function') {
      active.blur();
    }
  }

  // US-028: live measured value. While an endpoint is dragged or key-nudged,
  // replace just that line's Value cell — a full renderSpecPanel rebuild per
  // mousemove/keystroke would steal focus from other panel fields and is
  // needlessly heavy. buildMeasuredValueCell keeps value, tolerance chip,
  // tooltip, and the 📏 re-calibrate button in one code path. The commit-time
  // renderSpecPanel (via pushHistoryIfChanged → updateUI) stays the backstop.
  function refreshMeasuredValueForAnnotation(annId) {
    const ann = state.annotations.find(a => a.id === annId) || null;
    if (!ann) return; // Auto-Mode drafts have no annotation spec row — no-op.
    const tr = el.specBody.querySelector('tr[data-ann-id="' + ann.id + '"]');
    if (!tr) return;
    const oldTd = tr.querySelector('.spec-td-value');
    if (!oldTd) return;
    tr.replaceChild(buildMeasuredValueCell(ann, getLabelText(ann)), oldTd);
  }

  function updateSpecHighlightOnly() {
    const rows = el.specBody.querySelectorAll('tr');
    rows.forEach((tr) => {
      const selId = state.selection.kind === 'annotation' ? String(state.selection.id) : null;
      const isAnnSel = selId != null
        && (selId === tr.dataset.annId || selId === tr.dataset.pairAnnId);
      const isDraftSel = state.selection.kind === 'draft' && String(state.selection.id) === tr.dataset.draftId;
      tr.classList.toggle('selected', isAnnSel || isDraftSel);
    });
  }

  // ---- src/ui/anchor-manager-panel.js ----
// The Anchor Manager: a floating, non-modal panel over the board for hiding,
// showing and isolating detected anchors while checking Auto Mode's accuracy.
// Extracted from src/ui/spec-panel.js — see the US-038 note below for why it
// is deliberately NOT part of the exported Measurements panel.
// Source part for app.js. Run `npm run build` after editing.

  // ---- US-038: Anchors visibility manager (its OWN floating panel) -------
  // Deliberately NOT part of the Measurements panel: measurements are the
  // exported spec; anchors are a testing / accuracy-checking aid that never
  // exports. The panel floats over the board (non-modal) and is opened from
  // the Auto toolbar "Anchors" button. Offers Hide all / Show all, per-group
  // hide, per-anchor hide, and Isolate ("show only one"); a row click selects
  // the pin on the canvas.

  function anchorGroupLabel(group) {
    const map = {
      axis: 'Center / cradle', band: 'Band', chest: 'Chest', 'inner-cup': 'Cup',
      side: 'Side seam', apex: 'Apex', strap: 'Straps', back: 'Back',
      neckline: 'Neckline (17)', armhole: 'Armhole (18)',
    };
    return map[group] || group;
  }

  function anchorMiniBtn(label, title, onClick, extraCss) {
    const b = document.createElement('button');
    b.type = 'button';
    b.textContent = label;
    b.title = title;
    b.style.cssText = 'border:1px solid #cbd5e1;background:#fff;border-radius:5px;'
      + 'cursor:pointer;font-size:11px;line-height:1;padding:2px 6px;color:#334155;'
      + (extraCss || '');
    b.addEventListener('click', (e) => { e.stopPropagation(); onClick(); });
    return b;
  }

  function isAnchorManagerOpen() {
    return !!(el.anchorManagerPanel && !el.anchorManagerPanel.hidden);
  }

  // Toolbar entry point: open the floating anchor panel (Auto Mode only).
  function openAnchorManager() {
    if (state.appMode !== 'auto') {
      showToast('Anchor management is available in Auto Mode.');
      return;
    }
    if (!state.autoMode.anchors.length) {
      showToast('Run Detect Sketch first to place anchors.');
      return;
    }
    if (!el.anchorManagerPanel) return;
    el.anchorManagerPanel.hidden = false;
    if (el.autoManageAnchorsBtn) el.autoManageAnchorsBtn.classList.add('active');
    renderAnchorManagerPanel();
  }

  function closeAnchorManager() {
    if (!el.anchorManagerPanel) return;
    el.anchorManagerPanel.hidden = true;
    if (el.autoManageAnchorsBtn) el.autoManageAnchorsBtn.classList.remove('active');
  }

  function toggleAnchorManager() {
    if (isAnchorManagerOpen()) closeAnchorManager();
    else openAnchorManager();
  }

  // Rebuild the floating panel body from the current anchor set + hidden
  // state. Called on open, on every in-panel action, and from updateUI while
  // open (so a fresh Detect / canvas pin selection stays in sync).
  function renderAnchorManagerPanel() {
    const panel = el.anchorManagerPanel;
    const body = el.anchorManagerBody;
    if (!panel || !body) return;
    // Anchors only exist in Auto Mode; auto-close if we left it or lost them.
    if (state.appMode !== 'auto' || !state.autoMode.anchors.length) {
      closeAnchorManager();
      return;
    }
    const anchors = state.autoMode.anchors;
    const nameByKind = Object.create(null);
    const groupByKind = Object.create(null);
    const groupOrder = [];
    for (const schema of ANCHOR_SCHEMA) {
      nameByKind[schema.kind] = schema.name || schema.kind;
      groupByKind[schema.kind] = schema.group || 'other';
      if (groupOrder.indexOf(schema.group) === -1) groupOrder.push(schema.group);
    }
    const hidden = (k) => isAnchorHidden(k);
    const visibleCount = anchors.filter(a => !hidden(a.kind)).length;
    if (el.anchorManagerCount) {
      el.anchorManagerCount.textContent = visibleCount + '/' + anchors.length + ' shown';
    }

    body.innerHTML = '';
    for (const group of groupOrder) {
      const groupAnchors = anchors.filter(a => groupByKind[a.kind] === group);
      if (!groupAnchors.length) continue;
      const groupKinds = groupAnchors.map(a => a.kind);
      const groupAllHidden = groupKinds.every(hidden);

      const gRow = document.createElement('div');
      gRow.style.cssText = 'display:flex;align-items:center;gap:8px;padding:4px 10px;'
        + 'font-size:11.5px;color:#475569;background:#f8fafc;border-top:1px solid #eef2f7;';
      const gName = document.createElement('span');
      gName.style.fontWeight = '600';
      gName.textContent = anchorGroupLabel(group) + ' (' + groupAnchors.length + ')';
      gRow.appendChild(gName);
      const gSpacer = document.createElement('span'); gSpacer.style.flex = '1'; gRow.appendChild(gSpacer);
      gRow.appendChild(anchorMiniBtn(groupAllHidden ? 'Show' : 'Hide',
        groupAllHidden ? 'Show this group' : 'Hide this group',
        () => { toggleAnchorGroup(groupKinds); renderAnchorManagerPanel(); }));
      body.appendChild(gRow);

      for (const anchor of groupAnchors) {
        const isHidden = hidden(anchor.kind);
        const aRow = document.createElement('div');
        aRow.style.cssText = 'display:flex;align-items:center;gap:8px;padding:4px 10px 4px 22px;'
          + 'font-size:12px;border-top:1px solid #f4f6fa;'
          + (state.autoMode.anchorSelectedId === anchor.id ? 'background:#eff6ff;' : '')
          + (isHidden ? 'opacity:.5;' : '');
        const dot = document.createElement('span');
        dot.style.cssText = 'width:8px;height:8px;border-radius:50%;flex:0 0 auto;'
          + 'background:' + anchorFillForConfidence(anchor.confidence) + ';'
          + 'border:1px solid rgba(15,23,42,.5);';
        aRow.appendChild(dot);
        const aName = document.createElement('span');
        aName.textContent = nameByKind[anchor.kind] || anchor.kind;
        aName.style.cssText = 'color:#0f172a;cursor:pointer;';
        aName.title = anchor.name + ' — click to select on the sketch';
        aRow.appendChild(aName);
        if (anchor.reviewRequired) {
          const flag = document.createElement('span');
          flag.textContent = 'review';
          flag.style.cssText = 'font-size:10px;color:#b45309;background:#fffbeb;'
            + 'border:1px solid #fde68a;border-radius:4px;padding:0 4px;';
          aRow.appendChild(flag);
        }
        const aSpacer = document.createElement('span'); aSpacer.style.flex = '1'; aRow.appendChild(aSpacer);
        aRow.appendChild(anchorMiniBtn('◎', 'Isolate — show only this anchor',
          () => { isolateAnchor(anchor.kind); renderAnchorManagerPanel(); }));
        aRow.appendChild(anchorMiniBtn(isHidden ? '+' : '×',
          isHidden ? 'Show this anchor' : 'Hide this anchor',
          () => { toggleAnchorHidden(anchor.kind); renderAnchorManagerPanel(); },
          isHidden ? 'color:#2563eb;' : 'color:#b91c1c;'));
        aName.addEventListener('click', (e) => {
          e.stopPropagation();
          if (isHidden) return;
          state.autoMode.anchorSelectedId = anchor.id;
          updateUI();
          requestRender();
          renderAnchorManagerPanel();
        });
        body.appendChild(aRow);
      }
    }
  }

  // ---- src/ui/main-page-data.js ----
// MAIN PAGE sheet — static rosters and pure helpers (US-068, ADR 0037).
// Source part for app.js. Run `npm run build` after editing.
//
// The data carried across verbatim from the tech pack's mod-main module: the
// field roster, the suggestion rosters mined from 52 historical packs, and the
// 47-entry Color Master List. No DOM, no state.mainPage mutation — the sheet
// state owner is main-page.js, the version sketches are in
// main-page-sketches.js, the field picker is in main-page-fields.js and the
// colorway picker is in main-page-colorways.js.
//
// MP_SHADE_RE and MP_FIELD_SPEC are built at top level, at load time, so this
// part must precede the rest of the main-page-* parts in
// scripts/source-parts.mjs.

  /* House colour master list — the 47 entries of Color_Master_List.xlsx,
     verbatim (Pantone code + TCX + name + CP suffix exactly as recorded), so
     what prints on the colorway row is the name the factory list already
     uses. */
  const MP_COLOR_MASTER = [
    'Default White', 'Default Black', '11-0110 TCX Buttercream (SonaShape Beige) CP',
    '11-0601 TCX Bright White CP', '11-1408 TCX Light Pink CP', '12-0811 TCX Dawn',
    '12-1007 TCX Pastel Rose Tan (SonaShape Almond)', '12-1110 TCX Nude Pink CP',
    '12-1304 TCX Light Pink CP', '12-4302 TCX Light Blue CP', '13-1010 TCX Light Beige CP',
    '13-1408 TCX Chintz Rose', '13-4200 TCX Omphadoles', '13-4202 TCX Light Blue CP',
    '13-5907 TCX Light Green CP', '14-0217 TCX Sage', '14-1212 TCX Nude Tan CP',
    '14-1712 TCX Dusty Rose', '14-1904 TCX Pink', '14-3206 TCX Light Purple CP',
    '14-3812 TCX Lilac Mist', '14-3926 TCX Lavender CP', '14-4202 TCX Light Blue CP',
    '14-4306 TCX Coral Blue CP', '15-1515 TCX Dusty Pink CP', '15-3207 TCX Mauve Mist',
    '16-3205 TCX Mauve Purple CP', '16-4121 TCX Blissful Blue', '16-5304 TCX Light Teal CP',
    '17-1230 TCX Moccha Mouse', '17-1328 TCX Tanzine', '18-1229 TCX Coffee CP',
    '18-3025 TCX Purple CP', '18-3211 TCX Dusty Purple CP', '18-4016 TCX Dark Gray CP',
    '19-1555 TCX Burgundy', '19-2524 TCX Magenta Purple CP', '19-3832 TCX French Navy',
    '19-3911 TCX Black Beauty CP', '19-4029 TCX Navy Blue CP', 'Moona Purple', 'Nude Beige',
    'Taupe (Zenalift Brown)', 'Zenchic Beige', 'Zenchic Blue', 'Zenchic Pink', 'Zenchic White',
  ];

  /* The master list carries no hex, and a Pantone TCX reference must not be
     guessed, so the chip is only a rough on-screen cue read off the colour
     words in the name. Names with no recognisable shade word (Dawn,
     Omphadoles, Tanzine) get a blank chip rather than an invented one. Never
     treat these as Pantone values. */
  const MP_SHADE_WORDS = [
    ['bright white', '#fdfdfd'], ['black beauty', '#15151a'], ['pastel rose tan', '#e3bfae'],
    ['light pink', '#f2c6cd'], ['nude pink', '#e8c0b4'], ['dusty pink', '#d69ba2'],
    ['dusty rose', '#c08a8c'], ['chintz rose', '#c98b8b'], ['light beige', '#e8dcc6'],
    ['nude beige', '#e0c9ae'], ['nude tan', '#d9b391'], ['light blue', '#bdd4e7'],
    ['coral blue', '#a8c3cf'], ['blissful blue', '#4a6f9c'], ['navy blue', '#1d2b4a'],
    ['french navy', '#22304f'], ['light green', '#c9dcbe'], ['light teal', '#a9cdcb'],
    ['light purple', '#cbb8dc'], ['dusty purple', '#8d7594'], ['mauve purple', '#8c6b81'],
    ['magenta purple', '#7c2f5a'], ['mauve mist', '#b99aa8'], ['lilac mist', '#cbbdd8'],
    ['dark gray', '#4a4a4f'], ['moccha mouse', '#8a7263'], ['buttercream', '#f4e9c8'],
    ['lavender', '#c3b3d9'], ['burgundy', '#6b1f2e'], ['coffee', '#5a4034'],
    ['taupe', '#8f8071'], ['sage', '#9aa887'], ['magenta', '#a02360'], ['purple', '#6a4a8c'],
    ['navy', '#1d2b4a'], ['beige', '#ddc9ab'], ['nude', '#d8ad8a'], ['tan', '#c99b73'],
    ['pink', '#e9b7bd'], ['rose', '#c98b8b'], ['teal', '#3f8f8b'], ['blue', '#3269a8'],
    ['green', '#557c57'], ['gray', '#8c8c8c'], ['grey', '#8c8c8c'], ['white', '#ffffff'],
    ['black', '#111111'], ['brown', '#70483c'], ['red', '#b82025'],
  ];

  // Whole words only — a substring match reads "tan" inside "Tanzine".
  const MP_SHADE_RE = MP_SHADE_WORDS.map(([w, hex]) =>
    [new RegExp('\\b' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b'), hex]);

  function mpShadeOf(name) {
    const s = String(name || '').toLowerCase();
    const hit = MP_SHADE_RE.find(([re]) => re.test(s));
    return hit ? hit[1] : '';
  }

  /* Bumped when the master list changes, so a project saved against an older
     library picks the new list up on open instead of keeping a stale one. */
  const MP_COLOR_LIB_ID = 'color-master-list-47';

  function mpDefaultColorLibrary() {
    return MP_COLOR_MASTER.map(n => ({ name: n, hex: mpShadeOf(n) }));
  }

  /* The shipped field roster, verbatim from the tech pack's own default
     mainpage island. Labels are editable, hence the bind-once-by-regex rule
     below. "Block Reference" is a row here (US-080/ADR 0047) — the layout FD
     works from prints it, so ADR 0037's "strip it like the source module
     does" no longer holds. */
  const MP_DEFAULT_FIELDS = [
    { label: 'Brand - 品牌', value: 'Crossian' },
    { label: 'Fashion Designer', value: 'TBC' },
    { label: 'Tech Pack Designer', value: 'TBC' },
    { label: 'Technical Designer', value: 'TBC' },
    { label: 'Product Type - 品类', value: 'Bra' },
    { label: 'Style No Breakdown - 风格号码分解', value: '' },
    { label: 'Base Size - 基础尺码', value: 'TBC' },
    { label: 'Size Range - 尺寸范围', value: 'TBC' },
    { label: 'Style No - 风格号码', value: 'TBC' },
    { label: 'Garment Description - 文胸分类', value: 'TBC' },
    { label: 'Range Name - 产品名', value: 'TBC' },
    { label: 'Season/Year - 季节/年', value: 'TBC' },
    { label: 'Tech Pack Creation date', value: '' },
    { label: 'Block Reference - 原版品', value: 'TBC' },
  ];

  /* US-080/ADR 0047: the breakdown row is not one value. The factory layout
     splits it under three headers, and `parts` is what a TD types into;
     `value` is kept in sync as the composite so every existing reader (the
     preview sheet, the workbook, anything later) keeps working off `value`
     alone. */
  const MP_BREAKDOWN_PARTS = [
    { key: 'prefix', head: 'style prefix' },
    { key: 'category', head: 'category #:' },
    { key: 'rangeNo', head: 'range no:' },
  ];
  const MP_BREAKDOWN_SEP = ' · ';

  /* Version sketches (US-080/ADR 0047). Two fixed slots per version, in the
     order the factory layout prints them. TD-supplied: the tool never adopts
     a Board photo (those carry POM lines) or a Construction image (annotated)
     on its own. */
  const MP_SKETCH_VARIANTS = ['lace', 'solid'];
  const MP_SKETCH_SLOTS = [
    { key: 'front', label: 'FRONT' },
    { key: 'back', label: 'BACK' },
  ];

  /* ---- Field suggestion rosters -------------------------------------------
     Lists live HERE, in code, not copied into the saved project the way
     colorLibrary is. colorLibrary has to be copied because each entry carries
     a derived hex; these carry nothing, so changing a roster means shipping a
     new build and every project opened in it sees the change at once — with
     no colorLibId-style migration guard and no way for a project to sit on a
     stale list. What a TD types that is NOT on a list is remembered per
     project in state.mainPage.fieldExtra: the rosters were inferred from 52
     historical packs and are known to be incomplete, so a list must never be
     a wall. */
  const MP_RANGE_NAMES = ['SofieLift', 'TrulySofty', 'Airnix', 'AmoraFit', 'CherishShape',
    'FormaLift', 'VeraComfort', 'JuliaLace', 'BiancaBra', 'AuraZip', 'MilaEase',
    'FeliciaBra', 'KiraForm'];
  const MP_ALPHA_SIZES = ['S', 'M', 'M2', 'L', 'L2', 'XL', '2XL', '3XL', '4XL', '5XL', '5XL2'];

  /* The 3 size-column sets found in the "Size Chart & Grading Rule-2026"
     sheet of the historical grading workbook, each tied to a different
     size-chart revision. shortLabel is derived (not hand-typed twice) so it
     can never drift from the sizes array it describes. Picking one here only
     writes the field — it does not reflow this tool's size run, which is
     owned by the Grading dialog (ADR 0037 non-goal). */
  const MP_SIZE_RANGE_PRESETS = [
    { id: 'sc2d-3a',
      sizes: ['S', 'M', 'L', 'XL', '2XL', '3XL', '4XL', '5XL', 'M2', 'L2', '2XL2', '3XL2', '4XL2', '5XL2', 'L3', '2XL3', '3XL3', '4XL3'] },
    { id: '22jun2026',
      sizes: ['S', 'M', 'L', 'XL', '2XL', '3XL', '4XL', '5XL', 'M2', 'L2', 'XL2', '2XL2', '3XL2', '4XL2', '5XL2'] },
    { id: 'sc1b',
      sizes: ['S', 'M', 'L', 'XL', '2XL', '3XL', '4XL', '5XL', '6XL', 'M2', 'L2', '2XL2', '3XL2', '4XL2', '5XL2', '6XL2'] },
  ];
  MP_SIZE_RANGE_PRESETS.forEach(p => { p.shortLabel = 'S–' + p.sizes[p.sizes.length - 1]; });

  /* Season and Style No are composed from what the project already knows, so
     the drift the historical scan found (bare year with no season, "1. 0",
     vA/VA, missing V) cannot be reintroduced by hand. */
  function mpSeasonOpts() {
    const y = new Date().getFullYear() % 100;
    return [0, 1, -1].flatMap(d => ['SS', 'AW']
      .map(s => s + String(((y + d) % 100 + 100) % 100).padStart(2, '0')));
  }
  function mpStyleNoOpts() {
    const nm = String(state.styleId || '').trim().replace(/\s+/g, '');
    return nm ? ['VA', 'VB'].map(v => nm + v + '-1.0') : [];
  }

  /* Bound to rows ONCE, by regex, never per render: the labels are
     contenteditable, so re-matching every render would unbind a row the
     moment someone retypes its label. Order matters — 'Style No Breakdown'
     must claim its row before the looser /Style No/.

     Breakdown suggests RANGE NAMES ONLY. In the source, offering the
     composite strings the old packs used ("Airnix · VB · 1.0") pushed that
     whole string into the style name and corrupted every sheet header — the
     roster stays narrow here for the same reason. */
  const MP_FIELD_SPEC = [
    // Writes the `style prefix` sub-cell, never the whole composite.
    { key: 'breakdown', re: /Style No Breakdown/i, part: 'prefix', values: () => MP_RANGE_NAMES },
    { key: 'fashionDes', re: /Fashion Designer/i, values: ['Diep Ngoc Do', 'Linh Tung Nguyen', 'Dung Phuong Vu', 'Linh Phuong Le Trinh', 'Phong Dong Nguyen', 'Tam Thien Duc Nguyen'] },
    { key: 'tpDes', re: /Tech Pack Designer/i, values: ['Linh Khanh Nguyen', 'Khanh Linh Nguyen', 'Nguyễn Thị Hồng Hạnh', 'Phong Dong Nguyen', 'Vy Truc Ngoc Vang'] },
    { key: 'techDes', re: /Technical Designer/i, values: ['Tuyen Van Bui', 'Nishani Kadupitige', 'Selly Pham', 'Nga Hang Thi Hoang'] },
    { key: 'productType', re: /Product Type/i, values: ['Bra'] },
    { key: 'baseSize', re: /Base Size/i, values: MP_ALPHA_SIZES },
    { key: 'sizeRange', re: /Size Range/i, values: () => MP_SIZE_RANGE_PRESETS.map(p => p.shortLabel) },
    { key: 'styleNo', re: /Style No/i, values: mpStyleNoOpts },
    { key: 'garmentDesc', re: /Garment Description/i, values: ['Front Closure Bra', 'Back Closure Bra', '2-in-1 Bra', 'Front Closure Comfort Bra', 'Breathable Side Opening Bra', 'Front Zip Closure Bra'] },
    { key: 'rangeName', re: /Range Name/i, extras: 'breakdown', values: () => MP_RANGE_NAMES },
    { key: 'season', re: /Season/i, values: mpSeasonOpts },
  ];

  // ---- src/ui/main-page-sketches.js ----
// MAIN PAGE sheet — version sketches (US-080, ADR 0047).
// Source part for app.js. Run `npm run build` after editing.
//
// The two fixed slots per version: the byte store that lives outside
// state.mainPage, the save/open round trip for those bytes, the upload/paste
// slot menu, and mpSketchRowHtml — the one markup builder shared with the
// Preview & Export sheet. The slot roster itself (MP_SKETCH_VARIANTS /
// MP_SKETCH_SLOTS) is in main-page-data.js; state.mainPage.sketches is seeded
// by ensureMainPage() in main-page.js, which also wires the slot clicks.

  /* Bytes deliberately live outside state.mainPage, like BOM board images:
     history clones state.mainPage on every field edit, and four
     full-resolution flats cloned 120 deep is a different order of memory.
     Every import mints a NEW id and nothing is ever evicted, so undo across a
     replaced slot still finds the previous image's bytes here. */
  const mpSketchDataById = new Map();
  let mpSketchSeq = 0;

  /* ---- Version sketches -------------------------------------------------- */

  function mpSketchVariant(variant) {
    return String(variant || '').toLowerCase() === 'lace' ? 'lace' : 'solid';
  }

  function mpSketchSlot(variant, i) {
    const mp = state.mainPage;
    if (!mp || !mp.sketches) return null;
    const slots = mp.sketches[mpSketchVariant(variant)] || [];
    return slots[i] || null;
  }

  function mpSketchDataURL(variant, i) {
    const slot = mpSketchSlot(variant, i);
    return (slot && mpSketchDataById.get(slot.id)) || '';
  }

  // Injects the bytes back for save; the runtime state stays byte-free.
  function mpSerializeForProject() {
    const out = state.mainPage ? clone(state.mainPage) : null;
    if (!out || !out.sketches) return out;
    MP_SKETCH_VARIANTS.forEach(v => {
      out.sketches[v] = (out.sketches[v] || []).map(slot => (slot && slot.id
        ? { ...slot, dataURL: mpSketchDataById.get(slot.id) || null }
        : null));
    });
    return out;
  }

  // The mirror of the above, on open: bytes into the map, state left clean.
  function mpLoadProjectState(rawMainPage) {
    state.mainPage = rawMainPage && typeof rawMainPage === 'object' ? clone(rawMainPage) : null;
    mpSketchDataById.clear();
    const raw = (rawMainPage && rawMainPage.sketches) || {};
    MP_SKETCH_VARIANTS.forEach(v => {
      (raw[v] || []).forEach(slot => {
        if (slot && slot.id && slot.dataURL) mpSketchDataById.set(String(slot.id), slot.dataURL);
      });
    });
    return ensureMainPage();   // drops the injected dataURLs from state again
  }

  async function mpSetSketch(variant, i, dataURL) {
    const mp = ensureMainPage();
    const key = mpSketchVariant(variant);
    if (!dataURL) {
      mp.sketches[key][i] = null;
    } else {
      /* aspect is measured once here, not at render time: the preview sheet
         and the workbook both need it before an <img> exists. */
      let aspect = 1;
      try {
        const img = await loadImageFromDataURL(dataURL);
        aspect = Math.max(0.01, (img.naturalWidth || 1) / (img.naturalHeight || 1));
      } catch (err) { /* unreadable image still gets a slot, at 1:1 */ }
      const id = 'mp-sk-' + key + '-' + i + '-' + (++mpSketchSeq);
      mpSketchDataById.set(id, dataURL);
      mp.sketches[key][i] = { id, aspect };
    }
    mpCloseSketchMenu();
    mpRenderSketches();
    // The Preview & Export sheet shows the same slots; repaint it if that is
    // the page in view (same rule restoreSnapshot follows).
    if (state.activePage === 'preview' && typeof renderPreviewPage === 'function') renderPreviewPage();
    pushHistoryIfChanged();
  }

  /* One builder for the page and the Preview & Export sheet, so the two can
     never disagree about what a version panel shows (ADR 0046 rule 5).
     `editable` adds the screen-only clear button and the empty-slot prompt. */
  function mpSketchRowHtml(variant, editable) {
    const key = mpSketchVariant(variant);
    return MP_SKETCH_SLOTS.map((slot, i) => {
      const dataURL = mpSketchDataURL(key, i);
      const ref = key + ':' + i;
      const body = dataURL
        ? '<img class="mp-sk-img" src="' + escapeHtml(dataURL) + '" alt="' + slot.label + ' sketch">'
        : '<span class="mp-sk-empty">' + (editable ? '＋ ' : '') + slot.label + '</span>';
      return '<div class="mp-sketch' + (dataURL ? ' mp-sk-filled' : '') + '"'
        + (editable ? ' data-mp-sk="' + ref + '" role="button" tabindex="0" title="Upload or paste the '
          + slot.label.toLowerCase() + ' technical flat"' : '')
        + '>' + body
        + '<span class="mp-sk-tag">' + slot.label + '</span>'
        + (editable && dataURL
          ? '<button type="button" class="mp-sk-x mp-screen-only" data-mp-sk-clear="' + ref
            + '" title="Remove this sketch">×</button>'
          : '')
        + '</div>';
    }).join('');
  }

  function mpRenderSketches() {
    Array.from(document.querySelectorAll('#mainPageOverlay .mp-sketchrow')).forEach(row => {
      row.innerHTML = mpSketchRowHtml(row.dataset.mpVariant, true);
    });
  }

  /* ---- Sketch slot menu (forked from the BOM material-photo trigger) ------
     Upload or paste only: offline, no catalog, no auto-adoption. */

  let mpSketchOpen = null;   // 'lace:0' while a slot menu is open

  function mpSketchMenuEl() {
    let menu = document.getElementById('mpSketchMenu');
    if (menu) return menu;
    menu = document.createElement('div');
    menu.id = 'mpSketchMenu';
    menu.className = 'mp-menu mp-sketch-menu';
    menu.hidden = true;
    menu.innerHTML = '<div class="mp-sk-hint">Technical flat for this version — prints on the MAIN PAGE sheet.</div>'
      + '<div class="mp-sk-actions">'
      + '<button type="button" data-mp-sk-upload title="Or Cmd/Ctrl+V to paste a copied image">Upload&hellip; / Paste</button>'
      + '<button type="button" data-mp-sk-remove>Remove</button></div>';
    document.body.appendChild(menu);
    const filePick = document.createElement('input');
    filePick.type = 'file';
    filePick.accept = 'image/*';
    filePick.hidden = true;
    menu.appendChild(filePick);
    const applyFile = (f, ref) => {
      if (!f || !ref || !/^image\//i.test(f.type)) return;
      const [variant, i] = ref.split(':');
      const rd = new FileReader();
      rd.onload = () => mpSetSketch(variant, +i, rd.result);
      rd.readAsDataURL(f);
    };
    filePick.addEventListener('change', () => {
      const f = filePick.files && filePick.files[0];
      const ref = mpSketchOpen;
      filePick.value = '';
      applyFile(f, ref);
    });
    menu.addEventListener('click', e => {
      if (!mpSketchOpen) return;
      if (e.target.closest('[data-mp-sk-upload]')) { filePick.click(); return; }
      if (e.target.closest('[data-mp-sk-remove]')) {
        const [variant, i] = mpSketchOpen.split(':');
        mpSetSketch(variant, +i, null);
      }
    });
    /* stopPropagation keeps the app's document-level paste router from also
       adopting the image as a Board sketch. */
    menu.addEventListener('paste', e => {
      if (!mpSketchOpen || !e.clipboardData) return;
      const it = Array.from(e.clipboardData.items)
        .find(x => x.kind === 'file' && /^image\//i.test(x.type));
      if (!it) return;
      const f = it.getAsFile();
      if (!f) return;
      e.preventDefault();
      e.stopPropagation();
      applyFile(f, mpSketchOpen);
    });
    menu.addEventListener('keydown', e => {
      if (e.key === 'Escape') { mpCloseSketchMenu(); return; }
      if (e.key !== 'Tab') e.stopPropagation();
    });
    return menu;
  }

  function mpOpenSketchMenu(ref, box) {
    mpCloseFldMenu();
    if (mpColorWrap) mpColorWrap.classList.remove('open');
    mpSketchOpen = ref;
    const menu = mpSketchMenuEl();
    menu.hidden = false;
    menu.tabIndex = -1;   // focusable, so the paste event targets the menu
    const r = box.getBoundingClientRect();
    menu.style.left = Math.max(8, Math.min(r.left, window.innerWidth - 260)) + 'px';
    menu.style.top = Math.min(r.bottom + 4, window.innerHeight - 110) + 'px';
    menu.focus();
  }

  function mpCloseSketchMenu() {
    const menu = document.getElementById('mpSketchMenu');
    if (menu) menu.hidden = true;
    mpSketchOpen = null;
  }

  // ---- src/ui/main-page-fields.js ----
// MAIN PAGE sheet — field table + field suggestion picker (US-068, ADR 0037;
// breakdown sub-cells US-080/ADR 0047).
// Source part for app.js. Run `npm run build` after editing.
//
// Renders the style-metadata rows and owns the one shared suggestion dropdown
// parked on <body>: search, diacritic-folded filtering, remember-a-new-value,
// apply. What a field IS lives in main-page-data.js (MP_FIELD_SPEC and its
// rosters); the colorway rows have their own near-identical but distinct
// picker in main-page-colorways.js; state.mainPage itself is owned by
// main-page.js, which also builds and wires this menu's DOM in initMainPage().

  // Parallel to state.mainPage.fields; null where a row has no spec.
  let mpFieldSpec = [];
  let mpSpecRowCount = -1;
  let mpFldMenu = null;   // the one shared field picker, parked on <body>
  let mpFldOpen = null;   // {i, sp, btn} while a picker is open
  let mpFldFlat = [];     // options currently listed, indexed by data-mp-opt

  function mpResolveSpecs() {
    const f = (state.mainPage && state.mainPage.fields) || [];
    const taken = new Set();
    mpFieldSpec = f.map(() => null);
    MP_FIELD_SPEC.forEach(sp => {
      const i = f.findIndex((row, idx) => !taken.has(idx) && sp.re.test((row && row.label) || ''));
      if (i === -1) return;
      taken.add(i);
      mpFieldSpec[i] = sp;
    });
    mpSpecRowCount = f.length;
  }

  function mpFieldsEl() { return document.getElementById('mp-fields'); }

  function mpRenderFields() {
    const host = mpFieldsEl();
    if (!host) return;
    const fields = (state.mainPage && state.mainPage.fields) || [];
    if (fields.length !== mpSpecRowCount) mpResolveSpecs();
    host.innerHTML = fields.map((f, i) => {
      const isBrand = /^\s*Brand\b/i.test(f.label || '');
      const isDate = /Tech Pack Creation date/i.test(f.label || '');
      const isBreakdown = !!(mpFieldSpec[i] && mpFieldSpec[i].part && f.parts);
      const fixed = isBrand ? 'mp-fixed mp-brand-value' : (isDate ? 'mp-fixed mp-date-value' : '');
      const valueMarkup = isBrand ? '<strong>' + escapeHtml(f.value) + '</strong>' : escapeHtml(f.value);
      /* The sub-headers ride in their own row above the value, exactly as the
         factory layout prints them — they are captions, not data, so they are
         not editable and carry no data-i. */
      const headRow = isBreakdown
        ? '<tr class="mp-bd-headrow"><th class="mp-bd-blank"></th>'
          + '<td class="mp-bdhead">'
          + MP_BREAKDOWN_PARTS.map(p => '<span>' + escapeHtml(p.head) + '</span>').join('')
          + '</td><td class="act mp-screen-only mp-act"></td></tr>'
        : '';
      const valueCell = isBreakdown
        ? '<td class="mp-bdcell">'
          + MP_BREAKDOWN_PARTS.map(p => '<span class="mp-bd-sub" contenteditable spellcheck="false"'
            + ' data-i="' + i + '" data-f="part" data-part="' + p.key + '">'
            + escapeHtml(String(f.parts[p.key] || '')) + '</span>').join('')
          + '</td>'
        : '<td' + (fixed ? ' class="' + fixed + '" aria-readonly="true"' : ' contenteditable spellcheck="false"')
          + ' data-i="' + i + '" data-f="value">' + valueMarkup + '</td>';
      return headRow
        + '<tr><th contenteditable spellcheck="false" data-i="' + i + '" data-f="label">'
        + escapeHtml(f.label) + '</th>'
        + valueCell
        /* The trigger gets its own cell and never goes inside the value td:
           the input listener below stores the value cell's whole textContent,
           so a button living in it would be typed into the field. */
        + '<td class="act mp-screen-only mp-act">'
        + (mpFieldSpec[i]
          ? '<button type="button" class="mp-dd" data-mp-dd="' + i + '" tabindex="-1"'
            + ' title="Suggestions — you can still type straight into the cell"></button>'
          : '')
        + '</td></tr>';
    }).join('');
  }

  /* ---- Field picker ------------------------------------------------------ */

  function mpCurrentValue(i) {
    const f = (state.mainPage && state.mainPage.fields) || [];
    const row = f[i] || {};
    const part = mpFieldSpec[i] && mpFieldSpec[i].part;
    if (part) return String((row.parts || {})[part] || '');
    return String(row.value || '');
  }

  /* Diacritic-folded, so "nguyen thi hong hanh" finds "Nguyễn Thị Hồng Hạnh".
     Every token must appear somewhere, as in mpColorMatches(), so word order
     and the Vietnamese habit of reordering name parts both stop mattering. */
  function mpFold(s) {
    return String(s).toLowerCase().normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '').replace(/\u0111/g, 'd');
  }

  function mpOptionsFor(sp) {
    const base = (typeof sp.values === 'function' ? sp.values() : (sp.values || [])).map(String);
    const key = sp.extras || sp.key;
    const seen = new Set(base.map(v => v.toLowerCase()));
    const extra = ((state.mainPage.fieldExtra || {})[key] || [])
      .filter(v => !seen.has(String(v).toLowerCase()));
    return base.concat(extra);
  }

  function mpRememberExtra(sp, v) {
    const key = sp.extras || sp.key;
    const store = state.mainPage.fieldExtra || (state.mainPage.fieldExtra = {});
    const list = store[key] || (store[key] = []);
    if (v && !list.some(x => String(x).toLowerCase() === v.toLowerCase())) list.push(v);
  }

  function mpRenderFldMenu() {
    if (!mpFldOpen || !mpFldMenu) return;
    const box = mpFldMenu.querySelector('.mm-list');
    const foot = mpFldMenu.querySelector('.mm-foot');
    const raw = (mpFldMenu.querySelector('.mm-q').value || '').trim();
    const q = mpFold(raw).split(/\s+/).filter(Boolean);
    const cur = mpCurrentValue(mpFldOpen.i).toLowerCase();
    mpFldFlat = mpOptionsFor(mpFldOpen.sp).filter(v => q.every(t => mpFold(v).includes(t)));
    // Indices only in the attribute; the raw query is read back off .mm-q at
    // click time, never round-tripped through markup.
    let html = mpFldFlat.map((v, n) =>
      '<button type="button" data-mp-opt="' + n + '"' + (cur === v.toLowerCase() ? ' class="mm-on"' : '') + '>'
      + '<span class="mm-name">' + escapeHtml(v) + '</span></button>').join('');
    /* Looser than the colour menu, which only offers the free row when
       nothing matched: these rosters are known-incomplete, so typing "Selly"
       must still be able to mean a NEW Selly instead of being swallowed by
       "Selly Pham". */
    if (raw && !mpFldFlat.some(v => v.toLowerCase() === raw.toLowerCase())) {
      html += '<button type="button" data-mp-free><span class="mm-name">＋ Add “'
        + escapeHtml(raw) + '” (off the list)</span></button>';
    }
    html += '<button type="button" data-mp-clear><span class="mm-name">－ Leave blank</span></button>';
    box.innerHTML = html;
    foot.textContent = raw
      ? mpFldFlat.length + ' match · Enter picks the first'
      : mpFldFlat.length + ' suggestions · type to filter, or type a new value';
  }

  function mpOpenFldMenu(i, btn) {
    const sp = mpFieldSpec[i];
    if (!sp || !mpFldMenu) return;
    // Only one picker at a time: the overlay's click handler returns early on
    // a trigger hit, so it never reaches the close-the-colour-menu branch.
    if (mpColorWrap) mpColorWrap.classList.remove('open');
    mpFldOpen = { i, sp, btn };
    mpFldMenu.querySelector('.mm-q').value = '';
    mpRenderFldMenu();
    const r = btn.getBoundingClientRect();     // fixed positioning — no scroll maths
    const width = 300;
    mpFldMenu.style.left = Math.max(6, Math.min(r.right - width, window.innerWidth - width - 6)) + 'px';
    mpFldMenu.classList.add('open');
    const h = mpFldMenu.offsetHeight;
    const below = window.innerHeight - r.bottom;
    mpFldMenu.style.top = (below > h + 8 || r.top < h + 8 ? r.bottom + 4 : r.top - h - 4) + 'px';
    mpFldMenu.querySelector('.mm-q').focus();
  }

  function mpCloseFldMenu(refocus) {
    if (!mpFldMenu) return;
    mpFldMenu.classList.remove('open');
    const b = mpFldOpen && mpFldOpen.btn;
    mpFldOpen = null;
    if (refocus && b && document.contains(b)) b.focus();
  }

  function mpApplyFld(v) {
    if (!mpFldOpen) return;
    const i = mpFldOpen.i;
    const row = (state.mainPage.fields || [])[i] || {};
    const part = mpFldOpen.sp && mpFldOpen.sp.part;
    const label = (row.label || '') + (part ? ' · ' + part : '');
    if (part) {
      row.parts = row.parts || {};
      row.parts[part] = v;
      mpSyncBreakdown(row);
    } else {
      row.value = v;
    }
    mpRenderFields();
    pushHistoryIfChanged();
    mpCloseFldMenu(true);
    showToast(label + ': ' + (v || '(blank)') + ' · Ctrl/Cmd+Z to undo');
  }

  // ---- src/ui/main-page-colorways.js ----
// MAIN PAGE sheet — colorway rows + the Color Master List picker (US-068,
// ADR 0037; BOM columns US-072/ADR 0041).
// Source part for app.js. Run `npm run build` after editing.
//
// Adds, removes and renders state.mainPage.colorways, and owns the searchable
// colour menu hung off the sheet bar's "Add colour" button. The master list
// and the shade→chip inference are in main-page-data.js; the field rows have
// their own separate picker in main-page-fields.js; state.mainPage is seeded
// by ensureMainPage() in main-page.js, which also wires the menu's input.
//
// Read mpRemoveColor's comment before touching the `col` labels: BOM keys its
// per-row cwOverride by them.

  let mpColorWrap = null;
  let mpColorMenu = null;

  function mpCwTables() { return Array.from(document.querySelectorAll('table.mp-cwx')); }

  function mpRenderCw() {
    const rows = (state.mainPage && state.mainPage.colorways) || [];
    mpCwTables().forEach(t => {
      t.innerHTML = rows.map((c, i) =>
        '<tr><th>' + escapeHtml(c.col || ('COL ' + (i + 1))) + '</th>'
        + '<td contenteditable spellcheck="false" data-cw="' + i + '">' + escapeHtml(c.value) + '</td>'
        + '<td class="act mp-screen-only"><button type="button" data-rm="' + i + '" title="Remove this colorway">×</button></td></tr>').join('');
    });
    mpRenderColorMenu();   // keeps the "already used" marks in the picker honest
  }

  /* Every token of the query has to appear somewhere in the entry, so
     "14-38 lilac" and "lilac 14-38" both find 14-3812 TCX Lilac Mist. */
  function mpColorMatches(name, query) {
    const s = String(name).toLowerCase();
    return query.every(t => s.includes(t));
  }

  function mpRenderColorMenu() {
    if (!mpColorMenu) return;
    const box = mpColorMenu.querySelector('.cm-list');
    const foot = mpColorMenu.querySelector('.cm-foot');
    const raw = (mpColorMenu.querySelector('.cm-q').value || '').trim();
    const query = raw.toLowerCase().split(/\s+/).filter(Boolean);
    const lib = (state.mainPage && state.mainPage.colorLibrary) || [];
    const used = new Set(((state.mainPage && state.mainPage.colorways) || [])
      .map(c => String(c.value || '').toLowerCase()));
    const hits = lib.map((c, i) => ({ c, i })).filter(h => mpColorMatches(h.c.name, query));
    box.innerHTML = hits.map(({ c, i }) =>
      '<button type="button" data-color-choice="' + i + '"'
      + (used.has(String(c.name).toLowerCase()) ? ' class="cm-on" title="Already in the colorway list"' : '') + '>'
      + '<span class="mp-chip" style="--chip:' + escapeHtml(c.hex || 'transparent') + '"></span>'
      + '<span class="cm-name">' + escapeHtml(c.name || 'TBC') + '</span></button>').join('')
      // anything not on the house list can still be added by hand
      || (raw
        ? '<button type="button" class="cm-new" data-color-free>'
          + '<span class="mp-chip" style="--chip:transparent"></span>'
          + '<span class="cm-name">＋ Add “' + escapeHtml(raw) + '” (off the master list)</span></button>'
        : '<div class="cm-empty">No colour matches</div>');
    foot.textContent = raw
      ? hits.length + '/' + lib.length + ' colours match · Enter picks the first'
      : lib.length + ' colours in the Color Master List · type to search';
  }

  function mpAddColor(choice) {
    const mp = ensureMainPage();
    const picked = choice || { name: 'TBC', hex: '' };
    mp.colorways.push({
      col: 'COL ' + (mp.colorways.length + 1),
      value: picked.name || 'TBC',
      hex: picked.hex || '',
    });
    if (mpColorWrap) mpColorWrap.classList.remove('open');
    if (mpColorMenu) mpColorMenu.querySelector('.cm-q').value = '';
    mpRenderCw();
    pushHistoryIfChanged();
    showToast('Added ' + mp.colorways[mp.colorways.length - 1].col + ': ' + (picked.name || 'TBC'));
  }

  /* US-072/ADR 0041: BOM table columns now read state.mainPage.colorways
     directly (col/value), so removing a colorway does change what BOM
     shows — but col labels are renumbered below, and a BOM row's
     cwOverride is keyed by col label, not by a stable colorway id, so an
     override keyed 'COL 2' stays orphaned under the old label if a
     colorway ahead of it is removed. Accepted limitation: no remap pass
     exists, same as this function never remapped anything before BOM
     existed. */
  function mpRemoveColor(i) {
    const mp = ensureMainPage();
    if (!mp.colorways[i]) return;
    mp.colorways.splice(i, 1);
    mp.colorways.forEach((c, j) => { c.col = 'COL ' + (j + 1); });
    mpRenderCw();
    pushHistoryIfChanged();
  }

  // ---- src/ui/main-page.js ----
// MAIN PAGE sheet: state owner + DOM wiring (US-068, ADR 0037).
// Source part for app.js. Run `npm run build` after editing.
//
// Rebuilt on this tool's primitives from the tech pack's mod-main module —
// the Pack.* runtime does not exist here (ADR 0037). This part seeds and
// migrates state.mainPage, renders the sheet, and binds every delegated
// event; the pieces it composes live in the sibling parts loaded before it:
// main-page-data.js (rosters, Color Master List), main-page-sketches.js
// (version sketches), main-page-fields.js (field table + suggestion picker),
// main-page-colorways.js (colorway rows + colour picker).
//
// Style metadata only: no anchor, no POM, no view, so detection never reads
// it. state.mainPage is seeded lazily by ensureMainPage() so state.js does
// not carry 47 colour rows.

  function mpIsoToday() {
    const d = new Date(), p = n => String(n).padStart(2, '0');
    return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
  }

  /* Composite kept in sync from the parts, never typed directly. Empty parts
     drop out, so a breakdown with only a prefix reads "LiftyBliss" and not
     "LiftyBliss ·  · ". */
  function mpBreakdownValue(parts) {
    return MP_BREAKDOWN_PARTS
      .map(p => String((parts || {})[p.key] || '').trim())
      .filter(Boolean)
      .join(MP_BREAKDOWN_SEP);
  }

  function mpSyncBreakdown(field) {
    if (!field) return;
    field.value = mpBreakdownValue(field.parts);
  }

  /* A project saved before US-080 has one free-text breakdown value. It
     becomes the prefix — the historical packs put the range name there — and
     the placeholder 'TBC' is dropped rather than carried into a sub-cell. */
  function mpEnsureBreakdown(mp) {
    const i = mp.fields.findIndex(f => /Style No Breakdown/i.test((f && f.label) || ''));
    if (i === -1) return;
    const f = mp.fields[i];
    if (!f.parts || typeof f.parts !== 'object') {
      const legacy = String(f.value || '').trim();
      f.parts = {
        prefix: /^tbc$/i.test(legacy) ? '' : legacy,
        category: '',
        rangeNo: '',
      };
    }
    MP_BREAKDOWN_PARTS.forEach(p => {
      if (typeof f.parts[p.key] !== 'string') f.parts[p.key] = '';
    });
    mpSyncBreakdown(f);
  }

  // Seeds state.mainPage in place and migrates a project saved against an
  // older colour library. Safe to call repeatedly.
  function ensureMainPage() {
    const mp = state.mainPage && typeof state.mainPage === 'object'
      ? state.mainPage
      : (state.mainPage = {});
    if (!Array.isArray(mp.fields) || !mp.fields.length) {
      mp.fields = MP_DEFAULT_FIELDS.map(f => ({ ...f }));
    }
    /* Appended, not inserted by index: labels are editable, so a project can
       carry a reordered or renamed roster and there is no position to trust
       beyond "not present yet". */
    if (!mp.fields.some(f => /^Block Reference\b/i.test(String((f && f.label) || '').trim()))) {
      mp.fields.push({ ...MP_DEFAULT_FIELDS[MP_DEFAULT_FIELDS.length - 1] });
    }
    mpEnsureBreakdown(mp);
    if (!mp.sketches || typeof mp.sketches !== 'object') mp.sketches = {};
    MP_SKETCH_VARIANTS.forEach(v => {
      const slots = Array.isArray(mp.sketches[v]) ? mp.sketches[v] : [];
      mp.sketches[v] = MP_SKETCH_SLOTS.map((_, i) => {
        const s = slots[i];
        return s && typeof s === 'object' && s.id
          ? { id: String(s.id), aspect: Math.max(0.01, Number(s.aspect) || 1) }
          : null;
      });
    });
    const brand = mp.fields.find(f => /^\s*Brand\b/i.test(f.label || ''));
    if (brand) brand.value = 'Crossian';
    const created = mp.fields.find(f => /Tech Pack Creation date/i.test(f.label || ''));
    if (created && !/^\d{4}-\d{2}-\d{2}$/.test(String(created.value || '').trim())) {
      created.value = mpIsoToday();
    }
    if (!mp.fieldExtra || typeof mp.fieldExtra !== 'object') mp.fieldExtra = {};
    if (!Array.isArray(mp.colorways) || !mp.colorways.length) {
      mp.colorways = [
        { col: 'COL 1', value: 'Default White', hex: mpShadeOf('Default White') },
        { col: 'COL 2', value: 'Default Black', hex: mpShadeOf('Default Black') },
      ];
    }
    if (mp.colorLibId !== MP_COLOR_LIB_ID || !Array.isArray(mp.colorLibrary)) {
      mp.colorLibrary = mpDefaultColorLibrary();
      mp.colorLibId = MP_COLOR_LIB_ID;
    }
    if (typeof mp.provenance !== 'string') mp.provenance = '';
    mpResolveSpecs();
    return mp;
  }

  function renderMainPage() {
    if (!state.mainPage) return;
    mpRenderFields();
    mpRenderCw();
    mpRenderSketches();
    const prov = document.getElementById('mp-provenance');
    if (prov && prov !== document.activeElement) prov.textContent = state.mainPage.provenance || '';
  }

  /* ---- Wiring ------------------------------------------------------------ */
  // Sheet open/close now belongs to page-nav.js's setActivePage('mainpage' |
  // 'board') — the MAIN PAGE sheet is a peer page of the Board, not a modal
  // this file owns the visibility of.

  function initMainPage() {
    ensureMainPage();

    const overlay = document.getElementById('mainPageOverlay');
    if (!overlay) return;

    const printBtn = document.getElementById('mainPagePrintBtn');
    if (printBtn) printBtn.addEventListener('click', () => window.print());

    // Colour picker, hung off the "Add colour" button in the sheet bar.
    const addBtn = document.getElementById('mainPageAddColorBtn');
    if (addBtn) {
      mpColorWrap = addBtn.closest('.color-add-wrap');
      mpColorMenu = mpColorWrap && mpColorWrap.querySelector('.color-menu');
      if (mpColorMenu) {
        mpColorMenu.innerHTML = '<input type="search" class="cm-q" spellcheck="false" '
          + 'placeholder="Search colour — name or Pantone code (e.g. 14-38, dusty pink)">'
          + '<div class="cm-list"></div><div class="cm-foot"></div>';
        const q = mpColorMenu.querySelector('.cm-q');
        q.addEventListener('input', mpRenderColorMenu);
        /* The board's global keydown handler treats plain keys as tool
           shortcuts; a search input is not contenteditable, so without this a
           Backspace typed to fix a typo would reach the board. */
        q.addEventListener('keydown', e => {
          if (e.key !== 'Tab') e.stopPropagation();
          if (e.key === 'Escape') { mpColorWrap.classList.remove('open'); addBtn.focus(); return; }
          if (e.key !== 'Enter') return;
          e.preventDefault();
          const first = mpColorMenu.querySelector('.cm-list button');
          if (first) first.click();
        });
      }
      addBtn.addEventListener('click', () => {
        if (!mpColorWrap) return;
        mpCloseFldMenu();
        const open = mpColorWrap.classList.toggle('open');
        if (open && mpColorMenu) {
          const q = mpColorMenu.querySelector('.cm-q');
          q.value = '';
          mpRenderColorMenu();
          q.focus();
        }
      });
    }

    /* Parked on <body>, not inside the sheet, so it is never clipped by the
       scrolling sheet column. */
    mpFldMenu = document.createElement('div');
    mpFldMenu.id = 'mp-menu';
    mpFldMenu.className = 'mp-menu';
    mpFldMenu.setAttribute('role', 'menu');
    mpFldMenu.innerHTML =
      '<input type="search" class="mm-q" spellcheck="false" placeholder="Type to filter — or type a new value and press Enter">'
      + '<div class="mm-list"></div><div class="mm-foot"></div>';
    document.body.appendChild(mpFldMenu);
    mpFldMenu.addEventListener('keydown', e => { if (e.key !== 'Tab') e.stopPropagation(); });
    mpFldMenu.querySelector('.mm-q').addEventListener('input', mpRenderFldMenu);
    mpFldMenu.querySelector('.mm-q').addEventListener('keydown', e => {
      if (e.key === 'Escape') { mpCloseFldMenu(true); return; }
      if (e.key !== 'Enter') return;
      e.preventDefault();
      const first = mpFldMenu.querySelector('.mm-list button');
      if (first) first.click();
    });
    /* mousedown-preventDefault so the click never moves focus off the value
       cell before the option is applied. */
    mpFldMenu.addEventListener('mousedown', e => {
      if (e.target.closest('.mm-list button')) e.preventDefault();
    });
    mpFldMenu.addEventListener('click', e => {
      if (!mpFldOpen) return;
      const opt = e.target.closest('[data-mp-opt]');
      if (opt) { mpApplyFld(mpFldFlat[+opt.dataset.mpOpt]); return; }
      if (e.target.closest('[data-mp-free]')) {
        const raw = mpFldMenu.querySelector('.mm-q').value.trim();
        if (!raw) return;
        mpRememberExtra(mpFldOpen.sp, raw);
        mpApplyFld(raw);
        return;
      }
      if (e.target.closest('[data-mp-clear]')) mpApplyFld('');
    });
    window.addEventListener('resize', () => { if (mpFldOpen) mpCloseFldMenu(); });

    /* Delegated on the overlay, which survives every re-render — a listener
       on a cell or button would die on the next render. */
    overlay.addEventListener('input', e => {
      const cell = e.target.closest('#mp-fields [data-i]');
      if (cell) {
        const row = state.mainPage.fields[+cell.dataset.i];
        if (cell.dataset.f === 'part') {
          row.parts = row.parts || {};
          row.parts[cell.dataset.part] = cell.textContent.trim();
          mpSyncBreakdown(row);   // composite is derived, never typed
        } else {
          row[cell.dataset.f] = cell.textContent.trim();
        }
        return;
      }
      const cw = e.target.closest('table.mp-cwx [data-cw]');
      if (cw) {
        const idx = +cw.dataset.cw;
        state.mainPage.colorways[idx].value = cw.textContent.trim();
        // Both version panels show the same colorway list; mirror the edit
        // into the table the TD is not typing in.
        mpCwTables().forEach(t => {
          if (t.contains(cw)) return;
          const other = t.querySelector('[data-cw="' + idx + '"]');
          if (other) other.textContent = cw.textContent;
        });
        return;
      }
      if (e.target.id === 'mp-provenance') state.mainPage.provenance = e.target.textContent;
    });
    /* One history entry per field, not per keystroke: mutate on input, push
       on blur. pushHistoryIfChanged dedups by fingerprint, so a focus/blur
       with no edit is a no-op. */
    overlay.addEventListener('focusout', e => {
      if (e.target.closest('[contenteditable]')) pushHistoryIfChanged();
    });
    overlay.addEventListener('click', e => {
      const dd = e.target.closest('[data-mp-dd]');
      if (dd) {
        if (mpFldOpen && mpFldOpen.btn === dd) mpCloseFldMenu();
        else mpOpenFldMenu(+dd.dataset.mpDd, dd);
        return;
      }
      const rm = e.target.closest('table.mp-cwx [data-rm]');
      if (rm) { mpRemoveColor(+rm.dataset.rm); return; }
      // The clear button sits inside the slot box, so it has to win first.
      const skClear = e.target.closest('[data-mp-sk-clear]');
      if (skClear) {
        const [variant, i] = skClear.dataset.mpSkClear.split(':');
        mpSetSketch(variant, +i, null);
        return;
      }
      const sk = e.target.closest('[data-mp-sk]');
      if (sk) {
        if (mpSketchOpen === sk.dataset.mpSk) mpCloseSketchMenu();
        else mpOpenSketchMenu(sk.dataset.mpSk, sk);
        return;
      }
      if (mpSketchOpen && !e.target.closest('#mpSketchMenu')) mpCloseSketchMenu();
      const choice = e.target.closest('[data-color-choice]');
      if (choice) { mpAddColor(state.mainPage.colorLibrary[+choice.dataset.colorChoice]); return; }
      if (e.target.closest('[data-color-free]')) {
        const raw = mpColorMenu ? mpColorMenu.querySelector('.cm-q').value.trim() : '';
        if (raw) mpAddColor({ name: raw, hex: mpShadeOf(raw) });
        return;
      }
      if (mpColorWrap && !e.target.closest('.color-add-wrap')) mpColorWrap.classList.remove('open');
      if (mpFldOpen && !e.target.closest('#mp-menu,[data-mp-dd]')) mpCloseFldMenu();
    });
    overlay.addEventListener('keydown', e => {
      const sketch = e.target.closest('[data-mp-sk]');
      if (!sketch || (e.key !== 'Enter' && e.key !== ' ')) return;
      e.preventDefault();
      sketch.click();
    });
    document.addEventListener('keydown', e => {
      if (e.key !== 'Escape' || state.activePage !== 'mainpage') return;
      if (document.querySelector('.picker-overlay')) return;
      if (mpSketchOpen) { mpCloseSketchMenu(); return; }
      if (mpFldOpen) { mpCloseFldMenu(true); return; }
      if (mpColorWrap && mpColorWrap.classList.contains('open')) {
        mpColorWrap.classList.remove('open');
        return;
      }
      setActivePage('board');
    }, true);

    renderMainPage();
  }

